window.INKCRAFT_DIALOGUES = [{"lesson":1,"title":"Первое знакомство и состав ремонта","setting":"Первый визит к владельцу квартиры: ванная, кухня и перечень работ.","sentences":[{"speaker":"client","es":"Buenos días, gracias por venir a ver el piso.","ru":"Добрый день, спасибо, что приехали посмотреть квартиру.","pronunciation":"буэ́нос ди́ас, гра́сиас пор бэни́р а бэр эл пи́со.","id":"d01-001"},{"speaker":"serguei","es":"Hola, soy Serguéi, de INKCRAFT, y soy ingeniero.","ru":"Здравствуйте, я Сергей из INKCRAFT, я инженер.","pronunciation":"о́ла, сои сэргэ́й, дэ и́нккрафт, и сои инхэниэ́ро.","id":"d01-002"},{"speaker":"serguei","es":"Trabajo en reformas en Barcelona y también trabajo en Tarragona y la Costa Dorada.","ru":"Я занимаюсь ремонтом в Барселоне, а также работаю в Таррагоне и на Costa Dorada.","pronunciation":"траба́хо эн ррэфо́рмас эн барсэло́на и тамбиэ́н траба́хо эн тарраго́на и ла ко́ста дора́да.","id":"d01-003"},{"speaker":"client","es":"Soy el propietario de este piso y quiero preparar la reforma antes de entrar a vivir.","ru":"Я собственник квартиры и хочу подготовить ремонт до переезда.","pronunciation":"сои эл пропиэта́рио дэ э́стэ пи́со и киэ́ро прэпара́р ла ррэфо́рма а́нтэс дэ энтра́р а биби́р.","id":"d01-004"},{"speaker":"serguei","es":"Primero hablamos del baño, después de la cocina y al final del resto del piso.","ru":"Сначала обсудим ванную, затем кухню и в конце остальную квартиру.","pronunciation":"примэ́ро абла́мос дэл ба́ньо, дэспуэ́с дэ ла коси́на и ал фина́л дэл ррэ́сто дэл пи́со.","id":"d01-005"},{"speaker":"client","es":"El baño es pequeño, pero quiero cambiar los azulejos y también el lavabo.","ru":"Ванная маленькая, но я хочу поменять плитку и раковину.","pronunciation":"эл ба́ньо эс пэкэ́ньо, пэ́ро киэ́ро камбиа́р лос асулэ́хос и тамбиэ́н эл лаба́бо.","id":"d01-006"},{"speaker":"serguei","es":"¿Qué cambiamos en el baño y qué elementos conservamos?","ru":"Что меняем в ванной, а какие элементы сохраняем?","pronunciation":"кэ́ камбиа́мос эн эл ба́ньо и кэ́ элэмэ́нтос консэрба́мос?","id":"d01-007"},{"speaker":"client","es":"Cambiamos los azulejos de las paredes, el lavabo y las tuberías antiguas.","ru":"Меняем плитку на стенах, раковину и старые трубы.","pronunciation":"камбиа́мос лос асулэ́хос дэ лас парэ́дэс, эл лаба́бо и лас тубэри́ас анти́гуас.","id":"d01-008"},{"speaker":"serguei","es":"Entonces desmontamos el lavabo antiguo e instalamos el nuevo en la posición acordada.","ru":"Тогда демонтируем старую раковину и устанавливаем новую в согласованном месте.","pronunciation":"энто́нсэс дэсмонта́мос эл лаба́бо анти́гуо э инстала́мос эл нуэ́бо эн ла посисио́н акорда́да.","id":"d01-009"},{"speaker":"serguei","es":"¿Cambiamos también el suelo del baño o conservamos este suelo?","ru":"Пол в ванной тоже меняем или сохраняем этот?","pronunciation":"камбиа́мос тамбиэ́н эл суэ́ло дэл ба́ньо о консэрба́мос э́стэ суэ́ло?","id":"d01-010"},{"speaker":"client","es":"En el baño sí cambiamos el suelo, pero en el salón no cambiamos nada.","ru":"В ванной пол меняем, но в гостиной ничего не меняем.","pronunciation":"эн эл ба́ньо си́ камбиа́мос эл суэ́ло, пэ́ро эн эл сало́н но камбиа́мос на́да.","id":"d01-011"},{"speaker":"serguei","es":"Lo anoto por separado para que el presupuesto indique exactamente lo que hacemos en cada zona.","ru":"Запишу отдельно, чтобы смета точно показывала работы в каждой зоне.","pronunciation":"ло ано́то пор сэпара́до па́ра кэ эл прэсупуэ́сто инди́кэ эксактамэ́нтэ ло кэ асэ́мос эн ка́да со́на.","id":"d01-012"},{"speaker":"client","es":"El inodoro es nuevo y prefiero conservarlo si está en buen estado.","ru":"Унитаз новый, и я предпочитаю сохранить его, если он исправен.","pronunciation":"эл инодо́ро эс нуэ́бо и прэфиэ́ро консэрба́рло си эста́ эн буэн эста́до.","id":"d01-013"},{"speaker":"serguei","es":"Revisamos su estado y anotamos que no cambiamos el inodoro.","ru":"Проверим состояние и запишем, что унитаз не меняем.","pronunciation":"ррэбиса́мос су эста́до и анота́мос кэ но камбиа́мос эл инодо́ро.","id":"d01-014"},{"speaker":"client","es":"En la cocina quiero cambiar el fregadero y poner más enchufes junto a la encimera.","ru":"В кухне хочу поменять мойку и добавить розетки возле столешницы.","pronunciation":"эн ла коси́на киэ́ро камбиа́р эл фрэгадэ́ро и понэ́р ма́с энчу́фэс ху́нто а ла энсимэ́ра.","id":"d01-015"},{"speaker":"serguei","es":"¿Cambiamos las tuberías de la cocina o primero revisamos las que hay?","ru":"Трубы в кухне меняем или сначала проверяем существующие?","pronunciation":"камбиа́мос лас тубэри́ас дэ ла коси́на о примэ́ро ррэбиса́мос лас кэ аи?","id":"d01-016"},{"speaker":"client","es":"Primero las revisamos y después decidimos qué necesitamos cambiar.","ru":"Сначала проверим их, затем решим, что нужно заменить.","pronunciation":"примэ́ро лас ррэбиса́мос и дэспуэ́с дэсиди́мос кэ́ нэсэсита́мос камбиа́р.","id":"d01-017"},{"speaker":"serguei","es":"Los muebles de cocina se quedan, pero los protegemos antes de trabajar.","ru":"Кухонная мебель остаётся, но перед работами мы её защитим.","pronunciation":"лос муэ́блэс дэ коси́на сэ кэ́дан, пэ́ро лос протэхэ́мос а́нтэс дэ трабаха́р.","id":"d01-018"},{"speaker":"client","es":"¿Usted trabaja en reformas?","ru":"Вы занимаетесь ремонтом?","pronunciation":"устэ́д траба́ха эн ррэфо́рмас?","id":"d01-019"},{"speaker":"serguei","es":"Sí, trabajo en reformas.","ru":"Да, занимаюсь ремонтом.","pronunciation":"си́, траба́хо эн ррэфо́рмас.","id":"d01-020"},{"speaker":"client","es":"¿Cambia también los enchufes?","ru":"Вы также меняете розетки?","pronunciation":"ка́мбиа тамбиэ́н лос энчу́фэс?","id":"d01-021"},{"speaker":"serguei","es":"Sí, cambiamos los enchufes.","ru":"Да, меняем розетки.","pronunciation":"си́, камбиа́мос лос энчу́фэс.","id":"d01-022"},{"speaker":"client","es":"¿Cambiamos el inodoro?","ru":"Меняем унитаз?","pronunciation":"камбиа́мос эл инодо́ро?","id":"d01-023"},{"speaker":"serguei","es":"No, no cambiamos el inodoro.","ru":"Нет, унитаз не меняем.","pronunciation":"но, но камбиа́мос эл инодо́ро.","id":"d01-024"},{"speaker":"client","es":"¿Prepara un presupuesto?","ru":"Вы подготовите смету?","pronunciation":"прэпа́ра ун прэсупуэ́сто?","id":"d01-025"},{"speaker":"serguei","es":"Sí, preparo un presupuesto.","ru":"Да, подготовлю смету.","pronunciation":"си́, прэпа́ро ун прэсупуэ́сто.","id":"d01-026"},{"speaker":"client","es":"¿Hace reformas integrales?","ru":"Вы делаете комплексный ремонт?","pronunciation":"а́сэ ррэфо́рмас интэгра́лэс?","id":"d01-027"},{"speaker":"serguei","es":"Sí, coordinamos la reforma completa.","ru":"Да, координируем весь ремонт.","pronunciation":"си́, координа́мос ла ррэфо́рма комплэ́та.","id":"d01-028"},{"speaker":"client","es":"¿Trabaja con diseñadores?","ru":"Вы работаете с дизайнерами?","pronunciation":"траба́ха кон дисэньадо́рэс?","id":"d01-029"},{"speaker":"serguei","es":"Sí, ejecutamos sus proyectos.","ru":"Да, реализуем их проекты.","pronunciation":"си́, эхэкута́мос сус пройэ́ктос.","id":"d01-030"},{"speaker":"client","es":"También quiero pintar las paredes y los techos del pasillo y de los dos dormitorios.","ru":"Ещё хочу покрасить стены и потолки в коридоре и двух спальнях.","pronunciation":"тамбиэ́н киэ́ро пинта́р лас парэ́дэс и лос тэ́чос дэл паси́йо и дэ лос дос дормито́риос.","id":"d01-031"},{"speaker":"serguei","es":"Incluimos la preparación de las superficies y la pintura como trabajos separados en la propuesta.","ru":"Подготовку поверхностей и окраску включим в предложение отдельными работами.","pronunciation":"инклуи́мос ла прэпарасио́н дэ лас супэрфи́сиэс и ла пинту́ра ко́мо траба́хос сэпара́дос эн ла пропуэ́ста.","id":"d01-032"},{"speaker":"client","es":"¿Su equipo instala también las puertas o tengo que buscar otro profesional?","ru":"Ваша команда также устанавливает двери или нужно искать другого специалиста?","pronunciation":"су эки́по инста́ла тамбиэ́н лас пуэ́ртас о тэ́нго кэ буска́р о́тро профэсиона́л?","id":"d01-033"},{"speaker":"serguei","es":"Coordinamos esos trabajos y confirmamos cuáles están incluidos antes de empezar la obra.","ru":"Координируем эти работы и до начала подтверждаем, какие из них включены.","pronunciation":"координа́мос э́сос траба́хос и конфирма́мос куа́лэс эста́н инклуи́дос а́нтэс дэ эмпэса́р ла о́бра.","id":"d01-034"},{"speaker":"client","es":"Me interesa tener una sola persona de contacto para hablar de toda la reforma.","ru":"Мне важно иметь одно контактное лицо для обсуждения всего ремонта.","pronunciation":"мэ интэрэ́са тэнэ́р у́на со́ла пэрсо́на дэ конта́кто па́ра абла́р дэ то́да ла ррэфо́рма.","id":"d01-035"},{"speaker":"serguei","es":"Yo coordino los trabajos y le explico qué hacemos, qué falta decidir y qué necesita confirmación.","ru":"Я координирую работы и объясняю, что делаем, что осталось решить и что нужно подтвердить.","pronunciation":"йо коорди́но лос траба́хос и лэ экспли́ко кэ́ асэ́мос, кэ́ фа́лта дэсиди́р и кэ́ нэсэси́та конфирмасио́н.","id":"d01-036"},{"speaker":"client","es":"Entonces, ¿cuál es el siguiente paso para preparar el presupuesto del piso?","ru":"Тогда какой следующий шаг для подготовки сметы на квартиру?","pronunciation":"энто́нсэс, куа́л эс эл сигиэ́нтэ па́со па́ра прэпара́р эл прэсупуэ́сто дэл пи́со?","id":"d01-037"},{"speaker":"serguei","es":"Primero revisamos las zonas y tomamos medidas; después preparo un presupuesto con el alcance acordado.","ru":"Сначала осматриваем зоны и делаем замеры, затем готовлю смету с согласованным составом работ.","pronunciation":"примэ́ро ррэбиса́мос лас со́нас и тома́мос мэди́дас; дэспуэ́с прэпа́ро ун прэсупуэ́сто кон эл алка́нсэ акорда́до.","id":"d01-038"},{"speaker":"client","es":"Así puedo comprobar cada trabajo antes de tomar una decisión sobre la reforma.","ru":"Так я смогу проверить каждую работу, прежде чем принять решение о ремонте.","pronunciation":"аси́ пуэ́до компроба́р ка́да траба́хо а́нтэс дэ тома́р у́на дэсисио́н со́брэ ла ррэфо́рма.","id":"d01-039"},{"speaker":"serguei","es":"Sí, dejamos por escrito lo que cambiamos y también lo que conservamos.","ru":"Да, письменно фиксируем как то, что меняем, так и то, что сохраняем.","pronunciation":"си́, дэха́мос пор эскри́то ло кэ камбиа́мос и тамбиэ́н ло кэ консэрба́мос.","id":"d01-040"}],"words":402,"minutes":4},{"lesson":2,"title":"Осмотр квартиры, дефекты и замеры","setting":"Совместный обход квартиры: сырость у окна, трещины, неровный пол и размеры помещений.","sentences":[{"speaker":"serguei","es":"Buenos días, soy Serguéi, de INKCRAFT.","ru":"Добрый день, я Сергей из INKCRAFT.","pronunciation":"буэ́нос ди́ас, сои сэргэ́й, дэ и́нккрафт.","id":"d02-001"},{"speaker":"serguei","es":"Vamos a revisar el piso y tomar medidas.","ru":"Осмотрим квартиру и сделаем замеры.","pronunciation":"ба́мос а ррэбиса́р эл пи́со и тома́р мэди́дас.","id":"d02-002"},{"speaker":"serguei","es":"¿Puede enseñarme las zonas que quiere reformar?","ru":"Покажете зоны, которые хотите отремонтировать?","pronunciation":"пуэ́дэ энсэньа́рмэ лас со́нас кэ киэ́рэ ррэформа́р?","id":"d02-003"},{"speaker":"client","es":"Sí, pase, este es el recibidor.","ru":"Да, проходите, это прихожая.","pronunciation":"си́, па́сэ, э́стэ эс эл ррэсибидо́р.","id":"d02-004"},{"speaker":"client","es":"A la izquierda está el salón y a la derecha, la cocina.","ru":"Слева гостиная, а справа кухня.","pronunciation":"а ла искиэ́рда эста́ эл сало́н и а ла дэрэ́ча, ла коси́на.","id":"d02-005"},{"speaker":"serguei","es":"¿Dónde está el baño?","ru":"Где ванная?","pronunciation":"до́ндэ эста́ эл ба́ньо?","id":"d02-006"},{"speaker":"serguei","es":"¿Está al fondo del pasillo?","ru":"Она в конце коридора?","pronunciation":"эста́ ал фо́ндо дэл паси́йо?","id":"d02-007"},{"speaker":"client","es":"Sí, también hay dos dormitorios, un lavadero y una terraza.","ru":"Да, ещё есть две спальни, постирочная и терраса.","pronunciation":"си́, тамбиэ́н аи дос дормито́риос, ун лабадэ́ро и у́на тэрра́са.","id":"d02-008"},{"speaker":"client","es":"Pero primero quiero enseñarle una mancha en el salón.","ru":"Но сначала хочу показать вам пятно в гостиной.","pronunciation":"пэ́ро примэ́ро киэ́ро энсэньа́рлэ у́на ма́нча эн эл сало́н.","id":"d02-009"},{"speaker":"serguei","es":"¿Dónde está el problema?","ru":"Где проблема?","pronunciation":"до́ндэ эста́ эл проблэ́ма?","id":"d02-010"},{"speaker":"serguei","es":"¿Aquí, junto a la ventana?","ru":"Здесь, рядом с окном?","pronunciation":"аки́, ху́нто а ла бэнта́на?","id":"d02-011"},{"speaker":"client","es":"Sí, hay humedad en esta pared y un poco de moho detrás del mueble.","ru":"Да, на этой стене сырость, а за мебелью немного плесени.","pronunciation":"си́, аи умэда́д эн э́ста парэ́д и ун по́ко дэ мо́о дэтра́с дэл муэ́блэ.","id":"d02-012"},{"speaker":"serguei","es":"¿Desde cuándo aparece esta mancha?","ru":"С какого времени появляется это пятно?","pronunciation":"дэ́сдэ куа́ндо апарэ́сэ э́ста ма́нча?","id":"d02-013"},{"speaker":"serguei","es":"¿Aparece cuando llueve?","ru":"Оно появляется, когда идёт дождь?","pronunciation":"апарэ́сэ куа́ндо йуэ́бэ?","id":"d02-014"},{"speaker":"client","es":"Desde hace unos meses, sobre todo cuando llueve mucho.","ru":"Несколько месяцев, особенно когда сильный дождь.","pronunciation":"дэ́сдэ а́сэ у́нос мэ́сэс, со́брэ то́до куа́ндо йуэ́бэ му́чо.","id":"d02-015"},{"speaker":"client","es":"¿Por qué hay humedad?","ru":"Почему появилась сырость?","pronunciation":"пор кэ́ аи умэда́д?","id":"d02-016"},{"speaker":"client","es":"¿Es una fuga?","ru":"Это утечка?","pronunciation":"эс у́на фу́га?","id":"d02-017"},{"speaker":"serguei","es":"Puede haber varias causas.","ru":"Причин может быть несколько.","pronunciation":"пуэ́дэ абэ́р ба́риас ка́усас.","id":"d02-018"},{"speaker":"serguei","es":"Parece una filtración, pero hay que comprobarlo.","ru":"Похоже на просачивание воды, но нужно проверить.","pronunciation":"парэ́сэ у́на филтрасио́н, пэ́ро аи кэ компроба́рло.","id":"d02-019"},{"speaker":"serguei","es":"La pared está húmeda; todavía no sabemos la causa.","ru":"Стена влажная; причину мы пока не знаем.","pronunciation":"ла парэ́д эста́ у́мэда; тодаби́а но сабэ́мос ла ка́уса.","id":"d02-020"},{"speaker":"client","es":"¿Puede revisar también lo que hay detrás del mueble?","ru":"Можете также проверить, что за мебелью?","pronunciation":"пуэ́дэ ррэбиса́р тамбиэ́н ло кэ аи дэтра́с дэл муэ́блэ?","id":"d02-021"},{"speaker":"serguei","es":"Sí, pero necesitamos acceso para verlo bien.","ru":"Да, но для нормального осмотра нужен доступ.","pronunciation":"си́, пэ́ро нэсэсита́мос аксэ́со па́ра бэ́рло биэн.","id":"d02-022"},{"speaker":"serguei","es":"Primero revisamos la ventana y el encuentro con la fachada.","ru":"Сначала проверим окно и примыкание к фасаду.","pronunciation":"примэ́ро ррэбиса́мос ла бэнта́на и эл энкуэ́нтро кон ла фача́да.","id":"d02-023"},{"speaker":"serguei","es":"Después comprobamos la humedad con el medidor.","ru":"Затем измерим влажность прибором.","pronunciation":"дэспуэ́с компроба́мос ла умэда́д кон эл мэдидо́р.","id":"d02-024"},{"speaker":"client","es":"¿Y el techo, también está húmedo?","ru":"А потолок тоже влажный?","pronunciation":"и эл тэ́чо, тамбиэ́н эста́ у́мэдо?","id":"d02-025"},{"speaker":"serguei","es":"Ahora está seco; no veo manchas ni desprendimientos.","ru":"Сейчас он сухой; не вижу пятен или отслоений.","pronunciation":"ао́ра эста́ сэ́ко; но бэ́о ма́нчас ни дэспрэндимиэ́нтос.","id":"d02-026"},{"speaker":"serguei","es":"Voy a fotografiar esta zona y anotar lo que observamos.","ru":"Сфотографирую эту зону и запишу наши наблюдения.","pronunciation":"бои а фотографиа́р э́ста со́на и анота́р ло кэ обсэрба́мос.","id":"d02-027"},{"speaker":"client","es":"Allí hay una grieta, junto a la puerta.","ru":"Там трещина, рядом с дверью.","pronunciation":"айи́ аи у́на гриэ́та, ху́нто а ла пуэ́рта.","id":"d02-028"},{"speaker":"client","es":"¿Es una grieta importante?","ru":"Это серьёзная трещина?","pronunciation":"эс у́на гриэ́та импорта́нтэ?","id":"d02-029"},{"speaker":"serguei","es":"Todavía no puedo confirmarlo; primero revisamos su origen.","ru":"Пока не могу подтвердить; сначала выясним её происхождение.","pronunciation":"тодаби́а но пуэ́до конфирма́рло; примэ́ро ррэбиса́мос су ори́хэн.","id":"d02-030"},{"speaker":"serguei","es":"¿Sabe si esta pared es un tabique o un muro de carga?","ru":"Вы знаете, это перегородка или несущая стена?","pronunciation":"са́бэ си э́ста парэ́д эс ун таби́кэ о ун му́ро дэ ка́рга?","id":"d02-031"},{"speaker":"client","es":"No lo sé, creo que la pared es de ladrillo.","ru":"Не знаю, думаю, стена кирпичная.","pronunciation":"но ло сэ́, крэ́о кэ ла парэ́д эс дэ ладри́йо.","id":"d02-032"},{"speaker":"client","es":"También hay una fisura pequeña en el dormitorio.","ru":"В спальне тоже есть небольшая тонкая трещина.","pronunciation":"тамбиэ́н аи у́на фису́ра пэкэ́ньа эн эл дормито́рио.","id":"d02-033"},{"speaker":"serguei","es":"Vamos a revisar las dos.","ru":"Осмотрим обе.","pronunciation":"ба́мос а ррэбиса́р лас дос.","id":"d02-034"},{"speaker":"client","es":"El suelo es de madera, pero aquí parece más alto.","ru":"Пол деревянный, но здесь он кажется выше.","pronunciation":"эл суэ́ло эс дэ мадэ́ра, пэ́ро аки́ парэ́сэ ма́с а́лто.","id":"d02-035"},{"speaker":"client","es":"¿Hay un desnivel?","ru":"Есть перепад уровня?","pronunciation":"аи ун дэснибэ́л?","id":"d02-036"},{"speaker":"serguei","es":"Parece que sí; lo comprobamos con el nivel láser.","ru":"Похоже, да; проверим лазерным уровнем.","pronunciation":"парэ́сэ кэ си́; ло компроба́мос кон эл нибэ́л ла́сэр.","id":"d02-037"},{"speaker":"serguei","es":"También revisamos si hay abombamiento y falta de planeidad.","ru":"Также проверим, есть ли вздутие и отклонение от плоскости.","pronunciation":"тамбиэ́н ррэбиса́мос си аи абомбамиэ́нто и фа́лта дэ планэида́д.","id":"d02-038"},{"speaker":"client","es":"¿Cuánto mide el salón?","ru":"Какие размеры гостиной?","pronunciation":"куа́нто ми́дэ эл сало́н?","id":"d02-039"},{"speaker":"serguei","es":"Ahora lo medimos con el medidor láser.","ru":"Сейчас измерим лазерным дальномером.","pronunciation":"ао́ра ло мэди́мос кон эл мэдидо́р ла́сэр.","id":"d02-040"},{"speaker":"serguei","es":"Tiene tres metros veinte de ancho y cuatro metros cincuenta de largo: catorce coma cuatro metros cuadrados.","ru":"Ширина — 3,20 метра, длина — 4,50 метра: площадь 14,4 квадратного метра.","pronunciation":"тиэ́нэ трэс мэ́трос бэ́интэ дэ а́нчо и куа́тро мэ́трос синкуэ́нта дэ ла́рго: като́рсэ ко́ма куа́тро мэ́трос куадра́дос.","id":"d02-041"},{"speaker":"client","es":"¿Y qué altura tiene?","ru":"А какая высота?","pronunciation":"и кэ́ алту́ра тиэ́нэ?","id":"d02-042"},{"speaker":"serguei","es":"El techo está a dos metros sesenta.","ru":"Высота потолка — 2,60 метра.","pronunciation":"эл тэ́чо эста́ а дос мэ́трос сэсэ́нта.","id":"d02-043"},{"speaker":"serguei","es":"Ahora medimos el hueco de la puerta con la cinta métrica.","ru":"Теперь измерим дверной проём рулеткой.","pronunciation":"ао́ра мэди́мос эл уэ́ко дэ ла пуэ́рта кон ла си́нта мэ́трика.","id":"d02-044"},{"speaker":"client","es":"Vamos al baño, ¿cuántos metros cuadrados tiene?","ru":"Пойдёмте в ванную, сколько в ней квадратных метров?","pronunciation":"ба́мос ал ба́ньо, куа́нтос мэ́трос куадра́дос тиэ́нэ?","id":"d02-045"},{"speaker":"serguei","es":"Mide dos metros de ancho y dos de largo.","ru":"Ширина — два метра, длина — два.","pronunciation":"ми́дэ дос мэ́трос дэ а́нчо и дос дэ ла́рго.","id":"d02-046"},{"speaker":"serguei","es":"Según esta medición, tiene cuatro metros cuadrados.","ru":"По этому замеру площадь — четыре квадратных метра.","pronunciation":"сэгу́н э́ста мэдисио́н, тиэ́нэ куа́тро мэ́трос куадра́дос.","id":"d02-047"},{"speaker":"client","es":"Aquí también hay humedad, debajo del lavabo.","ru":"Здесь тоже сырость, под раковиной.","pronunciation":"аки́ тамбиэ́н аи умэда́д, дэба́хо дэл лаба́бо.","id":"d02-048"},{"speaker":"client","es":"¿Hay que cambiar todo?","ru":"Нужно всё менять?","pronunciation":"аи кэ камбиа́р то́до?","id":"d02-049"},{"speaker":"serguei","es":"Primero distinguimos lo que está bien de lo que necesita reparación.","ru":"Сначала отделим исправные части от того, что требует ремонта.","pronunciation":"примэ́ро дистинги́мос ло кэ эста́ биэн дэ ло кэ нэсэси́та ррэпарасио́н.","id":"d02-050"},{"speaker":"serguei","es":"Comprobamos si hay una fuga y después confirmamos el alcance.","ru":"Проверим, есть ли утечка, а затем подтвердим объём работ.","pronunciation":"компроба́мос си аи у́на фу́га и дэспуэ́с конфирма́мос эл алка́нсэ.","id":"d02-051"},{"speaker":"serguei","es":"¿Puede enseñarme también la terraza y el lavadero?","ru":"Покажете также террасу и постирочную?","pronunciation":"пуэ́дэ энсэньа́рмэ тамбиэ́н ла тэрра́са и эл лабадэ́ро?","id":"d02-052"},{"speaker":"client","es":"Sí, están por aquí.","ru":"Да, они здесь.","pronunciation":"си́, эста́н пор аки́.","id":"d02-053"},{"speaker":"client","es":"¿Podemos vivir aquí durante la obra?","ru":"Мы сможем жить здесь во время ремонта?","pronunciation":"подэ́мос биби́р аки́ дура́нтэ ла о́бра?","id":"d02-054"},{"speaker":"serguei","es":"Depende de las zonas afectadas y de los cortes de servicios; lo planificamos antes.","ru":"Это зависит от затронутых зон и отключений воды или электричества; заранее это спланируем.","pronunciation":"дэпэ́ндэ дэ лас со́нас афэкта́дас и дэ лос ко́ртэс дэ сэрби́сиос; ло планифика́мос а́нтэс.","id":"d02-055"},{"speaker":"client","es":"¿Puede decirme ya cuánto va a costar?","ru":"Можете уже сказать, сколько это будет стоить?","pronunciation":"пуэ́дэ дэси́рмэ йа куа́нто ба а коста́р?","id":"d02-056"},{"speaker":"serguei","es":"Sin revisar la zona no puedo confirmar el alcance.","ru":"Без осмотра зоны я не могу подтвердить объём работ.","pronunciation":"син ррэбиса́р ла со́на но пуэ́до конфирма́р эл алка́нсэ.","id":"d02-057"},{"speaker":"serguei","es":"Primero medimos; después confirmamos las cantidades.","ru":"Сначала измеряем, затем подтверждаем объёмы.","pronunciation":"примэ́ро мэди́мос; дэспуэ́с конфирма́мос лас кантида́дэс.","id":"d02-058"},{"speaker":"serguei","es":"Le envío las fotos, las medidas y una propuesta.","ru":"Отправлю фотографии, размеры и предложение.","pronunciation":"лэ энби́о лас фо́тос, лас мэди́дас и у́на пропуэ́ста.","id":"d02-059"},{"speaker":"client","es":"De acuerdo, esperamos las comprobaciones antes de decidir qué cambiamos.","ru":"Хорошо, дождёмся результатов проверки, прежде чем решать, что меняем.","pronunciation":"дэ акуэ́рдо, эспэра́мос лас компробасио́нэс а́нтэс дэ дэсиди́р кэ́ камбиа́мос.","id":"d02-060"}],"words":455,"minutes":5},{"lesson":3,"title":"Обсуждение проекта и планировки","setting":"Дизайн-проект, чертежи, размеры, материалы и согласование изменений.","sentences":[{"speaker":"client","es":"Buenos días, traigo el proyecto de interiorismo y unas imágenes de cómo quiero que quede el piso.","ru":"Добрый день, я принёс дизайн-проект и изображения того, как должна выглядеть квартира.","pronunciation":"буэ́нос ди́ас, тра́иго эл пройэ́кто дэ интэриори́смо и у́нас има́хэнэс дэ ко́мо киэ́ро кэ кэ́дэ эл пи́со.","id":"d03-001"},{"speaker":"serguei","es":"Ejecutamos el proyecto del diseñador y necesitamos trabajar con los planos actualizados.","ru":"Мы выполняем проект дизайнера, и нам нужны актуальные чертежи.","pronunciation":"эхэкута́мос эл пройэ́кто дэл дисэньадо́р и нэсэсита́мос трабаха́р кон лос пла́нос актуалиса́дос.","id":"d03-002"},{"speaker":"client","es":"Quiero unir la cocina con el salón y mantener los dos dormitorios con su distribución actual.","ru":"Хочу объединить кухню с гостиной и сохранить нынешнюю планировку двух спален.","pronunciation":"киэ́ро уни́р ла коси́на кон эл сало́н и мантэнэ́р лос дос дормито́риос кон су дистрибусио́н актуа́л.","id":"d03-003"},{"speaker":"serguei","es":"¿Qué elementos quiere mantener en la cocina y qué muebles quiere cambiar en esta versión?","ru":"Какие элементы хотите сохранить на кухне, а какую мебель поменять в этой версии?","pronunciation":"кэ́ элэмэ́нтос киэ́рэ мантэнэ́р эн ла коси́на и кэ́ муэ́блэс киэ́рэ камбиа́р эн э́ста бэрсио́н?","id":"d03-004"},{"speaker":"client","es":"Quiero mantener la ventana y cambiar todos los muebles, pero no sé dónde colocar la mesa.","ru":"Хочу сохранить окно и поменять всю мебель, но не знаю, где разместить стол.","pronunciation":"киэ́ро мантэнэ́р ла бэнта́на и камбиа́р то́дос лос муэ́блэс, пэ́ро но сэ́ до́ндэ колока́р ла мэ́са.","id":"d03-005"},{"speaker":"serguei","es":"Podemos estudiar dos alternativas con el diseñador y comprobar el espacio de paso en cada una.","ru":"Можем рассмотреть с дизайнером два варианта и проверить проход в каждом.","pronunciation":"подэ́мос эстудиа́р дос алтэрнати́бас кон эл дисэньадо́р и компроба́р эл эспа́сио дэ па́со эн ка́да у́на.","id":"d03-006"},{"speaker":"client","es":"En esta visualización en tres dimensiones parece que la mesa cabe sin problema junto a la isla.","ru":"На этой трёхмерной визуализации кажется, что стол без проблем помещается рядом с островом.","pronunciation":"эн э́ста бисуалисасио́н эн трэс димэнсио́нэс парэ́сэ кэ ла мэ́са ка́бэ син проблэ́ма ху́нто а ла и́сла.","id":"d03-007"},{"speaker":"serguei","es":"La imagen ayuda a entender el diseño, pero necesitamos confirmar las cotas en el plano y en el piso.","ru":"Изображение помогает понять дизайн, но размеры нужно подтвердить на чертеже и в квартире.","pronunciation":"ла има́хэн айу́да а энтэндэ́р эл дисэ́ньо, пэ́ро нэсэсита́мос конфирма́р лас ко́тас эн эл пла́но и эн эл пи́со.","id":"d03-008"},{"speaker":"client","es":"Esta medida es del suelo antiguo; después queremos cambiar también todo el pavimento de la cocina.","ru":"Этот размер взят от старого пола; затем хотим поменять всё покрытие кухни.","pronunciation":"э́ста мэди́да эс дэл суэ́ло анти́гуо; дэспуэ́с кэрэ́мос камбиа́р тамбиэ́н то́до эл пабимэ́нто дэ ла коси́на.","id":"d03-009"},{"speaker":"serguei","es":"Entonces necesitamos la altura del suelo terminado para coordinar puertas, muebles e instalaciones.","ru":"Тогда нужна отметка чистого пола для согласования дверей, мебели и коммуникаций.","pronunciation":"энто́нсэс нэсэсита́мос ла алту́ра дэл суэ́ло тэрмина́до па́ра координа́р пуэ́ртас, муэ́блэс э инсталасио́нэс.","id":"d03-010"},{"speaker":"client","es":"¿Puede hablar directamente con la diseñadora para que no tengamos varias versiones diferentes del mismo plano?","ru":"Можете связаться непосредственно с дизайнером, чтобы не было разных версий одного чертежа?","pronunciation":"пуэ́дэ абла́р дирэктамэ́нтэ кон ла дисэньадо́ра па́ра кэ но тэнга́мос ба́риас бэрсио́нэс дифэрэ́нтэс дэл ми́смо пла́но?","id":"d03-011"},{"speaker":"serguei","es":"Sí, yo coordino los oficios y le informo de los cambios que necesitan aprobación.","ru":"Да, я координирую специалистов и сообщаю вам об изменениях для согласования.","pronunciation":"си́, йо коорди́но лос офи́сиос и лэ инфо́рмо дэ лос ка́мбиос кэ нэсэси́тан апробасио́н.","id":"d03-012"},{"speaker":"client","es":"¿Puede quedar igual que en el render?","ru":"Можно сделать как на визуализации?","pronunciation":"пуэ́дэ кэда́р игуа́л кэ эн эл рэ́ндэр?","id":"d03-013"},{"speaker":"serguei","es":"Ese es el objetivo.","ru":"Это наша цель.","pronunciation":"э́сэ эс эл обхэти́бо.","id":"d03-014"},{"speaker":"serguei","es":"Primero comprobamos medidas, materiales y detalles de ejecución.","ru":"Сначала проверяем размеры, материалы и узлы исполнения.","pronunciation":"примэ́ро компроба́мос мэди́дас, матэриа́лэс и дэта́йэс дэ эхэкусио́н.","id":"d03-015"},{"speaker":"client","es":"¿Podemos mover esta pared?","ru":"Можно перенести эту стену?","pronunciation":"подэ́мос мобэ́р э́ста парэ́д?","id":"d03-016"},{"speaker":"serguei","es":"Primero hay que confirmar qué tipo de pared es y revisar la solución técnica y el trámite.","ru":"Сначала нужно определить тип стены и проверить техническое решение и оформление.","pronunciation":"примэ́ро аи кэ конфирма́р кэ́ ти́по дэ парэ́д эс и ррэбиса́р ла солусио́н тэ́кника и эл тра́митэ.","id":"d03-017"},{"speaker":"client","es":"¿Puede proponer otra distribución?","ru":"Можете предложить другую планировку?","pronunciation":"пуэ́дэ пропонэ́р о́тра дистрибусио́н?","id":"d03-018"},{"speaker":"serguei","es":"Sí, podemos estudiar una alternativa y coordinarla con el diseñador.","ru":"Да, можем рассмотреть альтернативу и согласовать её с дизайнером.","pronunciation":"си́, подэ́мос эстудиа́р у́на алтэрнати́ба и координа́рла кон эл дисэньадо́р.","id":"d03-019"},{"speaker":"client","es":"¿Quién decide este cambio?","ru":"Кто принимает решение об изменении?","pronunciation":"киэ́н дэси́дэ э́стэ ка́мбио?","id":"d03-020"},{"speaker":"serguei","es":"Lo confirmamos con el cliente y con el responsable del diseño antes de ejecutarlo.","ru":"До выполнения согласовываем с заказчиком и ответственным за дизайн.","pronunciation":"ло конфирма́мос кон эл клиэ́нтэ и кон эл ррэспонса́блэ дэл дисэ́ньо а́нтэс дэ эхэкута́рло.","id":"d03-021"},{"speaker":"client","es":"¿El presupuesto incluye el diseño?","ru":"Дизайн входит в смету?","pronunciation":"эл прэсупуэ́сто инклу́йэ эл дисэ́ньо?","id":"d03-022"},{"speaker":"serguei","es":"Lo indicamos por separado: diseño y ejecución son partidas distintas.","ru":"Указываем отдельно: дизайн и выполнение работ — разные позиции.","pronunciation":"ло индика́мос пор сэпара́до: дисэ́ньо и эхэкусио́н сон парти́дас дисти́нтас.","id":"d03-023"},{"speaker":"client","es":"¿Tengo que hablar con todos los operarios?","ru":"Мне нужно общаться с каждым рабочим?","pronunciation":"тэ́нго кэ абла́р кон то́дос лос опэра́риос?","id":"d03-024"},{"speaker":"serguei","es":"No hace falta.","ru":"В этом нет необходимости.","pronunciation":"но а́сэ фа́лта.","id":"d03-025"},{"speaker":"serguei","es":"Yo soy su interlocutor y coordino los oficios.","ru":"Я твоё контактное лицо и координирую специалистов.","pronunciation":"йо сои су интэрлокуто́р и коорди́но лос офи́сиос.","id":"d03-026"},{"speaker":"client","es":"También quiero luz indirecta en el techo y una ducha con un banco como en el render.","ru":"Ещё хочу скрытый свет в потолке и душ со скамьёй, как на визуализации.","pronunciation":"тамбиэ́н киэ́ро лус индирэ́кта эн эл тэ́чо и у́на ду́ча кон ун ба́нко ко́мо эн эл рэ́ндэр.","id":"d03-027"},{"speaker":"serguei","es":"Para esas soluciones necesitamos una sección y un detalle constructivo con las medidas y los materiales.","ru":"Для этих решений нужны разрез и конструктивный узел с размерами и материалами.","pronunciation":"па́ра э́сас солусио́нэс нэсэсита́мос у́на сэксио́н и ун дэта́йэ конструкти́бо кон лас мэди́дас и лос матэриа́лэс.","id":"d03-028"},{"speaker":"client","es":"Aquí tengo una memoria de calidades, pero algunas referencias todavía están pendientes de elegir.","ru":"У меня есть описание материалов, но некоторые артикулы ещё не выбраны.","pronunciation":"аки́ тэ́нго у́на мэмо́риа дэ калида́дэс, пэ́ро алгу́нас ррэфэрэ́нсиас тодаби́а эста́н пэндиэ́нтэс дэ элэхи́р.","id":"d03-029"},{"speaker":"serguei","es":"Revisamos la memoria y anotamos las decisiones pendientes antes de pedir materiales o cerrar las paredes.","ru":"Проверим описание и запишем нерешённые вопросы до заказа материалов или зашивки стен.","pronunciation":"ррэбиса́мос ла мэмо́риа и анота́мос лас дэсисио́нэс пэндиэ́нтэс а́нтэс дэ пэди́р матэриа́лэс о сэрра́р лас парэ́дэс.","id":"d03-030"},{"speaker":"client","es":"¿Cuándo podemos ver en la vivienda dónde van la isla, las puertas y los puntos de luz?","ru":"Когда можно увидеть в квартире расположение острова, дверей и световых точек?","pronunciation":"куа́ндо подэ́мос бэр эн ла бибиэ́нда до́ндэ бан ла и́сла, лас пуэ́ртас и лос пу́нтос дэ лус?","id":"d03-031"},{"speaker":"serguei","es":"Primero hacemos el replanteo con el diseñador y marcamos las posiciones para revisarlas juntos.","ru":"Сначала выполним разметку с дизайнером и обозначим места для совместной проверки.","pronunciation":"примэ́ро асэ́мос эл ррэплантэ́о кон эл дисэньадо́р и марка́мос лас посисио́нэс па́ра ррэбиса́рлас ху́нтос.","id":"d03-032"},{"speaker":"client","es":"Si después quiero mover una puerta un poco, prefiero saber qué consecuencias tiene antes de decidir.","ru":"Если потом захочу немного перенести дверь, предпочту заранее узнать последствия.","pronunciation":"си дэспуэ́с киэ́ро мобэ́р у́на пуэ́рта ун по́ко, прэфиэ́ро сабэ́р кэ́ консэкуэ́нсиас тиэ́нэ а́нтэс дэ дэсиди́р.","id":"d03-033"},{"speaker":"serguei","es":"No cambiamos la distribución sin confirmación y valoramos cualquier modificación antes de ejecutarla.","ru":"Не меняем планировку без подтверждения и оцениваем каждое изменение до выполнения.","pronunciation":"но камбиа́мос ла дистрибусио́н син конфирмасио́н и балора́мос куалкиэ́р модификасио́н а́нтэс дэ эхэкута́рла.","id":"d03-034"},{"speaker":"client","es":"Necesitamos que el resultado respete el diseño y que todo quede claro antes de empezar.","ru":"Нам нужно соблюсти дизайн и всё прояснить до начала.","pronunciation":"нэсэсита́мос кэ эл ррэсулта́до ррэспэ́тэ эл дисэ́ньо и кэ то́до кэ́дэ кла́ро а́нтэс дэ эмпэса́р.","id":"d03-035"},{"speaker":"serguei","es":"Le envío un resumen con la versión del plano, las medidas por confirmar y las aprobaciones pendientes.","ru":"Отправлю сводку с версией чертежа, размерами для проверки и вопросами на согласование.","pronunciation":"лэ энби́о ун ррэсу́мэн кон ла бэрсио́н дэл пла́но, лас мэди́дас пор конфирма́р и лас апробасио́нэс пэндиэ́нтэс.","id":"d03-036"}],"words":447,"minutes":4},{"lesson":4,"title":"Смета, договор и оплата","setting":"Разбор предложения по ванной: позиции, поставка, оборудование и оплата.","sentences":[{"speaker":"client","es":"He recibido el presupuesto del baño y quiero entender qué incluye cada partida antes de aceptarlo.","ru":"Я получил смету на ванную и хочу понять каждую позицию перед согласованием.","pronunciation":"э ррэсиби́до эл прэсупуэ́сто дэл ба́ньо и киэ́ро энтэндэ́р кэ́ инклу́йэ ка́да парти́да а́нтэс дэ асэпта́рло.","id":"d04-001"},{"speaker":"serguei","es":"El presupuesto está desglosado por partidas para separar la mano de obra, los materiales y el suministro.","ru":"Смета разбита по позициям с разделением работы, материалов и поставки.","pronunciation":"эл прэсупуэ́сто эста́ дэсглоса́до пор парти́дас па́ра сэпара́р ла ма́но дэ о́бра, лос матэриа́лэс и эл сумини́стро.","id":"d04-002"},{"speaker":"client","es":"En esta partida pone suministro e instalación, pero no sé si se refiere también a los sanitarios.","ru":"Здесь указаны поставка и установка, но я не понимаю, относится ли это к сантехнике.","pronunciation":"эн э́ста парти́да по́нэ сумини́стро э инсталасио́н, пэ́ро но сэ́ си сэ ррэфиэ́рэ тамбиэ́н а лос санита́риос.","id":"d04-003"},{"speaker":"serguei","es":"Aquí se refiere a los elementos descritos en la partida; los sanitarios que compra usted figuran aparte.","ru":"Здесь речь об описанных элементах; сантехника, которую покупаете вы, указана отдельно.","pronunciation":"аки́ сэ ррэфиэ́рэ а лос элэмэ́нтос дэскри́тос эн ла парти́да; лос санита́риос кэ ко́мпра устэ́д фигу́ран апа́ртэ.","id":"d04-004"},{"speaker":"client","es":"Quiero comprar yo el lavabo y el inodoro y que ustedes preparen las conexiones y los instalen.","ru":"Хочу сам купить раковину и унитаз, а вы подготовите подключения и установите их.","pronunciation":"киэ́ро компра́р йо эл лаба́бо и эл инодо́ро и кэ устэ́дэс прэпа́рэн лас конэксио́нэс и лос инста́лэн.","id":"d04-005"},{"speaker":"serguei","es":"Tenemos que confirmar las referencias y las fechas de entrega antes de cerrar el calendario.","ru":"Нужно подтвердить артикулы и даты доставки до согласования графика.","pronunciation":"тэнэ́мос кэ конфирма́р лас ррэфэрэ́нсиас и лас фэ́час дэ энтрэ́га а́нтэс дэ сэрра́р эл калэнда́рио.","id":"d04-006"},{"speaker":"client","es":"¿El importe de esta línea es un precio unitario por metro cuadrado o el total del trabajo?","ru":"Сумма в этой строке — цена за квадратный метр или общая стоимость работы?","pronunciation":"эл импо́ртэ дэ э́ста ли́нэа эс ун прэ́сио унита́рио пор мэ́тро куадра́до о эл тота́л дэл траба́хо?","id":"d04-007"},{"speaker":"serguei","es":"Esta línea indica la cantidad, el precio unitario y el importe; el total aparece al final del documento.","ru":"В строке указаны количество, единичная цена и сумма; итог находится в конце документа.","pronunciation":"э́ста ли́нэа инди́ка ла кантида́д, эл прэ́сио унита́рио и эл импо́ртэ; эл тота́л апарэ́сэ ал фина́л дэл докумэ́нто.","id":"d04-008"},{"speaker":"client","es":"Quiero comparar su propuesta con otra, pero en la otra solo aparece un precio por todo el baño.","ru":"Хочу сравнить с другим предложением, но там только одна цена за всю ванную.","pronunciation":"киэ́ро компара́р су пропуэ́ста кон о́тра, пэ́ро эн ла о́тра со́ло апарэ́сэ ун прэ́сио пор то́до эл ба́ньо.","id":"d04-009"},{"speaker":"serguei","es":"Conviene comparar el mismo alcance, las calidades previstas y las exclusiones para entender la diferencia.","ru":"Чтобы понять разницу, нужно сравнивать одинаковый состав работ, материалы и исключения.","pronunciation":"конбиэ́нэ компара́р эл ми́смо алка́нсэ, лас калида́дэс прэби́стас и лас эксклусио́нэс па́ра энтэндэ́р ла дифэрэ́нсиа.","id":"d04-010"},{"speaker":"client","es":"Aquí aparece un plazo de validez, ¿qué significa para la compra de materiales?","ru":"Здесь указан срок действия предложения, что он означает для закупки материалов?","pronunciation":"аки́ апарэ́сэ ун пла́со дэ балидэ́с, кэ́ сигнифи́ка па́ра ла ко́мпра дэ матэриа́лэс?","id":"d04-011"},{"speaker":"serguei","es":"Indica hasta cuándo se mantiene la propuesta en sus condiciones; después confirmamos de nuevo su vigencia.","ru":"Он указывает срок сохранения условий предложения; после этого повторно уточняем его актуальность.","pronunciation":"инди́ка а́ста куа́ндо сэ мантиэ́нэ ла пропуэ́ста эн сус кондисио́нэс; дэспуэ́с конфирма́мос дэ нуэ́бо су бихэ́нсиа.","id":"d04-012"},{"speaker":"client","es":"¿Este precio es con IVA?","ru":"Это цена с НДС?","pronunciation":"э́стэ прэ́сио эс кон и́ба?","id":"d04-013"},{"speaker":"serguei","es":"En esta propuesta indicamos la base, el IVA aplicable y el total por separado.","ru":"В этом предложении отдельно указываем базу, применимый НДС и итог.","pronunciation":"эн э́ста пропуэ́ста индика́мос ла ба́сэ, эл и́ба аплика́блэ и эл тота́л пор сэпара́до.","id":"d04-014"},{"speaker":"client","es":"¿Incluye todos los materiales?","ru":"Все материалы включены?","pronunciation":"инклу́йэ то́дос лос матэриа́лэс?","id":"d04-015"},{"speaker":"serguei","es":"Incluye los que aparecen en la lista.","ru":"Включены материалы из списка.","pronunciation":"инклу́йэ лос кэ апарэ́сэн эн ла ли́ста.","id":"d04-016"},{"speaker":"serguei","es":"Los demás se indican como no incluidos.","ru":"Остальные обозначены как не включённые.","pronunciation":"лос дэма́с сэ инди́кан ко́мо но инклуи́дос.","id":"d04-017"},{"speaker":"client","es":"¿Puede hacerlo más barato?","ru":"Можно дешевле?","pronunciation":"пуэ́дэ асэ́рло ма́с бара́то?","id":"d04-018"},{"speaker":"serguei","es":"Podemos revisar el alcance o elegir otros acabados y comparar las diferencias.","ru":"Можем пересмотреть состав работ или отделку и сравнить разницу.","pronunciation":"подэ́мос ррэбиса́р эл алка́нсэ о элэхи́р о́трос акаба́дос и компара́р лас дифэрэ́нсиас.","id":"d04-019"},{"speaker":"client","es":"¿Cuándo tengo que pagar?","ru":"Когда мне платить?","pronunciation":"куа́ндо тэ́нго кэ пага́р?","id":"d04-020"},{"speaker":"serguei","es":"Las fechas y los hitos están en el calendario de pagos.","ru":"Даты и этапы указаны в графике платежей.","pronunciation":"лас фэ́час и лос и́тос эста́н эн эл калэнда́рио дэ па́гос.","id":"d04-021"},{"speaker":"client","es":"¿Qué pasa si aparece un trabajo extra?","ru":"Что будет, если появится дополнительная работа?","pronunciation":"кэ́ па́са си апарэ́сэ ун траба́хо э́кстра?","id":"d04-022"},{"speaker":"serguei","es":"Le enviamos la descripción, el precio y el efecto en el plazo para aprobarlo antes.","ru":"Заранее отправим описание, цену и влияние на срок для согласования.","pronunciation":"лэ энбиа́мос ла дэскрипсио́н, эл прэ́сио и эл эфэ́кто эн эл пла́со па́ра апроба́рло а́нтэс.","id":"d04-023"},{"speaker":"client","es":"¿Quién responde si compro yo el material y llega roto?","ru":"Кто отвечает, если я куплю материал и он придёт разбитым?","pronunciation":"киэ́н ррэспо́ндэ си ко́мпро йо эл матэриа́л и йэ́га рро́то?","id":"d04-024"},{"speaker":"serguei","es":"Conviene definir quién compra, recibe y gestiona las incidencias con el proveedor.","ru":"Нужно определить, кто покупает, принимает и решает вопросы с поставщиком.","pronunciation":"конбиэ́нэ дэфини́р киэ́н ко́мпра, ррэси́бэ и хэстио́на лас инсидэ́нсиас кон эл пробээдо́р.","id":"d04-025"},{"speaker":"client","es":"Antes de firmar quiero revisar el contrato y saber cuándo tengo que hacer cada pago de la reforma.","ru":"До подписания хочу изучить договор и понять, когда вносить каждый платёж.","pronunciation":"а́нтэс дэ фирма́р киэ́ро ррэбиса́р эл контра́то и сабэ́р куа́ндо тэ́нго кэ асэ́р ка́да па́го дэ ла ррэфо́рма.","id":"d04-026"},{"speaker":"serguei","es":"El pago se divide en las fases indicadas en el contrato y la forma de pago queda por escrito.","ru":"Оплата делится на этапы договора, а порядок оплаты фиксируется письменно.","pronunciation":"эл па́го сэ диби́дэ эн лас фа́сэс индика́дас эн эл контра́то и ла фо́рма дэ па́го кэ́да пор эскри́то.","id":"d04-027"},{"speaker":"client","es":"También necesito ver el anticipo, lo que pago durante la obra y el saldo pendiente al final.","ru":"Ещё мне нужно видеть аванс, платежи во время ремонта и остаток в конце.","pronunciation":"тамбиэ́н нэсэси́то бэр эл антиси́по, ло кэ па́го дура́нтэ ла о́бра и эл са́лдо пэндиэ́нтэ ал фина́л.","id":"d04-028"},{"speaker":"serguei","es":"Detallamos esos importes y emitimos la documentación correspondiente a los pagos y a los trabajos contratados.","ru":"Подробно укажем суммы и оформим документы по платежам и согласованным работам.","pronunciation":"дэтайа́мос э́сос импо́ртэс и эмити́мос ла докумэнтасио́н коррэспондиэ́нтэ а лос па́гос и а лос траба́хос контрата́дос.","id":"d04-029"},{"speaker":"client","es":"Si decido añadir otro mueble o cambiar el revestimiento, quiero saber cuánto cuesta antes de pedirlo.","ru":"Если решу добавить шкаф или поменять облицовку, хочу узнать стоимость до заказа.","pronunciation":"си дэси́до аньади́р о́тро муэ́блэ о камбиа́р эл ррэбэстимиэ́нто, киэ́ро сабэ́р куа́нто куэ́ста а́нтэс дэ пэди́рло.","id":"d04-030"},{"speaker":"serguei","es":"Los trabajos adicionales se valoran antes de ejecutarlos y dejamos su aprobación por escrito.","ru":"Дополнительные работы оцениваем до выполнения и письменно фиксируем ваше согласие.","pronunciation":"лос траба́хос адисиона́лэс сэ бало́ран а́нтэс дэ эхэкута́рлос и дэха́мос су апробасио́н пор эскри́то.","id":"d04-031"},{"speaker":"client","es":"Así puedo decidir con el importe y el plazo claros, sin resolverlo después de la instalación.","ru":"Так я смогу принять решение, зная сумму и срок, а не разбираться после установки.","pronunciation":"аси́ пуэ́до дэсиди́р кон эл импо́ртэ и эл пла́со кла́рос, син ррэсолбэ́рло дэспуэ́с дэ ла инсталасио́н.","id":"d04-032"},{"speaker":"serguei","es":"Le envío la versión revisada con el alcance, los materiales incluidos y las condiciones de pago.","ru":"Отправлю обновлённую версию с составом работ, включёнными материалами и условиями оплаты.","pronunciation":"лэ энби́о ла бэрсио́н ррэбиса́да кон эл алка́нсэ, лос матэриа́лэс инклуи́дос и лас кондисио́нэс дэ па́го.","id":"d04-033"}],"words":440,"minutes":4},{"lesson":5,"title":"Когда начинаем и как организуем работы","setting":"График, доступ, соседи, защита квартиры, инструменты и доставка.","sentences":[{"speaker":"serguei","es":"Buenos días, hoy vamos a organizar el acceso al piso y revisar el calendario de obra por fases.","ru":"Добрый день, сегодня организуем доступ в квартиру и проверим поэтапный график работ.","pronunciation":"буэ́нос ди́ас, ои ба́мос а органиса́р эл аксэ́со ал пи́со и ррэбиса́р эл калэнда́рио дэ о́бра пор фа́сэс.","id":"d05-001"},{"speaker":"client","es":"Quiero estar presente el primer día para entregar las llaves y hablar con la persona que coordina el equipo.","ru":"Хочу присутствовать в первый день, передать ключи и поговорить с координатором команды.","pronunciation":"киэ́ро эста́р прэсэ́нтэ эл примэ́р ди́а па́ра энтрэга́р лас йа́бэс и абла́р кон ла пэрсо́на кэ коорди́на эл эки́по.","id":"d05-002"},{"speaker":"serguei","es":"¿Podemos quedar el martes a las nueve para revisar las protecciones antes de empezar el desmontaje?","ru":"Можем встретиться во вторник в девять и проверить защиту до начала демонтажа?","pronunciation":"подэ́мос кэда́р эл ма́ртэс а лас нуэ́бэ па́ра ррэбиса́р лас протэксио́нэс а́нтэс дэ эмпэса́р эл дэсмонта́хэ?","id":"d05-003"},{"speaker":"client","es":"Sí, pero el portal se cierra y el ascensor es pequeño para subir los materiales más largos.","ru":"Да, но подъезд запирается, а лифт мал для подъёма длинных материалов.","pronunciation":"си́, пэ́ро эл порта́л сэ сиэ́рра и эл ассэнсо́р эс пэкэ́ньо па́ра суби́р лос матэриа́лэс ма́с ла́ргос.","id":"d05-004"},{"speaker":"serguei","es":"Confirmamos las medidas de los bultos y coordinamos con el proveedor la entrega y la subida al piso.","ru":"Уточним размеры упаковок и согласуем с поставщиком доставку и подъём в квартиру.","pronunciation":"конфирма́мос лас мэди́дас дэ лос бу́лтос и координа́мос кон эл пробээдо́р ла энтрэ́га и ла суби́да ал пи́со.","id":"d05-005"},{"speaker":"client","es":"El administrador de fincas quiere saber qué días trabajan y quién va a limpiar las zonas comunes.","ru":"Управляющий хочет знать дни работы и кто будет убирать общие зоны.","pronunciation":"эл администрадо́р дэ фи́нкас киэ́рэ сабэ́р кэ́ ди́ас траба́хан и киэ́н ба а лимпиа́р лас со́нас кому́нэс.","id":"d05-006"},{"speaker":"serguei","es":"Vamos a consultar las condiciones de la comunidad y después enviamos un aviso con la información confirmada.","ru":"Уточним условия сообщества собственников, затем отправим уведомление с подтверждённой информацией.","pronunciation":"ба́мос а консулта́р лас кондисио́нэс дэ ла комунида́д и дэспуэ́с энбиа́мос ун аби́со кон ла информасио́н конфирма́да.","id":"d05-007"},{"speaker":"client","es":"También necesitamos acceso a la azotea para revisar los equipos que están en la cubierta del edificio.","ru":"Ещё нужен доступ на крышу для проверки установленного там оборудования.","pronunciation":"тамбиэ́н нэсэсита́мос аксэ́со а ла асотэ́а па́ра ррэбиса́р лос эки́пос кэ эста́н эн ла кубиэ́рта дэл эдифи́сио.","id":"d05-008"},{"speaker":"serguei","es":"¿Quién tiene las llaves de la azotea y con quién podemos acordar la visita del instalador?","ru":"У кого ключи от крыши и с кем согласовать визит монтажника?","pronunciation":"киэ́н тиэ́нэ лас йа́бэс дэ ла асотэ́а и кон киэ́н подэ́мос акорда́р ла биси́та дэл инсталадо́р?","id":"d05-009"},{"speaker":"client","es":"Las tiene el presidente de la comunidad y puedo pedirle que abra cuando confirmemos la hora.","ru":"Они у председателя сообщества, могу попросить его открыть после согласования времени.","pronunciation":"лас тиэ́нэ эл прэсидэ́нтэ дэ ла комунида́д и пуэ́до пэди́рлэ кэ а́бра куа́ндо конфирмэ́мос ла о́ра.","id":"d05-010"},{"speaker":"serguei","es":"Antes de empezar protegemos el portal, la escalera y las zonas del piso que se conservan.","ru":"До начала защитим подъезд, лестницу и сохраняемые зоны квартиры.","pronunciation":"а́нтэс дэ эмпэса́р протэхэ́мос эл порта́л, ла эскалэ́ра и лас со́нас дэл пи́со кэ сэ консэ́рбан.","id":"d05-011"},{"speaker":"client","es":"Quiero que el equipo sepa dónde puede guardar las herramientas y dónde no puede dejar material.","ru":"Хочу, чтобы команда знала, где хранить инструменты, а где нельзя оставлять материалы.","pronunciation":"киэ́ро кэ эл эки́по сэ́па до́ндэ пуэ́дэ гуарда́р лас эррамиэ́нтас и до́ндэ но пуэ́дэ дэха́р матэриа́л.","id":"d05-012"},{"speaker":"client","es":"¿Cuánto va a durar la obra?","ru":"Сколько продлится ремонт?","pronunciation":"куа́нто ба а дура́р ла о́бра?","id":"d05-013"},{"speaker":"serguei","es":"Le envío un calendario por fases con las dependencias de materiales y decisiones.","ru":"Отправлю поэтапный график с зависимостями от поставок и решений.","pronunciation":"лэ энби́о ун калэнда́рио пор фа́сэс кон лас дэпэндэ́нсиас дэ матэриа́лэс и дэсисио́нэс.","id":"d05-014"},{"speaker":"client","es":"¿A qué hora van a hacer ruido?","ru":"В какое время будут шумные работы?","pronunciation":"а кэ́ о́ра бан а асэ́р рруи́до?","id":"d05-015"},{"speaker":"serguei","es":"Confirmamos el horario permitido y las condiciones de la comunidad antes de planificarlas.","ru":"До планирования уточним допустимое время и условия дома.","pronunciation":"конфирма́мос эл ора́рио пэрмити́до и лас кондисио́нэс дэ ла комунида́д а́нтэс дэ планифика́рлас.","id":"d05-016"},{"speaker":"client","es":"¿Va a haber mucho polvo?","ru":"Будет много пыли?","pronunciation":"ба а абэ́р му́чо по́лбо?","id":"d05-017"},{"speaker":"serguei","es":"Vamos a proteger y separar las zonas, y a limpiar durante el trabajo.","ru":"Защитим и отделим зоны, будем убирать в процессе.","pronunciation":"ба́мос а протэхэ́р и сэпара́р лас со́нас, и а лимпиа́р дура́нтэ эл траба́хо.","id":"d05-018"},{"speaker":"client","es":"¿Puedo dejar los muebles dentro?","ru":"Можно оставить мебель внутри?","pronunciation":"пуэ́до дэха́р лос муэ́блэс дэ́нтро?","id":"d05-019"},{"speaker":"serguei","es":"Revisamos qué muebles pueden quedarse y cómo protegerlos o moverlos.","ru":"Посмотрим, что можно оставить и как защитить или переместить.","pronunciation":"ррэбиса́мос кэ́ муэ́блэс пуэ́дэн кэда́рсэ и ко́мо протэхэ́рлос о мобэ́рлос.","id":"d05-020"},{"speaker":"client","es":"¿Quién sube el material?","ru":"Кто поднимает материал?","pronunciation":"киэ́н су́бэ эл матэриа́л?","id":"d05-021"},{"speaker":"serguei","es":"Lo definimos con el proveedor: entrega a pie de calle o subida al piso.","ru":"Уточняем с поставщиком: доставка до улицы или подъём в квартиру.","pronunciation":"ло дэфини́мос кон эл пробээдо́р: энтрэ́га а пиэ дэ ка́йэ о суби́да ал пи́со.","id":"d05-022"},{"speaker":"client","es":"¿Y si no llega el pedido?","ru":"А если заказ не приедет?","pronunciation":"и си но йэ́га эл пэди́до?","id":"d05-023"},{"speaker":"serguei","es":"Revisamos las tareas que pueden continuar y actualizamos el plazo afectado.","ru":"Проверим, какие работы можно продолжать, и обновим затронутый срок.","pronunciation":"ррэбиса́мос лас тарэ́ас кэ пуэ́дэн континуа́р и актуалиса́мос эл пла́со афэкта́до.","id":"d05-024"},{"speaker":"serguei","es":"El acopio va en esta habitación y dejamos libre el pasillo para entrar y salir sin obstáculos.","ru":"Материалы складируем в этой комнате, коридор оставляем свободным для прохода.","pronunciation":"эл ако́пио ба эн э́ста абитасио́н и дэха́мос ли́брэ эл паси́йо па́ра энтра́р и сали́р син обста́кулос.","id":"d05-025"},{"speaker":"client","es":"¿Qué herramientas van a traer el primer día y qué preparación necesita la vivienda antes de su llegada?","ru":"Какие инструменты привезёте в первый день и как подготовить квартиру к приезду?","pronunciation":"кэ́ эррамиэ́нтас бан а траэ́р эл примэ́р ди́а и кэ́ прэпарасио́н нэсэси́та ла бибиэ́нда а́нтэс дэ су йэга́да?","id":"d05-026"},{"speaker":"serguei","es":"Traemos las herramientas de desmontaje, el aspirador y los equipos de protección necesarios para los trabajos previstos.","ru":"Привезём инструмент для демонтажа, пылесос и защитное снаряжение для предусмотренных работ.","pronunciation":"траэ́мос лас эррамиэ́нтас дэ дэсмонта́хэ, эл аспирадо́р и лос эки́пос дэ протэксио́н нэсэса́риос па́ра лос траба́хос прэби́стос.","id":"d05-027"},{"speaker":"client","es":"En la habitación hay una mesa y varias cajas que puedo retirar mañana por la tarde.","ru":"В комнате стол и коробки, которые я могу убрать завтра вечером.","pronunciation":"эн ла абитасио́н аи у́на мэ́са и ба́риас ка́хас кэ пуэ́до ррэтира́р маньа́на пор ла та́рдэ.","id":"d05-028"},{"speaker":"serguei","es":"Perfecto, mañana protegemos las superficies y pasado mañana recibimos el primer pedido de material.","ru":"Хорошо, завтра защитим поверхности, послезавтра получим первую поставку материалов.","pronunciation":"пэрфэ́кто, маньа́на протэхэ́мос лас супэрфи́сиэс и паса́до маньа́на ррэсиби́мос эл примэ́р пэди́до дэ матэриа́л.","id":"d05-029"},{"speaker":"client","es":"Avíseme antes de cualquier corte de agua o de luz porque necesito organizarme con la familia.","ru":"Предупреждайте перед отключением воды или света, мне нужно организовать быт семьи.","pronunciation":"аби́сэмэ а́нтэс дэ куалкиэ́р ко́ртэ дэ а́гуа о дэ лус по́ркэ нэсэси́то органиса́рмэ кон ла фами́лиа.","id":"d05-030"},{"speaker":"serguei","es":"Sí, confirmamos la zona afectada y la duración prevista antes de cada corte de servicios.","ru":"Да, перед каждым отключением согласуем затронутую зону и ожидаемую продолжительность.","pronunciation":"си́, конфирма́мос ла со́на афэкта́да и ла дурасио́н прэби́ста а́нтэс дэ ка́да ко́ртэ дэ сэрби́сиос.","id":"d05-031"},{"speaker":"client","es":"¿El viernes podemos revisar juntos el avance y las tareas que quedan para la semana siguiente?","ru":"В пятницу можем вместе проверить ход работ и задачи на следующую неделю?","pronunciation":"эл биэ́рнэс подэ́мос ррэбиса́р ху́нтос эл аба́нсэ и лас тарэ́ас кэ кэ́дан па́ра ла сэма́на сигиэ́нтэ?","id":"d05-032"},{"speaker":"serguei","es":"Sí, le envío el calendario actualizado y avisamos si una entrega o una decisión afecta al plazo.","ru":"Да, отправлю обновлённый график и предупрежу, если поставка или решение повлияет на срок.","pronunciation":"си́, лэ энби́о эл калэнда́рио актуалиса́до и абиса́мос си у́на энтрэ́га о у́на дэсисио́н афэ́кта ал пла́со.","id":"d05-033"},{"speaker":"client","es":"De acuerdo, así sabemos qué va a pasar cada día y qué tenemos que preparar antes.","ru":"Хорошо, так будем знать, что происходит каждый день и что подготовить заранее.","pronunciation":"дэ акуэ́рдо, аси́ сабэ́мос кэ́ ба а паса́р ка́да ди́а и кэ́ тэнэ́мос кэ прэпара́р а́нтэс.","id":"d05-034"}],"words":472,"minutes":5},{"lesson":6,"title":"Демонтаж и подготовка проёмов","setting":"Что снимаем, что сохраняем, проверка стен и организация вывоза мусора.","sentences":[{"speaker":"client","es":"Hoy quiero confirmar qué elementos retiramos del piso y cuáles debemos conservar durante la demolición.","ru":"Сегодня хочу подтвердить, что убираем из квартиры, а что сохраняем при демонтаже.","pronunciation":"ои киэ́ро конфирма́р кэ́ элэмэ́нтос ррэтира́мос дэл пи́со и куа́лэс дэбэ́мос консэрба́р дура́нтэ ла дэмолисио́н.","id":"d06-001"},{"speaker":"serguei","es":"Recorremos las zonas con el plano y marcamos los elementos confirmados antes de empezar a picar.","ru":"Пройдём по зонам с чертежом и отметим согласованные элементы до начала сбивки.","pronunciation":"ррэкоррэ́мос лас со́нас кон эл пла́но и марка́мос лос элэмэ́нтос конфирма́дос а́нтэс дэ эмпэса́р а пика́р.","id":"d06-002"},{"speaker":"client","es":"Esta puerta de madera me gusta y quiero reutilizarla después de cambiar la distribución del pasillo.","ru":"Мне нравится эта деревянная дверь, хочу использовать её после изменения планировки коридора.","pronunciation":"э́ста пуэ́рта дэ мадэ́ра мэ гу́ста и киэ́ро ррэутилиса́рла дэспуэ́с дэ камбиа́р ла дистрибусио́н дэл паси́йо.","id":"d06-003"},{"speaker":"serguei","es":"Primero revisamos la hoja y el marco; después la desmontamos, la identificamos y la protegemos.","ru":"Сначала проверим полотно и коробку, затем снимем, промаркируем и защитим дверь.","pronunciation":"примэ́ро ррэбиса́мос ла о́ха и эл ма́рко; дэспуэ́с ла дэсмонта́мос, ла идэнтифика́мос и ла протэхэ́мос.","id":"d06-004"},{"speaker":"client","es":"En la cocina quiero retirar los muebles, los azulejos y el suelo antiguo hasta la capa prevista.","ru":"В кухне хочу убрать мебель, плитку и старый пол до предусмотренного слоя.","pronunciation":"эн ла коси́на киэ́ро ррэтира́р лос муэ́блэс, лос асулэ́хос и эл суэ́ло анти́гуо а́ста ла ка́па прэби́ста.","id":"d06-005"},{"speaker":"serguei","es":"Anotamos cada capa en el alcance para distinguir el desmontaje de los muebles de la demolición del revestimiento.","ru":"Укажем каждый слой в составе работ, разделив снятие мебели и разрушение облицовки.","pronunciation":"анота́мос ка́да ка́па эн эл алка́нсэ па́ра дистинги́р эл дэсмонта́хэ дэ лос муэ́блэс дэ ла дэмолисио́н дэл ррэбэстимиэ́нто.","id":"d06-006"},{"speaker":"client","es":"Detrás de este tabique puede haber una tubería porque el baño está al otro lado de la pared.","ru":"За этой перегородкой может быть труба, потому что с другой стороны ванная.","pronunciation":"дэтра́с дэ э́стэ таби́кэ пуэ́дэ абэ́р у́на тубэри́а по́ркэ эл ба́ньо эста́ ал о́тро ла́до дэ ла парэ́д.","id":"d06-007"},{"speaker":"serguei","es":"Tenemos que localizar las instalaciones ocultas y coordinar su comprobación antes de abrir la zona.","ru":"Нужно определить скрытые коммуникации и согласовать их проверку до вскрытия зоны.","pronunciation":"тэнэ́мос кэ локалиса́р лас инсталасио́нэс оку́лтас и координа́р су компробасио́н а́нтэс дэ абри́р ла со́на.","id":"d06-008"},{"speaker":"client","es":"El proyecto dibuja un hueco aquí, pero no sé dónde termina el tabique y empieza el pilar.","ru":"На чертеже здесь проём, но я не знаю, где заканчивается перегородка и начинается колонна.","pronunciation":"эл пройэ́кто дибу́ха ун уэ́ко аки́, пэ́ро но сэ́ до́ндэ тэрми́на эл таби́кэ и эмпиэ́са эл пила́р.","id":"d06-009"},{"speaker":"serguei","es":"No retiramos elementos sin identificar y consultamos esa zona con el técnico que corresponda.","ru":"Не убираем неопознанные элементы и уточняем эту зону с соответствующим специалистом.","pronunciation":"но ррэтира́мос элэмэ́нтос син идэнтифика́р и консулта́мос э́са со́на кон эл тэ́книко кэ коррэспо́нда.","id":"d06-010"},{"speaker":"client","es":"Prefiero revisar ahora los límites para que el equipo no derribe algo que queremos mantener.","ru":"Предпочитаю сейчас проверить границы, чтобы команда не снесла то, что хотим оставить.","pronunciation":"прэфиэ́ро ррэбиса́р ао́ра лос ли́митэс па́ра кэ эл эки́по но дэрри́бэ а́лго кэ кэрэ́мос мантэнэ́р.","id":"d06-011"},{"speaker":"serguei","es":"Dejamos marcas claras en el plano y en la vivienda para separar lo que se conserva de lo que se retira.","ru":"Обозначим границы на чертеже и в квартире, разделив сохраняемое и демонтируемое.","pronunciation":"дэха́мос ма́ркас кла́рас эн эл пла́но и эн ла бибиэ́нда па́ра сэпара́р ло кэ сэ консэ́рба дэ ло кэ сэ ррэти́ра.","id":"d06-012"},{"speaker":"client","es":"¿Se puede tirar esta pared?","ru":"Можно снести эту стену?","pronunciation":"сэ пуэ́дэ тира́р э́ста парэ́д?","id":"d06-013"},{"speaker":"serguei","es":"Primero confirmamos si es un tabique o un elemento estructural y revisamos proyecto y trámite.","ru":"Сначала определим, перегородка это или конструктивный элемент, и проверим проект и оформление.","pronunciation":"примэ́ро конфирма́мос си эс ун таби́кэ о ун элэмэ́нто эструктура́л и ррэбиса́мос пройэ́кто и тра́митэ.","id":"d06-014"},{"speaker":"client","es":"¿Puede guardar la puerta para reutilizarla?","ru":"Можно сохранить дверь для повторного использования?","pronunciation":"пуэ́дэ гуарда́р ла пуэ́рта па́ра ррэутилиса́рла?","id":"d06-015"},{"speaker":"serguei","es":"Sí, la desmontamos y la protegemos; revisamos antes su estado.","ru":"Да, снимем и защитим, предварительно проверив состояние.","pronunciation":"си́, ла дэсмонта́мос и ла протэхэ́мос; ррэбиса́мос а́нтэс су эста́до.","id":"d06-016"},{"speaker":"client","es":"¿Por qué hay que abrir aquí?","ru":"Зачем здесь вскрывать?","pronunciation":"пор кэ́ аи кэ абри́р аки́?","id":"d06-017"},{"speaker":"serguei","es":"Necesitamos comprobar el soporte y la instalación que queda oculta.","ru":"Нужно проверить основание и скрытую коммуникацию.","pronunciation":"нэсэсита́мос компроба́р эл сопо́ртэ и ла инсталасио́н кэ кэ́да оку́лта.","id":"d06-018"},{"speaker":"client","es":"¿El escombro está incluido?","ru":"Вывоз мусора включён?","pronunciation":"эл эско́мбро эста́ инклуи́до?","id":"d06-019"},{"speaker":"serguei","es":"La retirada prevista aparece en esta partida; si cambia el volumen, lo revisamos antes.","ru":"Предусмотренный вывоз указан в этой позиции; изменение объёма согласуем заранее.","pronunciation":"ла ррэтира́да прэби́ста апарэ́сэ эн э́ста парти́да; си ка́мбиа эл болу́мэн, ло ррэбиса́мос а́нтэс.","id":"d06-020"},{"speaker":"client","es":"¿Y si aparece amianto?","ru":"А если обнаружится асбест?","pronunciation":"и си апарэ́сэ амиа́нто?","id":"d06-021"},{"speaker":"serguei","es":"No seguimos manipulando el material sospechoso; lo valoramos con una empresa especializada.","ru":"Не продолжаем работу с подозрительным материалом; обращаемся к специализированной компании.","pronunciation":"но сэги́мос манипула́ндо эл матэриа́л соспэчо́со; ло балора́мос кон у́на эмпрэ́са эспэсиалиса́да.","id":"d06-022"},{"speaker":"client","es":"¿Puede abrir un hueco más grande?","ru":"Можно увеличить проём?","pronunciation":"пуэ́дэ абри́р ун уэ́ко ма́с гра́ндэ?","id":"d06-023"},{"speaker":"serguei","es":"Hay que comprobar el elemento y definir la solución y la documentación necesarias.","ru":"Нужно проверить элемент и определить решение и необходимые документы.","pronunciation":"аи кэ компроба́р эл элэмэ́нто и дэфини́р ла солусио́н и ла докумэнтасио́н нэсэса́риас.","id":"d06-024"},{"speaker":"client","es":"Después de abrir, ¿quién confirma si el soporte necesita reparación antes de levantar el tabique nuevo?","ru":"Кто после вскрытия подтвердит, нужно ли ремонтировать основание до возведения новой перегородки?","pronunciation":"дэспуэ́с дэ абри́р, киэ́н конфи́рма си эл сопо́ртэ нэсэси́та ррэпарасио́н а́нтэс дэ лэбанта́р эл таби́кэ нуэ́бо?","id":"d06-025"},{"speaker":"serguei","es":"Revisamos el estado visible y coordinamos la valoración necesaria antes de definir el mortero y la solución.","ru":"Проверим видимое состояние и организуем нужную оценку до выбора раствора и решения.","pronunciation":"ррэбиса́мос эл эста́до биси́блэ и координа́мос ла балорасио́н нэсэса́риа а́нтэс дэ дэфини́р эл мортэ́ро и ла солусио́н.","id":"d06-026"},{"speaker":"client","es":"Quiero saber también dónde hacen las rozas y qué partes se cierran después de colocar las instalaciones.","ru":"Ещё хочу знать, где делают штробы и какие участки заделывают после монтажа коммуникаций.","pronunciation":"киэ́ро сабэ́р тамбиэ́н до́ндэ а́сэн лас рро́сас и кэ́ па́ртэс сэ сиэ́рран дэспуэ́с дэ колока́р лас инсталасио́нэс.","id":"d06-027"},{"speaker":"serguei","es":"Los recorridos se coordinan con los oficios y no se improvisan sobre elementos que no hemos comprobado.","ru":"Трассы согласуются со специалистами; на непроверенных элементах их не прокладывают наугад.","pronunciation":"лос ррэкорри́дос сэ коорди́нан кон лос офи́сиос и но сэ импроби́сан со́брэ элэмэ́нтос кэ но э́мос компроба́до.","id":"d06-028"},{"speaker":"client","es":"El edificio no tiene espacio dentro para guardar muchos sacos de escombros durante varios días.","ru":"Внутри здания нет места для длительного хранения множества мешков мусора.","pronunciation":"эл эдифи́сио но тиэ́нэ эспа́сио дэ́нтро па́ра гуарда́р му́чос са́кос дэ эско́мброс дура́нтэ ба́риос ди́ас.","id":"d06-029"},{"speaker":"serguei","es":"Planificamos la retirada por fases y confirmamos con el gestor autorizado la recogida prevista.","ru":"Спланируем поэтапный вывоз и согласуем сбор с уполномоченным оператором отходов.","pronunciation":"планифика́мос ла ррэтира́да пор фа́сэс и конфирма́мос кон эл хэсто́р ауториса́до ла ррэкохи́да прэби́ста.","id":"d06-030"},{"speaker":"client","es":"Si hace falta un contenedor, quiero que no bloquee la entrada del portal ni el acceso de los vecinos.","ru":"Если нужен контейнер, он не должен перекрывать подъезд и проход соседей.","pronunciation":"си а́сэ фа́лта ун контэнэдо́р, киэ́ро кэ но блокэ́э ла энтра́да дэл порта́л ни эл аксэ́со дэ лос бэси́нос.","id":"d06-031"},{"speaker":"serguei","es":"Primero confirmamos la ubicación y la autorización que corresponda, y después organizamos su colocación.","ru":"Сначала подтвердим место и нужное разрешение, затем организуем установку.","pronunciation":"примэ́ро конфирма́мос ла убикасио́н и ла ауторисасио́н кэ коррэспо́нда, и дэспуэ́с органиса́мос су колокасио́н.","id":"d06-032"},{"speaker":"client","es":"Entonces hoy podemos preparar la protección y empezar solo con los elementos que ya están confirmados.","ru":"Значит, сегодня можно подготовить защиту и начать только с согласованных элементов.","pronunciation":"энто́нсэс ои подэ́мос прэпара́р ла протэксио́н и эмпэса́р со́ло кон лос элэмэ́нтос кэ йа эста́н конфирма́дос.","id":"d06-033"},{"speaker":"serguei","es":"Exactamente, fotografiamos el estado inicial y dejamos anotadas las comprobaciones pendientes antes de continuar.","ru":"Именно, сфотографируем исходное состояние и запишем проверки, необходимые до продолжения.","pronunciation":"эксактамэ́нтэ, фотографиа́мос эл эста́до инисиа́л и дэха́мос анота́дас лас компробасио́нэс пэндиэ́нтэс а́нтэс дэ континуа́р.","id":"d06-034"}],"words":461,"minutes":5},{"lesson":7,"title":"Розетки, свет и электрощит","setting":"Планирование электрических точек и освещения с заказчиком.","sentences":[{"speaker":"client","es":"Quiero revisar el plano eléctrico antes de cerrar las paredes porque todavía tengo dudas sobre varios puntos.","ru":"Хочу проверить электроплан до зашивки стен, ещё есть сомнения по нескольким точкам.","pronunciation":"киэ́ро ррэбиса́р эл пла́но элэ́ктрико а́нтэс дэ сэрра́р лас парэ́дэс по́ркэ тодаби́а тэ́нго ду́дас со́брэ ба́риос пу́нтос.","id":"d07-001"},{"speaker":"serguei","es":"Vamos habitación por habitación y marcamos los enchufes, los interruptores y los puntos de luz previstos.","ru":"Пройдём по комнатам и отметим предусмотренные розетки, выключатели и световые точки.","pronunciation":"ба́мос абитасио́н пор абитасио́н и марка́мос лос энчу́фэс, лос интэррупто́рэс и лос пу́нтос дэ лус прэби́стос.","id":"d07-002"},{"speaker":"client","es":"En el salón necesito una toma de datos junto al televisor y otra cerca de la mesa de trabajo.","ru":"В гостиной нужна информационная розетка у телевизора и ещё одна возле рабочего стола.","pronunciation":"эн эл сало́н нэсэси́то у́на то́ма дэ да́тос ху́нто ал тэлэбисо́р и о́тра сэ́рка дэ ла мэ́са дэ траба́хо.","id":"d07-003"},{"speaker":"serguei","es":"Confirmamos la posición de los muebles para que las tomas queden accesibles y no detrás de una parte fija.","ru":"Уточним положение мебели, чтобы розетки оставались доступны и не оказались за неподвижной частью.","pronunciation":"конфирма́мос ла посисио́н дэ лос муэ́блэс па́ра кэ лас то́мас кэ́дэн аксэси́блэс и но дэтра́с дэ у́на па́ртэ фи́ха.","id":"d07-004"},{"speaker":"client","es":"Quiero encender la luz del pasillo desde la entrada y apagarla desde la puerta del dormitorio.","ru":"Хочу включать свет коридора у входа и выключать у двери спальни.","pronunciation":"киэ́ро энсэндэ́р ла лус дэл паси́йо дэ́сдэ ла энтра́да и апага́рла дэ́сдэ ла пуэ́рта дэл дормито́рио.","id":"d07-005"},{"speaker":"serguei","es":"Lo coordinamos con el instalador y lo indicamos en el plano de mecanismos y de control del alumbrado.","ru":"Согласуем с монтажником и укажем на плане электроустановочных изделий и управления светом.","pronunciation":"ло координа́мос кон эл инсталадо́р и ло индика́мос эн эл пла́но дэ мэкани́смос и дэ контро́л дэл алумбра́до.","id":"d07-006"},{"speaker":"client","es":"En la cocina hay pocos enchufes y necesito conectar varios electrodomésticos sin usar regletas.","ru":"На кухне мало розеток, нужно подключить несколько приборов без удлинителей-разветвителей.","pronunciation":"эн ла коси́на аи по́кос энчу́фэс и нэсэси́то конэкта́р ба́риос элэктродомэ́стикос син уса́р ррэглэ́тас.","id":"d07-007"},{"speaker":"serguei","es":"Necesitamos las referencias de los equipos para revisar la alimentación y los circuitos con el profesional habilitado.","ru":"Нужны артикулы оборудования, чтобы проверить питание и линии с уполномоченным специалистом.","pronunciation":"нэсэсита́мос лас ррэфэрэ́нсиас дэ лос эки́пос па́ра ррэбиса́р ла алимэнтасио́н и лос сиркуи́тос кон эл профэсиона́л абилита́до.","id":"d07-008"},{"speaker":"client","es":"El cuadro eléctrico es antiguo y no entiendo qué hacen el diferencial y los magnetotérmicos.","ru":"Щит старый, я не понимаю назначение дифференциальной защиты и автоматов.","pronunciation":"эл куа́дро элэ́ктрико эс анти́гуо и но энтиэ́ндо кэ́ а́сэн эл дифэрэнсиа́л и лос магнэтотэ́рмикос.","id":"d07-009"},{"speaker":"serguei","es":"El instalador revisa las protecciones, la toma de tierra y el estado de la instalación antes de definir los cambios.","ru":"Монтажник проверит защиту, заземление и состояние установки до определения изменений.","pronunciation":"эл инсталадо́р ррэби́са лас протэксио́нэс, ла то́ма дэ тиэ́рра и эл эста́до дэ ла инсталасио́н а́нтэс дэ дэфини́р лос ка́мбиос.","id":"d07-010"},{"speaker":"client","es":"También quiero una tira LED debajo de los muebles de cocina para iluminar bien la encimera.","ru":"Ещё хочу светодиодную ленту под кухонными шкафами для освещения столешницы.","pronunciation":"тамбиэ́н киэ́ро у́на ти́ра лэд дэба́хо дэ лос муэ́блэс дэ коси́на па́ра илумина́р биэн ла энсимэ́ра.","id":"d07-011"},{"speaker":"serguei","es":"Definimos el perfil de aluminio, la luminaria, la alimentación y el acceso necesario para su mantenimiento.","ru":"Определим алюминиевый профиль, светильник, питание и нужный доступ для обслуживания.","pronunciation":"дэфини́мос эл пэрфи́л дэ алуми́нио, ла лумина́риа, ла алимэнтасио́н и эл аксэ́со нэсэса́рио па́ра су мантэнимиэ́нто.","id":"d07-012"},{"speaker":"client","es":"¿Puedo poner un enchufe aquí?","ru":"Можно здесь розетку?","pronunciation":"пуэ́до понэ́р ун энчу́фэ аки́?","id":"d07-013"},{"speaker":"serguei","es":"Comprobamos la ubicación, el uso y los requisitos de esa zona con el instalador.","ru":"Проверим место, назначение и требования к зоне с монтажником.","pronunciation":"компроба́мос ла убикасио́н, эл у́со и лос ррэкиси́тос дэ э́са со́на кон эл инсталадо́р.","id":"d07-014"},{"speaker":"client","es":"¿Es necesario cambiar todo el cableado?","ru":"Нужно менять всю проводку?","pronunciation":"эс нэсэса́рио камбиа́р то́до эл каблэа́до?","id":"d07-015"},{"speaker":"serguei","es":"Primero revisamos su estado, las necesidades y la documentación disponible.","ru":"Сначала проверим состояние, потребности и имеющиеся документы.","pronunciation":"примэ́ро ррэбиса́мос су эста́до, лас нэсэсида́дэс и ла докумэнтасио́н диспони́блэ.","id":"d07-016"},{"speaker":"client","es":"¿Puedo regular la luz?","ru":"Можно регулировать яркость?","pronunciation":"пуэ́до ррэгула́р ла лус?","id":"d07-017"},{"speaker":"serguei","es":"Sí, si la luminaria, el equipo y el sistema de regulación son compatibles.","ru":"Да, если совместимы светильник, питание и система регулирования.","pronunciation":"си́, си ла лумина́риа, эл эки́по и эл систэ́ма дэ ррэгуласио́н сон компати́блэс.","id":"d07-018"},{"speaker":"client","es":"¿La luz va a ser cálida o fría?","ru":"Свет будет тёплый или холодный?","pronunciation":"ла лус ба а сэр ка́лида о фри́а?","id":"d07-019"},{"speaker":"serguei","es":"Confirmamos la temperatura de color y, si hace falta, hacemos una prueba con una muestra.","ru":"Подтвердим цветовую температуру и при необходимости проверим образец.","pronunciation":"конфирма́мос ла тэмпэрату́ра дэ коло́р и, си а́сэ фа́лта, асэ́мос у́на пруэ́ба кон у́на муэ́стра.","id":"d07-020"},{"speaker":"client","es":"¿Incluye el boletín eléctrico?","ru":"Электрический сертификат включён?","pronunciation":"инклу́йэ эл болэти́н элэ́ктрико?","id":"d07-021"},{"speaker":"serguei","es":"Comprobamos qué documento corresponde y si está incluido en la partida del instalador.","ru":"Проверим нужный документ и включение в позицию монтажника.","pronunciation":"компроба́мос кэ́ докумэ́нто коррэспо́ндэ и си эста́ инклуи́до эн ла парти́да дэл инсталадо́р.","id":"d07-022"},{"speaker":"client","es":"¿Se puede esconder todo el cable?","ru":"Можно скрыть все провода?","pronunciation":"сэ пуэ́дэ эскондэ́р то́до эл ка́блэ?","id":"d07-023"},{"speaker":"serguei","es":"Revisamos recorridos, registros y accesos de mantenimiento antes de confirmarlo.","ru":"До подтверждения проверим трассы, ревизии и доступ для обслуживания.","pronunciation":"ррэбиса́мос ррэкорри́дос, ррэхи́строс и аксэ́сос дэ мантэнимиэ́нто а́нтэс дэ конфирма́рло.","id":"d07-024"},{"speaker":"client","es":"En el dormitorio quiero una luz general y dos luces junto a la cama que se controlen por separado.","ru":"В спальне хочу общий свет и два отдельных светильника возле кровати.","pronunciation":"эн эл дормито́рио киэ́ро у́на лус хэнэра́л и дос лу́сэс ху́нто а ла ка́ма кэ сэ контро́лэн пор сэпара́до.","id":"d07-025"},{"speaker":"serguei","es":"Anotamos qué interruptor enciende cada punto para comprobar el funcionamiento cuando todo esté instalado.","ru":"Запишем, какой выключатель включает каждую точку, чтобы проверить работу после монтажа.","pronunciation":"анота́мос кэ́ интэррупто́р энсиэ́ндэ ка́да пу́нто па́ра компроба́р эл фунсионамиэ́нто куа́ндо то́до эстэ́ инстала́до.","id":"d07-026"},{"speaker":"client","es":"¿Podemos hacer una prueba de iluminación antes de comprar todas las luminarias del piso?","ru":"Можем проверить освещение до покупки всех светильников квартиры?","pronunciation":"подэ́мос асэ́р у́на пруэ́ба дэ илуминасио́н а́нтэс дэ компра́р то́дас лас лумина́риас дэл пи́со?","id":"d07-027"},{"speaker":"serguei","es":"Sí, confirmamos la referencia y revisamos una muestra para valorar la luz en la habitación.","ru":"Да, подтвердим артикул и проверим образец, чтобы оценить свет в комнате.","pronunciation":"си́, конфирма́мос ла ррэфэрэ́нсиа и ррэбиса́мос у́на муэ́стра па́ра балора́р ла лус эн ла абитасио́н.","id":"d07-028"},{"speaker":"client","es":"El videoportero también se queda, pero quiero que el cable no se vea por encima de la pared.","ru":"Видеодомофон остаётся, но я не хочу видеть провод поверх стены.","pronunciation":"эл бидэопортэ́ро тамбиэ́н сэ кэ́да, пэ́ро киэ́ро кэ эл ка́блэ но сэ бэ́а пор энси́ма дэ ла парэ́д.","id":"d07-029"},{"speaker":"serguei","es":"Revisamos el recorrido y las condiciones del sistema antes de confirmar cómo podemos integrar ese cableado.","ru":"Проверим трассу и условия системы, прежде чем подтвердить способ скрыть проводку.","pronunciation":"ррэбиса́мос эл ррэкорри́до и лас кондисио́нэс дэл систэ́ма а́нтэс дэ конфирма́р ко́мо подэ́мос интэгра́р э́сэ каблэа́до.","id":"d07-030"},{"speaker":"client","es":"¿Cuándo tengo que aprobar definitivamente las posiciones de los enchufes y los mecanismos?","ru":"Когда окончательно утвердить положение розеток и электроустановочных изделий?","pronunciation":"куа́ндо тэ́нго кэ апроба́р дэфинитибамэ́нтэ лас посисио́нэс дэ лос энчу́фэс и лос мэкани́смос?","id":"d07-031"},{"speaker":"serguei","es":"Antes de ejecutar los recorridos y cerrar los revestimientos, revisamos el replanteo y dejamos su aprobación anotada.","ru":"До прокладки трасс и зашивки проверим разметку и зафиксируем ваше согласование.","pronunciation":"а́нтэс дэ эхэкута́р лос ррэкорри́дос и сэрра́р лос ррэбэстимиэ́нтос, ррэбиса́мос эл ррэплантэ́о и дэха́мос су апробасио́н анота́да.","id":"d07-032"},{"speaker":"client","es":"Después de la instalación quiero ver cómo se enciende todo y qué línea corresponde a cada zona.","ru":"После установки хочу увидеть включение всего освещения и назначение каждой линии.","pronunciation":"дэспуэ́с дэ ла инсталасио́н киэ́ро бэр ко́мо сэ энсиэ́ндэ то́до и кэ́ ли́нэа коррэспо́ндэ а ка́да со́на.","id":"d07-033"},{"speaker":"serguei","es":"Organizamos una comprobación de funcionamiento y entregamos la documentación que corresponda al trabajo contratado.","ru":"Организуем проверку работы и передадим документы, соответствующие согласованным работам.","pronunciation":"органиса́мос у́на компробасио́н дэ фунсионамиэ́нто и энтрэга́мос ла докумэнтасио́н кэ коррэспо́нда ал траба́хо контрата́до.","id":"d07-034"}],"words":468,"minutes":5},{"lesson":8,"title":"Трубы, канализация и ванная","setting":"Обсуждение новой ванной: подключения, оборудование, душ и обслуживание.","sentences":[{"speaker":"client","es":"Quiero reformar todo el baño, retirar el bidé y aprovechar ese espacio para hacer una ducha más grande.","ru":"Хочу полностью переделать ванную, убрать биде и увеличить душ за его счёт.","pronunciation":"киэ́ро ррэформа́р то́до эл ба́ньо, ррэтира́р эл бидэ́ и апробэча́р э́сэ эспа́сио па́ра асэ́р у́на ду́ча ма́с гра́ндэ.","id":"d08-001"},{"speaker":"serguei","es":"Revisamos las medidas y las conexiones antes de confirmar la posición del plato de ducha y del resto de sanitarios.","ru":"Проверим размеры и подключения до подтверждения положения поддона и остальной сантехники.","pronunciation":"ррэбиса́мос лас мэди́дас и лас конэксио́нэс а́нтэс дэ конфирма́р ла посисио́н дэл пла́то дэ ду́ча и дэл ррэ́сто дэ санита́риос.","id":"d08-002"},{"speaker":"client","es":"El lavabo nuevo lleva un mueble suspendido y la grifería va colocada en la pared.","ru":"У новой раковины подвесная тумба, а смеситель устанавливается на стене.","pronunciation":"эл лаба́бо нуэ́бо йэ́ба ун муэ́блэ суспэнди́до и ла грифэри́а ба колока́да эн ла парэ́д.","id":"d08-003"},{"speaker":"serguei","es":"Necesitamos las fichas del lavabo, del mueble y del grifo empotrado antes de preparar las tomas.","ru":"Нужны документы раковины, тумбы и скрытого смесителя до подготовки подключений.","pronunciation":"нэсэсита́мос лас фи́час дэл лаба́бо, дэл муэ́блэ и дэл гри́фо эмпотра́до а́нтэс дэ прэпара́р лас то́мас.","id":"d08-004"},{"speaker":"client","es":"Quiero conservar el inodoro, pero la cisterna hace ruido y a veces parece que sigue entrando agua.","ru":"Хочу сохранить унитаз, но бачок шумит, и иногда кажется, что вода продолжает поступать.","pronunciation":"киэ́ро консэрба́р эл инодо́ро, пэ́ро ла систэ́рна а́сэ рруи́до и а бэ́сэс парэ́сэ кэ си́гэ энтра́ндо а́гуа.","id":"d08-005"},{"speaker":"serguei","es":"Lo revisamos por separado y distinguimos la reparación del mecanismo de una posible sustitución del conjunto.","ru":"Проверим отдельно и разделим ремонт механизма и возможную замену всего изделия.","pronunciation":"ло ррэбиса́мос пор сэпара́до и дистинги́мос ла ррэпарасио́н дэл мэкани́смо дэ у́на поси́блэ суститусио́н дэл конху́нто.","id":"d08-006"},{"speaker":"client","es":"En la cocina también hay una llave de paso que no gira bien y quiero incluirla en la revisión.","ru":"На кухне ещё есть запорный кран, который плохо поворачивается, его тоже хочу проверить.","pronunciation":"эн ла коси́на тамбиэ́н аи у́на йа́бэ дэ па́со кэ но хи́ра биэн и киэ́ро инклуи́рла эн ла ррэбисио́н.","id":"d08-007"},{"speaker":"serguei","es":"Localizamos las llaves de corte y confirmamos cómo aislar cada zona antes de desmontar las conexiones.","ru":"Найдём запорные краны и уточним отключение каждой зоны до разборки соединений.","pronunciation":"локалиса́мос лас йа́бэс дэ ко́ртэ и конфирма́мос ко́мо аисла́р ка́да со́на а́нтэс дэ дэсмонта́р лас конэксио́нэс.","id":"d08-008"},{"speaker":"client","es":"¿La tubería que veo aquí es de agua fría o es parte del desagüe del lavabo?","ru":"Видимая здесь труба — холодная вода или часть слива раковины?","pronunciation":"ла тубэри́а кэ бэ́о аки́ эс дэ а́гуа фри́а о эс па́ртэ дэл дэса́гуэ дэл лаба́бо?","id":"d08-009"},{"speaker":"serguei","es":"Primero identificamos la instalación y comprobamos el recorrido para no confundir el suministro con la evacuación.","ru":"Сначала определим коммуникацию и проверим трассу, чтобы не перепутать подачу и отвод воды.","pronunciation":"примэ́ро идэнтифика́мос ла инсталасио́н и компроба́мос эл ррэкорри́до па́ра но конфунди́р эл сумини́стро кон ла эбакуасио́н.","id":"d08-010"},{"speaker":"client","es":"También quiero que el sifón quede accesible dentro del mueble y no impida abrir los cajones.","ru":"Ещё хочу доступный сифон внутри тумбы, который не мешает открывать ящики.","pronunciation":"тамбиэ́н киэ́ро кэ эл сифо́н кэ́дэ аксэси́блэ дэ́нтро дэл муэ́блэ и но импи́да абри́р лос кахо́нэс.","id":"d08-011"},{"speaker":"serguei","es":"Coordinamos el desagüe con las medidas del mueble y revisamos la posición de las conexiones antes del montaje.","ru":"Согласуем слив с размерами тумбы и проверим подключения до монтажа.","pronunciation":"координа́мос эл дэса́гуэ кон лас мэди́дас дэл муэ́блэ и ррэбиса́мос ла посисио́н дэ лас конэксио́нэс а́нтэс дэл монта́хэ.","id":"d08-012"},{"speaker":"client","es":"¿Se puede poner el inodoro al otro lado?","ru":"Можно поставить унитаз с другой стороны?","pronunciation":"сэ пуэ́дэ понэ́р эл инодо́ро ал о́тро ла́до?","id":"d08-013"},{"speaker":"serguei","es":"Primero comprobamos el desagüe, el espacio disponible y la solución técnica.","ru":"Сначала проверим слив, доступное место и техническое решение.","pronunciation":"примэ́ро компроба́мос эл дэса́гуэ, эл эспа́сио диспони́блэ и ла солусио́н тэ́кника.","id":"d08-014"},{"speaker":"client","es":"¿Por qué huele mal el baño?","ru":"Почему в ванной пахнет?","pronunciation":"пор кэ́ уэ́лэ мал эл ба́ньо?","id":"d08-015"},{"speaker":"serguei","es":"Revisamos los sifones, las conexiones y la ventilación antes de confirmar la causa.","ru":"До вывода о причине проверим сифоны, соединения и вентиляцию.","pronunciation":"ррэбиса́мос лос сифо́нэс, лас конэксио́нэс и ла бэнтиласио́н а́нтэс дэ конфирма́р ла ка́уса.","id":"d08-016"},{"speaker":"client","es":"¿Podemos reutilizar los tubos?","ru":"Можно использовать старые трубы?","pronunciation":"подэ́мос ррэутилиса́р лос ту́бос?","id":"d08-017"},{"speaker":"serguei","es":"Hay que comprobar el material, el estado, la compatibilidad y el alcance de la reforma.","ru":"Нужно проверить материал, состояние, совместимость и состав ремонта.","pronunciation":"аи кэ компроба́р эл матэриа́л, эл эста́до, ла компатибилида́д и эл алка́нсэ дэ ла ррэфо́рма.","id":"d08-018"},{"speaker":"client","es":"¿Cómo se repara una cisterna empotrada?","ru":"Как обслуживать скрытый бачок?","pronunciation":"ко́мо сэ ррэпа́ра у́на систэ́рна эмпотра́да?","id":"d08-019"},{"speaker":"serguei","es":"El acceso depende del modelo; dejamos previsto el acceso indicado por el fabricante.","ru":"Доступ зависит от модели; предусматриваем доступ по документации изготовителя.","pronunciation":"эл аксэ́со дэпэ́ндэ дэл модэ́ло; дэха́мос прэби́сто эл аксэ́со индика́до пор эл фабрика́нтэ.","id":"d08-020"},{"speaker":"client","es":"¿Se puede usar el baño durante la obra?","ru":"Можно пользоваться ванной во время работ?","pronunciation":"сэ пуэ́дэ уса́р эл ба́ньо дура́нтэ ла о́бра?","id":"d08-021"},{"speaker":"serguei","es":"Definimos las fases, los cortes y cuándo puede volver a utilizarse cada elemento.","ru":"Определим этапы, отключения и момент возврата каждого элемента в работу.","pronunciation":"дэфини́мос лас фа́сэс, лос ко́ртэс и куа́ндо пуэ́дэ болбэ́р а утилиса́рсэ ка́да элэмэ́нто.","id":"d08-022"},{"speaker":"client","es":"¿Va a mejorar la presión del agua?","ru":"Напор воды улучшится?","pronunciation":"ба а мэхора́р ла прэсио́н дэл а́гуа?","id":"d08-023"},{"speaker":"serguei","es":"Primero medimos y localizamos la limitación; no puedo prometerlo sin comprobar la instalación.","ru":"Сначала измерим и найдём ограничение; до проверки обещать нельзя.","pronunciation":"примэ́ро мэди́мос и локалиса́мос ла лимитасио́н; но пуэ́до промэтэ́рло син компроба́р ла инсталасио́н.","id":"d08-024"},{"speaker":"client","es":"Me gustaría tener un toallero eléctrico y una mampara con una parte fija y una puerta.","ru":"Мне нужен электрический полотенцесушитель и ограждение с неподвижной частью и дверью.","pronunciation":"мэ густари́а тэнэ́р ун тоайэ́ро элэ́ктрико и у́на мампа́ра кон у́на па́ртэ фи́ха и у́на пуэ́рта.","id":"d08-025"},{"speaker":"serguei","es":"Confirmamos los modelos y coordinamos las posiciones con la fontanería, la electricidad y los remates del baño.","ru":"Уточним модели и согласуем расположение с сантехникой, электрикой и отделкой ванной.","pronunciation":"конфирма́мос лос модэ́лос и координа́мос лас посисио́нэс кон ла фонтанэри́а, ла элэктрисида́д и лос ррэма́тэс дэл ба́ньо.","id":"d08-026"},{"speaker":"client","es":"La ducha debe ser cómoda y quiero que quede claro dónde va la válvula y cómo se limpia.","ru":"Душ должен быть удобным; хочу понимать расположение клапана слива и способ очистки.","pronunciation":"ла ду́ча дэ́бэ сэр ко́мода и киэ́ро кэ кэ́дэ кла́ро до́ндэ ба ла ба́лбула и ко́мо сэ ли́мпиа.","id":"d08-027"},{"speaker":"serguei","es":"Revisamos el acceso de mantenimiento y la documentación del fabricante antes de cerrar los elementos que quedan ocultos.","ru":"Проверим доступ для обслуживания и документацию изготовителя до закрытия скрытых элементов.","pronunciation":"ррэбиса́мос эл аксэ́со дэ мантэнимиэ́нто и ла докумэнтасио́н дэл фабрика́нтэ а́нтэс дэ сэрра́р лос элэмэ́нтос кэ кэ́дан оку́лтос.","id":"d08-028"},{"speaker":"client","es":"¿Cuándo se comprueba que no hay fugas en las conexiones que van dentro de la pared?","ru":"Когда проверяют отсутствие утечек в соединениях внутри стены?","pronunciation":"куа́ндо сэ компруэ́ба кэ но аи фу́гас эн лас конэксио́нэс кэ бан дэ́нтро дэ ла парэ́д?","id":"d08-029"},{"speaker":"serguei","es":"El profesional realiza las comprobaciones correspondientes antes de cerrar y confirma las pruebas previstas para la instalación.","ru":"Специалист проводит соответствующие проверки до зашивки и подтверждает предусмотренные испытания.","pronunciation":"эл профэсиона́л ррэали́са лас компробасио́нэс коррэспондиэ́нтэс а́нтэс дэ сэрра́р и конфи́рма лас пруэ́бас прэби́стас па́ра ла инсталасио́н.","id":"d08-030"},{"speaker":"client","es":"Quiero que se vea en la propuesta qué equipos compro yo y qué materiales suministran ustedes.","ru":"Хочу видеть в предложении, какое оборудование покупаю я и какие материалы поставляете вы.","pronunciation":"киэ́ро кэ сэ бэ́а эн ла пропуэ́ста кэ́ эки́пос ко́мпро йо и кэ́ матэриа́лэс сумини́стран устэ́дэс.","id":"d08-031"},{"speaker":"serguei","es":"Separamos el suministro de equipos, los materiales de instalación y la mano de obra para evitar confusiones.","ru":"Разделим поставку оборудования, монтажные материалы и работу, чтобы избежать путаницы.","pronunciation":"сэпара́мос эл сумини́стро дэ эки́пос, лос матэриа́лэс дэ инсталасио́н и ла ма́но дэ о́бра па́ра эбита́р конфусио́нэс.","id":"d08-032"},{"speaker":"client","es":"Cuando terminemos, necesito saber dónde están las llaves y cómo actuar si aparece una fuga.","ru":"После завершения мне нужно знать расположение кранов и что делать при утечке.","pronunciation":"куа́ндо тэрминэ́мос, нэсэси́то сабэ́р до́ндэ эста́н лас йа́бэс и ко́мо актуа́р си апарэ́сэ у́на фу́га.","id":"d08-033"},{"speaker":"serguei","es":"En la entrega revisamos el funcionamiento, enseñamos los puntos de corte y entregamos la información de mantenimiento.","ru":"При сдаче проверим работу, покажем точки отключения и передадим информацию по обслуживанию.","pronunciation":"эн ла энтрэ́га ррэбиса́мос эл фунсионамиэ́нто, энсэньа́мос лос пу́нтос дэ ко́ртэ и энтрэга́мос ла информасио́н дэ мантэнимиэ́нто.","id":"d08-034"}],"words":487,"minutes":5},{"lesson":9,"title":"Кондиционеры, отопление и вентиляция","setting":"Замена кондиционеров, трассы на крышу, дренаж и вентиляция ванной.","sentences":[{"speaker":"client","es":"Quiero cambiar los dos aires acondicionados antiguos y poner un sistema con tres unidades interiores y una exterior.","ru":"Хочу заменить два старых кондиционера системой с тремя внутренними и одним наружным блоком.","pronunciation":"киэ́ро камбиа́р лос дос а́ирэс акондисиона́дос анти́гуос и понэ́р ун систэ́ма кон трэс унида́дэс интэрио́рэс и у́на экстэрио́р.","id":"d09-001"},{"speaker":"serguei","es":"Revisamos las habitaciones que quiere climatizar y coordinamos la selección del equipo con el instalador habilitado.","ru":"Проверим помещения для кондиционирования и согласуем выбор оборудования с уполномоченным монтажником.","pronunciation":"ррэбиса́мос лас абитасио́нэс кэ киэ́рэ климатиса́р и координа́мос ла сэлэксио́н дэл эки́по кон эл инсталадо́р абилита́до.","id":"d09-002"},{"speaker":"client","es":"La unidad exterior tiene que ir en la cubierta porque no quiero ocupar más espacio en la terraza.","ru":"Наружный блок должен стоять на крыше, не хочу занимать место на террасе.","pronunciation":"ла унида́д экстэрио́р тиэ́нэ кэ ир эн ла кубиэ́рта по́ркэ но киэ́ро окупа́р ма́с эспа́сио эн ла тэрра́са.","id":"d09-003"},{"speaker":"serguei","es":"Necesitamos confirmar el acceso, la ubicación y las condiciones aplicables antes de organizar la subida del equipo.","ru":"Нужно уточнить доступ, место и применимые условия до организации подъёма оборудования.","pronunciation":"нэсэсита́мос конфирма́р эл аксэ́со, ла убикасио́н и лас кондисио́нэс аплика́блэс а́нтэс дэ органиса́р ла суби́да дэл эки́по.","id":"d09-004"},{"speaker":"client","es":"Dos líneas ya están colocadas y la tercera tiene que recorrer unos veintiún metros hasta el dormitorio.","ru":"Две трассы уже проложены, третьей нужно пройти около 21 метра до спальни.","pronunciation":"дос ли́нэас йа эста́н колока́дас и ла тэрсэ́ра тиэ́нэ кэ ррэкоррэ́р у́нос бэинтиу́н мэ́трос а́ста эл дормито́рио.","id":"d09-005"},{"speaker":"serguei","es":"El instalador comprueba las líneas existentes y los límites del modelo antes de confirmar si se pueden reutilizar.","ru":"Монтажник проверит существующие трассы и ограничения модели до подтверждения повторного использования.","pronunciation":"эл инсталадо́р компруэ́ба лас ли́нэас эксистэ́нтэс и лос ли́митэс дэл модэ́ло а́нтэс дэ конфирма́р си сэ пуэ́дэн ррэутилиса́р.","id":"d09-006"},{"speaker":"client","es":"El recorrido pasa por un canal de fachada, una cámara bajo cubierta y el falso techo del pasillo.","ru":"Трасса проходит по фасадному каналу, полости под крышей и подвесному потолку коридора.","pronunciation":"эл ррэкорри́до па́са пор ун кана́л дэ фача́да, у́на ка́мара ба́хо кубиэ́рта и эл фа́лсо тэ́чо дэл паси́йо.","id":"d09-007"},{"speaker":"serguei","es":"Marcamos el recorrido y coordinamos los pasos, las rozas y los registros antes de cerrar los acabados.","ru":"Отметим трассу и согласуем проходы, штробы и ревизии до закрытия отделки.","pronunciation":"марка́мос эл ррэкорри́до и координа́мос лос па́сос, лас рро́сас и лос ррэхи́строс а́нтэс дэ сэрра́р лос акаба́дос.","id":"d09-008"},{"speaker":"client","es":"También me han dicho que dos unidades van a necesitar una bomba para sacar el agua de condensación.","ru":"Мне также сказали, что двум блокам нужны насосы для отвода конденсата.","pronunciation":"тамбиэ́н мэ ан ди́чо кэ дос унида́дэс бан а нэсэсита́р у́на бо́мба па́ра сака́р эл а́гуа дэ кондэнсасио́н.","id":"d09-009"},{"speaker":"serguei","es":"Revisamos el desagüe de condensados y dejamos previsto el acceso necesario para mantener cada bomba.","ru":"Проверим отвод конденсата и предусмотрим доступ для обслуживания каждого насоса.","pronunciation":"ррэбиса́мос эл дэса́гуэ дэ кондэнса́дос и дэха́мос прэби́сто эл аксэ́со нэсэса́рио па́ра мантэнэ́р ка́да бо́мба.","id":"d09-010"},{"speaker":"client","es":"No quiero escuchar un ruido constante en el dormitorio por la noche ni notar vibraciones en la pared.","ru":"Не хочу постоянного шума в спальне ночью или вибрации стены.","pronunciation":"но киэ́ро эскуча́р ун рруи́до конста́нтэ эн эл дормито́рио пор ла но́чэ ни нота́р бибрасио́нэс эн ла парэ́д.","id":"d09-011"},{"speaker":"serguei","es":"Estudiamos la ubicación, los soportes y las características de los equipos con el profesional antes de elegirlos.","ru":"Изучим расположение, крепления и характеристики оборудования со специалистом до выбора.","pronunciation":"эстудиа́мос ла убикасио́н, лос сопо́ртэс и лас карактэри́стикас дэ лос эки́пос кон эл профэсиона́л а́нтэс дэ элэхи́рлос.","id":"d09-012"},{"speaker":"client","es":"¿Podemos aprovechar las tuberías antiguas?","ru":"Можно оставить старые трубы трассы?","pronunciation":"подэ́мос апробэча́р лас тубэри́ас анти́гуас?","id":"d09-013"},{"speaker":"serguei","es":"Primero comprobamos el modelo, el estado, las dimensiones y las condiciones de reutilización.","ru":"Сначала проверим модель, состояние, размеры и условия повторного использования.","pronunciation":"примэ́ро компроба́мос эл модэ́ло, эл эста́до, лас димэнсио́нэс и лас кондисио́нэс дэ ррэутилисасио́н.","id":"d09-014"},{"speaker":"client","es":"¿Hace falta una bomba de condensados?","ru":"Нужен дренажный насос?","pronunciation":"а́сэ фа́лта у́на бо́мба дэ кондэнса́дос?","id":"d09-015"},{"speaker":"serguei","es":"Depende del recorrido y de la posibilidad de evacuar por gravedad.","ru":"Зависит от трассы и возможности самотечного отвода.","pronunciation":"дэпэ́ндэ дэл ррэкорри́до и дэ ла посибилида́д дэ эбакуа́р пор грабэда́д.","id":"d09-016"},{"speaker":"client","es":"¿Va a hacer mucho ruido?","ru":"Будет сильно шуметь?","pronunciation":"ба а асэ́р му́чо рруи́до?","id":"d09-017"},{"speaker":"serguei","es":"Revisamos las características del equipo, la ubicación y los apoyos; después comprobamos el resultado.","ru":"Проверим характеристики, место и опоры; затем проверим результат.","pronunciation":"ррэбиса́мос лас карактэри́стикас дэл эки́по, ла убикасио́н и лос апо́йос; дэспуэ́с компроба́мос эл ррэсулта́до.","id":"d09-018"},{"speaker":"client","es":"¿Por qué no podemos ponerlo en la fachada?","ru":"Почему нельзя просто поставить на фасад?","pronunciation":"пор кэ́ но подэ́мос понэ́рло эн ла фача́да?","id":"d09-019"},{"speaker":"serguei","es":"Hay que comprobar las condiciones del edificio, la comunidad y el ayuntamiento antes de decidirlo.","ru":"До решения нужно проверить условия здания, сообщества и муниципалитета.","pronunciation":"аи кэ компроба́р лас кондисио́нэс дэл эдифи́сио, ла комунида́д и эл айунтамиэ́нто а́нтэс дэ дэсиди́рло.","id":"d09-020"},{"speaker":"client","es":"¿Incluye retirar los equipos viejos?","ru":"Снятие старых блоков включено?","pronunciation":"инклу́йэ ррэтира́р лос эки́пос биэ́хос?","id":"d09-021"},{"speaker":"serguei","es":"Lo indicamos expresamente, junto con su gestión y la intervención sobre el refrigerante.","ru":"Указываем явно, вместе с обращением с оборудованием и работами по хладагенту.","pronunciation":"ло индика́мос экспрэсамэ́нтэ, ху́нто кон су хэстио́н и ла интэрбэнсио́н со́брэ эл ррэфрихэра́нтэ.","id":"d09-022"},{"speaker":"client","es":"¿Puede revisar también la caldera de gas?","ru":"Можете проверить газовый котёл?","pronunciation":"пуэ́дэ ррэбиса́р тамбиэ́н ла калдэ́ра дэ гас?","id":"d09-023"},{"speaker":"serguei","es":"Coordinamos la revisión con el profesional o empresa habilitados para esa instalación.","ru":"Организуем проверку специалистом или компанией с необходимыми допусками к этой системе.","pronunciation":"координа́мос ла ррэбисио́н кон эл профэсиона́л о эмпрэ́са абилита́дос па́ра э́са инсталасио́н.","id":"d09-024"},{"speaker":"client","es":"En invierno quiero usar el equipo para calentar el salón y los dormitorios sin poner radiadores adicionales.","ru":"Зимой хочу обогревать гостиную и спальни кондиционером без дополнительных радиаторов.","pronunciation":"эн инбиэ́рно киэ́ро уса́р эл эки́по па́ра калэнта́р эл сало́н и лос дормито́риос син понэ́р ррадиадо́рэс адисиона́лэс.","id":"d09-025"},{"speaker":"serguei","es":"Confirmamos las necesidades de cada zona y revisamos la solución de calefacción junto con la climatización.","ru":"Уточним потребности каждой зоны и рассмотрим отопление вместе с кондиционированием.","pronunciation":"конфирма́мос лас нэсэсида́дэс дэ ка́да со́на и ррэбиса́мос ла солусио́н дэ калэфаксио́н ху́нто кон ла климатисасио́н.","id":"d09-026"},{"speaker":"client","es":"El baño no tiene ventana y el extractor actual casi no saca aire cuando nos duchamos.","ru":"В ванной нет окна, и существующая вытяжка почти не удаляет воздух во время душа.","pronunciation":"эл ба́ньо но тиэ́нэ бэнта́на и эл экстракто́р актуа́л ка́си но са́ка а́ирэ куа́ндо нос дуча́мос.","id":"d09-027"},{"speaker":"serguei","es":"Revisamos el conducto, la salida y el funcionamiento antes de confirmar el nuevo extractor y sus conexiones.","ru":"Проверим канал, выход и работу системы до выбора нового вентилятора и подключений.","pronunciation":"ррэбиса́мос эл конду́кто, ла сали́да и эл фунсионамиэ́нто а́нтэс дэ конфирма́р эл нуэ́бо экстракто́р и сус конэксио́нэс.","id":"d09-028"},{"speaker":"client","es":"Quiero que el presupuesto separe el desmontaje de los equipos antiguos y el montaje de los nuevos.","ru":"Хочу разделить в смете снятие старого оборудования и монтаж нового.","pronunciation":"киэ́ро кэ эл прэсупуэ́сто сэпа́рэ эл дэсмонта́хэ дэ лос эки́пос анти́гуос и эл монта́хэ дэ лос нуэ́бос.","id":"d09-029"},{"speaker":"serguei","es":"Sí, también indicamos los recorridos nuevos, los equipos auxiliares y los remates que estén incluidos.","ru":"Да, также укажем новые трассы, вспомогательное оборудование и включённые отделочные работы.","pronunciation":"си́, тамбиэ́н индика́мос лос ррэкорри́дос нуэ́бос, лос эки́пос ауксилиа́рэс и лос ррэма́тэс кэ эстэ́н инклуи́дос.","id":"d09-030"},{"speaker":"client","es":"¿Quién se encarga del refrigerante cuando se retiran los equipos que están instalados ahora?","ru":"Кто занимается хладагентом при снятии существующего оборудования?","pronunciation":"киэ́н сэ энка́рга дэл ррэфрихэра́нтэ куа́ндо сэ ррэти́ран лос эки́пос кэ эста́н инстала́дос ао́ра?","id":"d09-031"},{"speaker":"serguei","es":"Lo realiza el profesional habilitado y coordinamos su intervención antes de desmontar o cortar las líneas.","ru":"Это выполняет уполномоченный специалист; согласуем его работу до снятия или разрезания трасс.","pronunciation":"ло ррэали́са эл профэсиона́л абилита́до и координа́мос су интэрбэнсио́н а́нтэс дэ дэсмонта́р о корта́р лас ли́нэас.","id":"d09-032"},{"speaker":"client","es":"Cuando todo esté montado, quiero aprender a usar el mando, limpiar los filtros y detectar cualquier aviso.","ru":"После монтажа хочу научиться пользоваться пультом, чистить фильтры и распознавать предупреждения.","pronunciation":"куа́ндо то́до эстэ́ монта́до, киэ́ро апрэндэ́р а уса́р эл ма́ндо, лимпиа́р лос фи́лтрос и дэтэкта́р куалкиэ́р аби́со.","id":"d09-033"},{"speaker":"serguei","es":"Organizamos la puesta en marcha y entregamos la documentación y las indicaciones de mantenimiento correspondientes.","ru":"Организуем запуск и передадим соответствующие документы и указания по обслуживанию.","pronunciation":"органиса́мос ла пуэ́ста эн ма́рча и энтрэга́мос ла докумэнтасио́н и лас индикасио́нэс дэ мантэнимиэ́нто коррэспондиэ́нтэс.","id":"d09-034"}],"words":481,"minutes":5},{"lesson":10,"title":"Плитка, гидроизоляция и примыкания","setting":"Выбор керамогранита, раскладка, швы, душ и сроки использования.","sentences":[{"speaker":"client","es":"Me gusta este gres porcelánico grande y quiero ponerlo en el suelo y en la pared de la ducha.","ru":"Мне нравится этот крупный керамогранит, хочу его на полу и на стене душа.","pronunciation":"мэ гу́ста э́стэ грэс порсэла́нико гра́ндэ и киэ́ро понэ́рло эн эл суэ́ло и эн ла парэ́д дэ ла ду́ча.","id":"d10-001"},{"speaker":"serguei","es":"Revisamos el formato, las medidas del baño y el despiece antes de confirmar la cantidad del pedido.","ru":"Проверим формат, размеры ванной и раскладку до подтверждения количества для заказа.","pronunciation":"ррэбиса́мос эл форма́то, лас мэди́дас дэл ба́ньо и эл дэспиэ́сэ а́нтэс дэ конфирма́р ла кантида́д дэл пэди́до.","id":"d10-002"},{"speaker":"client","es":"Quiero que la veta continúe entre las piezas y que los cortes no queden en el centro de la pared.","ru":"Хочу продолжение рисунка между плитами и чтобы подрезки не оказались посередине стены.","pronunciation":"киэ́ро кэ ла бэ́та контину́э э́нтрэ лас пиэ́сас и кэ лос ко́ртэс но кэ́дэн эн эл сэ́нтро дэ ла парэ́д.","id":"d10-003"},{"speaker":"serguei","es":"Tenemos que comprobar las piezas disponibles y presentar una propuesta de colocación antes de cortar el material.","ru":"Нужно проверить доступные плиты и представить раскладку до резки материала.","pronunciation":"тэнэ́мос кэ компроба́р лас пиэ́сас диспони́блэс и прэсэнта́р у́на пропуэ́ста дэ колокасио́н а́нтэс дэ корта́р эл матэриа́л.","id":"d10-004"},{"speaker":"client","es":"Para el suelo prefiero un acabado mate, pero necesito que sea adecuado para la zona donde usamos la ducha.","ru":"Для пола предпочитаю матовый финиш, но он должен подходить для зоны душа.","pronunciation":"па́ра эл суэ́ло прэфиэ́ро ун акаба́до ма́тэ, пэ́ро нэсэси́то кэ сэ́а адэкуа́до па́ра ла со́на до́ндэ уса́мос ла ду́ча.","id":"d10-005"},{"speaker":"serguei","es":"Consultamos la documentación del producto para confirmar sus características y no elegimos solo por el aspecto.","ru":"Проверим характеристики по документации изделия, а не будем выбирать только по виду.","pronunciation":"консулта́мос ла докумэнтасио́н дэл проду́кто па́ра конфирма́р сус карактэри́стикас и но элэхи́мос со́ло пор эл аспэ́кто.","id":"d10-006"},{"speaker":"client","es":"En la pared del lavabo me gustaría poner mármol natural en lugar de la misma cerámica.","ru":"На стене у раковины хочу натуральный мрамор вместо той же керамики.","pronunciation":"эн ла парэ́д дэл лаба́бо мэ густари́а понэ́р ма́рмол натура́л эн луга́р дэ ла ми́сма сэра́мика.","id":"d10-007"},{"speaker":"serguei","es":"Revisamos la muestra, el uso previsto y el mantenimiento de la piedra natural antes de confirmar esa alternativa.","ru":"Проверим образец, условия использования и уход за натуральным камнем до согласования варианта.","pronunciation":"ррэбиса́мос ла муэ́стра, эл у́со прэби́сто и эл мантэнимиэ́нто дэ ла пиэ́дра натура́л а́нтэс дэ конфирма́р э́са алтэрнати́ба.","id":"d10-008"},{"speaker":"client","es":"¿El color de la junta puede ser parecido al de la pieza para que el conjunto se vea más uniforme?","ru":"Можно подобрать шов близко к цвету плитки, чтобы поверхность выглядела однороднее?","pronunciation":"эл коло́р дэ ла ху́нта пуэ́дэ сэр парэси́до ал дэ ла пиэ́са па́ра кэ эл конху́нто сэ бэ́а ма́с унифо́рмэ?","id":"d10-009"},{"speaker":"serguei","es":"Elegimos el material de rejuntado y el color con una muestra, teniendo en cuenta el sistema previsto.","ru":"Выберем затирочный материал и цвет по образцу с учётом предусмотренной системы.","pronunciation":"элэхи́мос эл матэриа́л дэ ррэхунта́до и эл коло́р кон у́на муэ́стра, тэниэ́ндо эн куэ́нта эл систэ́ма прэби́сто.","id":"d10-010"},{"speaker":"client","es":"Me preocupa especialmente el encuentro del suelo con las paredes y la esquina donde está el plato.","ru":"Особенно беспокоят примыкание пола к стенам и угол возле поддона.","pronunciation":"мэ прэоку́па эспэсиалмэ́нтэ эл энкуэ́нтро дэл суэ́ло кон лас парэ́дэс и ла эски́на до́ндэ эста́ эл пла́то.","id":"d10-011"},{"speaker":"serguei","es":"Definimos la impermeabilización y sus encuentros antes de colocar las piezas para no resolverlos al final.","ru":"Определим гидроизоляцию и примыкания до укладки плитки, не оставляя их на конец.","pronunciation":"дэфини́мос ла импэрмэабилисасио́н и сус энкуэ́нтрос а́нтэс дэ колока́р лас пиэ́сас па́ра но ррэсолбэ́рлос ал фина́л.","id":"d10-012"},{"speaker":"client","es":"¿Se puede poner la baldosa nueva sobre la antigua?","ru":"Можно положить новую плитку на старую?","pronunciation":"сэ пуэ́дэ понэ́р ла балдо́са нуэ́ба со́брэ ла анти́гуа?","id":"d10-013"},{"speaker":"serguei","es":"Depende del soporte, la adherencia, las alturas y el sistema; hay que comprobarlo.","ru":"Зависит от основания, сцепления, высот и системы; нужно проверить.","pronunciation":"дэпэ́ндэ дэл сопо́ртэ, ла адэрэ́нсиа, лас алту́рас и эл систэ́ма; аи кэ компроба́рло.","id":"d10-014"},{"speaker":"client","es":"¿Por qué quedan juntas?","ru":"Почему остаются швы?","pronunciation":"пор кэ́ кэ́дан ху́нтас?","id":"d10-015"},{"speaker":"serguei","es":"La junta forma parte de la solución; confirmamos su ancho y tipo con el proyecto y la documentación del material.","ru":"Шов — часть решения; ширину и тип согласуем с проектом и документацией материала.","pronunciation":"ла ху́нта фо́рма па́ртэ дэ ла солусио́н; конфирма́мос су а́нчо и ти́по кон эл пройэ́кто и ла докумэнтасио́н дэл матэриа́л.","id":"d10-016"},{"speaker":"client","es":"¿Podemos hacer el suelo sin pendiente visible?","ru":"Можно без заметного уклона?","pronunciation":"подэ́мос асэ́р эл суэ́ло син пэндиэ́нтэ биси́блэ?","id":"d10-017"},{"speaker":"serguei","es":"En la ducha hay que resolver la evacuación y coordinarla con el acabado.","ru":"В душе нужно решить водоотвод и согласовать с отделкой.","pronunciation":"эн ла ду́ча аи кэ ррэсолбэ́р ла эбакуасио́н и координа́рла кон эл акаба́до.","id":"d10-018"},{"speaker":"client","es":"¿Cuándo puedo usar la ducha?","ru":"Когда можно пользоваться душем?","pronunciation":"куа́ндо пуэ́до уса́р ла ду́ча?","id":"d10-019"},{"speaker":"serguei","es":"Confirmamos el plazo según los materiales colocados y su documentación, y se lo dejamos por escrito.","ru":"Срок подтвердим по применённым материалам и техдокументации и запишем.","pronunciation":"конфирма́мос эл пла́со сэгу́н лос матэриа́лэс колока́дос и су докумэнтасио́н, и сэ ло дэха́мос пор эскри́то.","id":"d10-020"},{"speaker":"client","es":"¿Por qué hay que comprar más metros de los que mide el baño?","ru":"Зачем покупать больше площади ванной?","pronunciation":"пор кэ́ аи кэ компра́р ма́с мэ́трос дэ лос кэ ми́дэ эл ба́ньо?","id":"d10-021"},{"speaker":"serguei","es":"Hay cortes y posibles reservas; calculamos la cantidad según el despiece, sin aplicar un porcentaje fijo a todos los casos.","ru":"Есть подрезки и возможный запас; считаем по раскладке без универсального процента.","pronunciation":"аи ко́ртэс и поси́блэс ррэсэ́рбас; калкула́мос ла кантида́д сэгу́н эл дэспиэ́сэ, син аплика́р ун порсэнта́хэ фи́хо а то́дос лос ка́сос.","id":"d10-022"},{"speaker":"client","es":"¿Esta mancha es un defecto del mármol?","ru":"Это пятно — дефект мрамора?","pronunciation":"э́ста ма́нча эс ун дэфэ́кто дэл ма́рмол?","id":"d10-023"},{"speaker":"serguei","es":"Lo comparamos con la muestra y la documentación y consultamos al proveedor antes de concluir.","ru":"Сравним с образцом и документацией и уточним у поставщика до вывода.","pronunciation":"ло компара́мос кон ла муэ́стра и ла докумэнтасио́н и консулта́мос ал пробээдо́р а́нтэс дэ конклуи́р.","id":"d10-024"},{"speaker":"client","es":"Quiero revisar también si la esquina exterior lleva un perfil de remate o un acabado diferente.","ru":"Хочу также уточнить, будет ли на наружном углу завершающий профиль или другой узел.","pronunciation":"киэ́ро ррэбиса́р тамбиэ́н си ла эски́на экстэрио́р йэ́ба ун пэрфи́л дэ ррэма́тэ о ун акаба́до дифэрэ́нтэ.","id":"d10-025"},{"speaker":"serguei","es":"Confirmamos el detalle y su coste antes de cortar las piezas y preparar los remates.","ru":"Подтвердим узел и стоимость до резки плитки и подготовки примыканий.","pronunciation":"конфирма́мос эл дэта́йэ и су ко́стэ а́нтэс дэ корта́р лас пиэ́сас и прэпара́р лос ррэма́тэс.","id":"d10-026"},{"speaker":"client","es":"¿Quién comprueba que el soporte está preparado antes de aplicar el adhesivo cementoso?","ru":"Кто проверяет подготовку основания перед нанесением цементного плиточного клея?","pronunciation":"киэ́н компруэ́ба кэ эл сопо́ртэ эста́ прэпара́до а́нтэс дэ аплика́р эл адэси́бо сэмэнто́со?","id":"d10-027"},{"speaker":"serguei","es":"Revisamos el soporte y la compatibilidad de los productos con el sistema y la documentación del fabricante.","ru":"Проверим основание и совместимость материалов с системой и документацией изготовителя.","pronunciation":"ррэбиса́мос эл сопо́ртэ и ла компатибилида́д дэ лос проду́ктос кон эл систэ́ма и ла докумэнтасио́н дэл фабрика́нтэ.","id":"d10-028"},{"speaker":"client","es":"Si una pieza se rompe durante los cortes, quiero saber cómo afecta al dibujo de la pared.","ru":"Если плита сломается при резке, хочу понимать влияние на рисунок стены.","pronunciation":"си у́на пиэ́са сэ рро́мпэ дура́нтэ лос ко́ртэс, киэ́ро сабэ́р ко́мо афэ́кта ал дибу́хо дэ ла парэ́д.","id":"d10-029"},{"speaker":"serguei","es":"Por eso confirmamos el despiece, las reservas y la disponibilidad del lote antes de empezar.","ru":"Поэтому до начала подтверждаем раскладку, запас и доступность партии.","pronunciation":"пор э́со конфирма́мос эл дэспиэ́сэ, лас ррэсэ́рбас и ла диспонибилида́д дэл ло́тэ а́нтэс дэ эмпэса́р.","id":"d10-030"},{"speaker":"client","es":"Me gustaría ver las primeras piezas presentadas antes de seguir con todo el alicatado.","ru":"Хочу увидеть предварительную раскладку первых плит перед продолжением всей облицовки.","pronunciation":"мэ густари́а бэр лас примэ́рас пиэ́сас прэсэнта́дас а́нтэс дэ сэги́р кон то́до эл аликата́до.","id":"d10-031"},{"speaker":"serguei","es":"Sí, revisamos juntos la posición, las juntas y los encuentros para confirmar que coinciden con lo aprobado.","ru":"Да, вместе проверим положение, швы и примыкания на соответствие согласованному решению.","pronunciation":"си́, ррэбиса́мос ху́нтос ла посисио́н, лас ху́нтас и лос энкуэ́нтрос па́ра конфирма́р кэ коинси́дэн кон ло апроба́до.","id":"d10-032"},{"speaker":"client","es":"Al terminar necesito instrucciones claras para limpiar la piedra y las juntas sin estropear el acabado.","ru":"В конце нужны понятные инструкции по очистке камня и швов без повреждения финиша.","pronunciation":"ал тэрмина́р нэсэси́то инструксио́нэс кла́рас па́ра лимпиа́р ла пиэ́дра и лас ху́нтас син эстропэа́р эл акаба́до.","id":"d10-033"},{"speaker":"serguei","es":"Le entregamos las indicaciones de uso y mantenimiento de los materiales realmente colocados en el baño.","ru":"Передадим указания по эксплуатации и уходу за фактически уложенными материалами.","pronunciation":"лэ энтрэга́мос лас индикасио́нэс дэ у́со и мантэнимиэ́нто дэ лос матэриа́лэс ррэалмэ́нтэ колока́дос эн эл ба́ньо.","id":"d10-034"}],"words":510,"minutes":5},{"lesson":11,"title":"Паркет, основание и отметки пола","setting":"Паркетная доска, подложка, перепады, остаточная влажность и двери.","sentences":[{"speaker":"client","es":"Quiero poner parquet multicapa de quince milímetros porque prefiero madera en el salón y en los dormitorios.","ru":"Хочу уложить паркетную доску 15 миллиметров, предпочитаю дерево в гостиной и спальнях.","pronunciation":"киэ́ро понэ́р паркэ́т мултика́па дэ ки́нсэ мили́мэтрос по́ркэ прэфиэ́ро мадэ́ра эн эл сало́н и эн лос дормито́риос.","id":"d11-001"},{"speaker":"serguei","es":"Revisamos la ficha del parquet y la altura disponible antes de confirmar todas las capas del suelo.","ru":"Проверим документацию доски и доступную высоту до подтверждения всех слоёв пола.","pronunciation":"ррэбиса́мос ла фи́ча дэл паркэ́т и ла алту́ра диспони́блэ а́нтэс дэ конфирма́р то́дас лас ка́пас дэл суэ́ло.","id":"d11-002"},{"speaker":"client","es":"Prefiero colocación flotante y quiero aprovechar la base si no hace falta retirarlo todo.","ru":"Предпочитаю плавающую укладку и хочу сохранить основание, если можно не убирать всё.","pronunciation":"прэфиэ́ро колокасио́н флота́нтэ и киэ́ро апробэча́р ла ба́сэ си но а́сэ фа́лта ррэтира́рло то́до.","id":"d11-003"},{"speaker":"serguei","es":"Cuando dice base, ¿se refiere a la manta que hay debajo del parquet o al soporte de la vivienda?","ru":"Когда вы говорите «основание», имеете в виду подложку под доской или основание квартиры?","pronunciation":"куа́ндо ди́сэ ба́сэ, сэ ррэфиэ́рэ а ла ма́нта кэ аи дэба́хо дэл паркэ́т о ал сопо́ртэ дэ ла бибиэ́нда?","id":"d11-004"},{"speaker":"client","es":"Me refiero a la solera, porque parece firme aunque tiene algunas grietas y diferencias de altura.","ru":"Имею в виду стяжку: кажется прочной, хотя есть трещины и перепады высоты.","pronunciation":"мэ ррэфиэ́ро а ла солэ́ра, по́ркэ парэ́сэ фи́рмэ а́ункэ тиэ́нэ алгу́нас гриэ́тас и дифэрэ́нсиас дэ алту́ра.","id":"d11-005"},{"speaker":"serguei","es":"Comprobamos el estado, la planeidad y la humedad residual antes de definir la preparación compatible con el sistema.","ru":"Проверим состояние, плоскостность и остаточную влажность до определения подготовки под систему.","pronunciation":"компроба́мос эл эста́до, ла планэида́д и ла умэда́д ррэсидуа́л а́нтэс дэ дэфини́р ла прэпарасио́н компати́блэ кон эл систэ́ма.","id":"d11-006"},{"speaker":"client","es":"En la cocina hay cerámica nueva y no quiero encontrar un escalón al pasar desde el salón.","ru":"На кухне новая плитка, не хочу ступеньки при переходе из гостиной.","pronunciation":"эн ла коси́на аи сэра́мика нуэ́ба и но киэ́ро энконтра́р ун эскало́н ал паса́р дэ́сдэ эл сало́н.","id":"d11-007"},{"speaker":"serguei","es":"Medimos las cotas terminadas y revisamos el encuentro entre los dos pavimentos antes de decidir la solución.","ru":"Измерим чистовые отметки и проверим переход между покрытиями до выбора решения.","pronunciation":"мэди́мос лас ко́тас тэрмина́дас и ррэбиса́мос эл энкуэ́нтро э́нтрэ лос дос пабимэ́нтос а́нтэс дэ дэсиди́р ла солусио́н.","id":"d11-008"},{"speaker":"client","es":"También he visto vinilo rígido y laminado, pero no entiendo cómo cambia la altura con cada opción.","ru":"Ещё видел жёсткий винил и ламинат, но не понимаю изменение высоты в каждом варианте.","pronunciation":"тамбиэ́н э би́сто бини́ло рри́хидо и ламина́до, пэ́ро но энтиэ́ндо ко́мо ка́мбиа ла алту́ра кон ка́да опсио́н.","id":"d11-009"},{"speaker":"serguei","es":"Comparamos el espesor del revestimiento y las capas necesarias, no solo el grosor visible de la pieza.","ru":"Сравним толщину покрытия и необходимых слоёв, а не только видимую толщину изделия.","pronunciation":"компара́мос эл эспэсо́р дэл ррэбэстимиэ́нто и лас ка́пас нэсэса́риас, но со́ло эл гросо́р биси́блэ дэ ла пиэ́са.","id":"d11-010"},{"speaker":"client","es":"Debajo del suelo antiguo había restos dañados y quiero estar seguro de revisar el problema antes de taparlo.","ru":"Под старым полом были повреждённые остатки, хочу проверить проблему до закрытия.","pronunciation":"дэба́хо дэл суэ́ло анти́гуо аби́а ррэ́стос даньа́дос и киэ́ро эста́р сэгу́ро дэ ррэбиса́р эл проблэ́ма а́нтэс дэ тапа́рло.","id":"d11-011"},{"speaker":"serguei","es":"Lo dejamos anotado y confirmamos la intervención necesaria antes de preparar y cerrar el soporte.","ru":"Зафиксируем это и подтвердим необходимые действия до подготовки и закрытия основания.","pronunciation":"ло дэха́мос анота́до и конфирма́мос ла интэрбэнсио́н нэсэса́риа а́нтэс дэ прэпара́р и сэрра́р эл сопо́ртэ.","id":"d11-012"},{"speaker":"client","es":"¿Podemos poner el suelo mañana?","ru":"Можно завтра укладывать пол?","pronunciation":"подэ́мос понэ́р эл суэ́ло маньа́на?","id":"d11-013"},{"speaker":"serguei","es":"Depende del producto aplicado, las condiciones y las comprobaciones del soporte.","ru":"Зависит от материала, условий и проверок основания.","pronunciation":"дэпэ́ндэ дэл проду́кто аплика́до, лас кондисио́нэс и лас компробасио́нэс дэл сопо́ртэ.","id":"d11-014"},{"speaker":"client","es":"¿El vinilo no necesita nivelar?","ru":"Под винил не нужно выравнивать?","pronunciation":"эл бини́ло но нэсэси́та нибэла́р?","id":"d11-015"},{"speaker":"serguei","es":"También necesita un soporte adecuado; comprobamos las tolerancias del sistema elegido.","ru":"Ему тоже нужно подходящее основание; проверим допуски выбранной системы.","pronunciation":"тамбиэ́н нэсэси́та ун сопо́ртэ адэкуа́до; компроба́мос лас толэра́нсиас дэл систэ́ма элэхи́до.","id":"d11-016"},{"speaker":"client","es":"¿Se puede poner todo sin perfiles en las puertas?","ru":"Можно везде без профилей в дверях?","pronunciation":"сэ пуэ́дэ понэ́р то́до син пэрфи́лэс эн лас пуэ́ртас?","id":"d11-017"},{"speaker":"serguei","es":"Revisamos superficies, pasos, juntas y condiciones del fabricante antes de confirmarlo.","ru":"До подтверждения проверим площади, переходы, швы и условия изготовителя.","pronunciation":"ррэбиса́мос супэрфи́сиэс, па́сос, ху́нтас и кондисио́нэс дэл фабрика́нтэ а́нтэс дэ конфирма́рло.","id":"d11-018"},{"speaker":"client","es":"¿La madera va a moverse?","ru":"Дерево будет двигаться?","pronunciation":"ла мадэ́ра ба а мобэ́рсэ?","id":"d11-019"},{"speaker":"serguei","es":"La madera responde a las condiciones ambientales; elegimos el sistema y el mantenimiento adecuados.","ru":"Дерево реагирует на условия среды; подбираем систему и уход.","pronunciation":"ла мадэ́ра ррэспо́ндэ а лас кондисио́нэс амбиэнта́лэс; элэхи́мос эл систэ́ма и эл мантэнимиэ́нто адэкуа́дос.","id":"d11-020"},{"speaker":"client","es":"¿Qué hacemos si había termitas?","ru":"Что делать, если были термиты?","pronunciation":"кэ́ асэ́мос си аби́а тэрми́тас?","id":"d11-021"},{"speaker":"serguei","es":"Antes de cerrar, confirmamos el estado del problema y la intervención necesaria con una empresa especializada.","ru":"До закрытия проверим состояние проблемы и нужную обработку со специализированной компанией.","pronunciation":"а́нтэс дэ сэрра́р, конфирма́мос эл эста́до дэл проблэ́ма и ла интэрбэнсио́н нэсэса́риа кон у́на эмпрэ́са эспэсиалиса́да.","id":"d11-022"},{"speaker":"client","es":"¿Hay que cortar las puertas?","ru":"Нужно подрезать двери?","pronunciation":"аи кэ корта́р лас пуэ́ртас?","id":"d11-023"},{"speaker":"serguei","es":"Lo comprobamos con la altura final de todas las capas y los encuentros.","ru":"Проверим по итоговой высоте всех слоёв и примыканиям.","pronunciation":"ло компроба́мос кон ла алту́ра фина́л дэ то́дас лас ка́пас и лос энкуэ́нтрос.","id":"d11-024"},{"speaker":"client","es":"¿Qué diferencia hay entre alisar la superficie y nivelar todo el suelo hasta la misma cota?","ru":"Чем отличается сглаживание поверхности от выравнивания всего пола до одной отметки?","pronunciation":"кэ́ дифэрэ́нсиа аи э́нтрэ алиса́р ла супэрфи́сиэ и нибэла́р то́до эл суэ́ло а́ста ла ми́сма ко́та?","id":"d11-025"},{"speaker":"serguei","es":"Definimos el objetivo de planeidad y de nivel para elegir la preparación que necesita el revestimiento.","ru":"Определим требования к плоскостности и уровню для выбора подготовки под покрытие.","pronunciation":"дэфини́мос эл обхэти́бо дэ планэида́д и дэ нибэ́л па́ра элэхи́р ла прэпарасио́н кэ нэсэси́та эл ррэбэстимиэ́нто.","id":"d11-026"},{"speaker":"client","es":"Quiero saber si utilizan una pasta autonivelante, otro recrecido o reparaciones en zonas concretas.","ru":"Хочу знать, применяется ли самонивелирующаяся смесь, другая стяжка или локальный ремонт.","pronunciation":"киэ́ро сабэ́р си утили́сан у́на па́ста аутонибэла́нтэ, о́тро ррэкрэси́до о ррэпарасио́нэс эн со́нас конкрэ́тас.","id":"d11-027"},{"speaker":"serguei","es":"Lo confirmamos con el estado del soporte, los espesores y la compatibilidad indicada para los productos.","ru":"Уточним по состоянию основания, толщинам и указанной совместимости материалов.","pronunciation":"ло конфирма́мос кон эл эста́до дэл сопо́ртэ, лос эспэсо́рэс и ла компатибилида́д индика́да па́ра лос проду́ктос.","id":"d11-028"},{"speaker":"client","es":"El rodapié tiene que combinar con las puertas y quiero ver el perfil de transición antes de comprarlo.","ru":"Плинтус должен сочетаться с дверями, а переходный профиль хочу увидеть до покупки.","pronunciation":"эл рродапиэ́ тиэ́нэ кэ комбина́р кон лас пуэ́ртас и киэ́ро бэр эл пэрфи́л дэ трансисио́н а́нтэс дэ компра́рло.","id":"d11-029"},{"speaker":"serguei","es":"Elegimos los remates y respetamos las juntas previstas por el sistema, incluida la junta perimetral.","ru":"Выберем примыкания и сохраним предусмотренные системой швы, включая периметральный.","pronunciation":"элэхи́мос лос ррэма́тэс и ррэспэта́мос лас ху́нтас прэби́стас пор эл систэ́ма, инклуи́да ла ху́нта пэримэтра́л.","id":"d11-030"},{"speaker":"client","es":"Antes de traer los muebles, necesito saber cuándo se puede pisar y cuándo podemos usar las habitaciones.","ru":"До доставки мебели мне нужно знать, когда можно ходить и пользоваться комнатами.","pronunciation":"а́нтэс дэ траэ́р лос муэ́блэс, нэсэси́то сабэ́р куа́ндо сэ пуэ́дэ писа́р и куа́ндо подэ́мос уса́р лас абитасио́нэс.","id":"d11-031"},{"speaker":"serguei","es":"Le confirmo los plazos según los productos utilizados y las condiciones comprobadas en la vivienda.","ru":"Подтвержу сроки по использованным материалам и проверенным условиям квартиры.","pronunciation":"лэ конфи́рмо лос пла́сос сэгу́н лос проду́ктос утилиса́дос и лас кондисио́нэс компроба́дас эн ла бибиэ́нда.","id":"d11-032"},{"speaker":"client","es":"De acuerdo, quiero decidir con las alturas y las comprobaciones claras antes de pedir todo el parquet.","ru":"Хорошо, хочу решить вопрос отметок и проверок до заказа всей паркетной доски.","pronunciation":"дэ акуэ́рдо, киэ́ро дэсиди́р кон лас алту́рас и лас компробасио́нэс кла́рас а́нтэс дэ пэди́р то́до эл паркэ́т.","id":"d11-033"},{"speaker":"serguei","es":"Le envío las medidas, la solución propuesta y los puntos pendientes para aprobar el sistema completo.","ru":"Отправлю размеры, предложенное решение и нерешённые пункты для согласования всей системы.","pronunciation":"лэ энби́о лас мэди́дас, ла солусио́н пропуэ́ста и лос пу́нтос пэндиэ́нтэс па́ра апроба́р эл систэ́ма комплэ́то.","id":"d11-034"}],"words":472,"minutes":5},{"lesson":12,"title":"Гладкие стены, потолки и покраска","setting":"Убираем gotelé, обсуждаем гипсокартон, усиления, образцы и финиш.","sentences":[{"speaker":"client","es":"Quiero quitar el gotelé del salón y del pasillo para que las paredes queden lisas antes de pintar.","ru":"Хочу убрать фактурное покрытие в гостиной и коридоре, чтобы стены были гладкими перед покраской.","pronunciation":"киэ́ро кита́р эл готэлэ́ дэл сало́н и дэл паси́йо па́ра кэ лас парэ́дэс кэ́дэн ли́сас а́нтэс дэ пинта́р.","id":"d12-001"},{"speaker":"serguei","es":"Primero revisamos el soporte y definimos el acabado esperado y las zonas incluidas en el trabajo.","ru":"Сначала проверим основание и определим ожидаемый финиш и включённые зоны.","pronunciation":"примэ́ро ррэбиса́мос эл сопо́ртэ и дэфини́мос эл акаба́до эспэра́до и лас со́нас инклуи́дас эн эл траба́хо.","id":"d12-002"},{"speaker":"client","es":"No necesito corregir toda la geometría de la vivienda, pero sí quiero una superficie visualmente uniforme.","ru":"Мне не нужно исправлять всю геометрию квартиры, но нужна визуально однородная поверхность.","pronunciation":"но нэсэси́то коррэхи́р то́да ла хэомэтри́а дэ ла бибиэ́нда, пэ́ро си́ киэ́ро у́на супэрфи́сиэ бисуалмэ́нтэ унифо́рмэ.","id":"d12-003"},{"speaker":"serguei","es":"Lo dejamos por escrito para distinguir el alisado de una corrección completa de niveles y verticalidad.","ru":"Зафиксируем это, отделив сглаживание от полного исправления уровней и вертикали.","pronunciation":"ло дэха́мос пор эскри́то па́ра дистинги́р эл алиса́до дэ у́на коррэксио́н комплэ́та дэ нибэ́лэс и бэртикалида́д.","id":"d12-004"},{"speaker":"client","es":"También quiero un falso techo en el pasillo para ocultar los recorridos de las instalaciones.","ru":"Ещё хочу подвесной потолок в коридоре, чтобы скрыть трассы коммуникаций.","pronunciation":"тамбиэ́н киэ́ро ун фа́лсо тэ́чо эн эл паси́йо па́ра окулта́р лос ррэкорри́дос дэ лас инсталасио́нэс.","id":"d12-005"},{"speaker":"serguei","es":"Coordinamos la perfilería, las placas de yeso laminado y los accesos de mantenimiento antes del montaje.","ru":"Согласуем каркас, гипсокартонные плиты и доступы для обслуживания до монтажа.","pronunciation":"координа́мос ла пэрфилэри́а, лас пла́кас дэ йэ́со ламина́до и лос аксэ́сос дэ мантэнимиэ́нто а́нтэс дэл монта́хэ.","id":"d12-006"},{"speaker":"client","es":"En el salón me gustaría una moldura con luz indirecta y un cortinero para las cortinas largas.","ru":"В гостиной хочу молдинг со скрытым светом и нишу для длинных штор.","pronunciation":"эн эл сало́н мэ густари́а у́на молду́ра кон лус индирэ́кта и ун кортинэ́ро па́ра лас корти́нас ла́ргас.","id":"d12-007"},{"speaker":"serguei","es":"Necesitamos la sección del detalle, la posición del carril y los refuerzos antes de cerrar el techo.","ru":"Нужны разрез узла, положение шины и усиления до зашивки потолка.","pronunciation":"нэсэсита́мос ла сэксио́н дэл дэта́йэ, ла посисио́н дэл карри́л и лос ррэфуэ́рсос а́нтэс дэ сэрра́р эл тэ́чо.","id":"d12-008"},{"speaker":"client","es":"¿El trasdosado de esta pared lleva lana mineral o solo una placa delante de la pared existente?","ru":"В облицовке этой стены будет минеральная вата или только плита перед существующей стеной?","pronunciation":"эл трасдоса́до дэ э́ста парэ́д йэ́ба ла́на минэра́л о со́ло у́на пла́ка дэла́нтэ дэ ла парэ́д эксистэ́нтэ?","id":"d12-009"},{"speaker":"serguei","es":"Confirmamos el sistema completo y el objetivo de aislamiento para no elegir las capas de forma aislada.","ru":"Уточним всю систему и цель изоляции, чтобы не выбирать слои по отдельности.","pronunciation":"конфирма́мос эл систэ́ма комплэ́то и эл обхэти́бо дэ аисламиэ́нто па́ра но элэхи́р лас ка́пас дэ фо́рма аисла́да.","id":"d12-010"},{"speaker":"client","es":"Quiero que se distingan en la propuesta la preparación de juntas, la masilla y la pintura final.","ru":"Хочу разделить в предложении подготовку швов, шпаклёвку и финишную окраску.","pronunciation":"киэ́ро кэ сэ дисти́нган эн ла пропуэ́ста ла прэпарасио́н дэ ху́нтас, ла маси́йа и ла пинту́ра фина́л.","id":"d12-011"},{"speaker":"serguei","es":"Describimos la cinta de juntas, la pasta, el lijado y la imprimación según el sistema previsto.","ru":"Опишем шовную ленту, состав, шлифовку и грунтование по предусмотренной системе.","pronunciation":"дэскриби́мос ла си́нта дэ ху́нтас, ла па́ста, эл лиха́до и ла импримасио́н сэгу́н эл систэ́ма прэби́сто.","id":"d12-012"},{"speaker":"client","es":"¿Cuántas manos de pintura incluye?","ru":"Сколько слоёв краски включено?","pronunciation":"куа́нтас ма́нос дэ пинту́ра инклу́йэ?","id":"d12-013"},{"speaker":"serguei","es":"La propuesta indica la preparación y las manos previstas; lo ajustamos al producto y al soporte.","ru":"В предложении указаны подготовка и предусмотренные слои; учитываем материал и основание.","pronunciation":"ла пропуэ́ста инди́ка ла прэпарасио́н и лас ма́нос прэби́стас; ло ахуста́мос ал проду́кто и ал сопо́ртэ.","id":"d12-014"},{"speaker":"client","es":"¿Puede quedar totalmente liso?","ru":"Можно сделать полностью гладко?","pronunciation":"пуэ́дэ кэда́р тоталмэ́нтэ ли́со?","id":"d12-015"},{"speaker":"serguei","es":"Definimos el acabado esperado y revisamos el soporte y las condiciones de iluminación.","ru":"Согласуем ожидаемый финиш и проверим основание и освещение.","pronunciation":"дэфини́мос эл акаба́до эспэра́до и ррэбиса́мос эл сопо́ртэ и лас кондисио́нэс дэ илуминасио́н.","id":"d12-016"},{"speaker":"client","es":"¿Va a quitar el ruido de los vecinos?","ru":"Это уберёт шум от соседей?","pronunciation":"ба а кита́р эл рруи́до дэ лос бэси́нос?","id":"d12-017"},{"speaker":"serguei","es":"Hay que estudiar cómo se transmite el ruido; una solución parcial no garantiza eliminarlo.","ru":"Нужно изучить пути передачи шума; частичное решение не гарантирует его устранение.","pronunciation":"аи кэ эстудиа́р ко́мо сэ трансми́тэ эл рруи́до; у́на солусио́н парсиа́л но гаранти́са элимина́рло.","id":"d12-018"},{"speaker":"client","es":"¿Podemos colgar un mueble aquí?","ru":"Можно здесь повесить мебель?","pronunciation":"подэ́мос колга́р ун муэ́блэ аки́?","id":"d12-019"},{"speaker":"serguei","es":"Confirmamos su peso, el sistema de pared y los refuerzos antes de cerrar.","ru":"До зашивки подтвердим вес, систему стены и усиления.","pronunciation":"конфирма́мос су пэ́со, эл систэ́ма дэ парэ́д и лос ррэфуэ́рсос а́нтэс дэ сэрра́р.","id":"d12-020"},{"speaker":"client","es":"¿La pintura tapa el moho?","ru":"Краска закроет плесень?","pronunciation":"ла пинту́ра та́па эл мо́о?","id":"d12-021"},{"speaker":"serguei","es":"Primero revisamos y resolvemos la causa; después definimos la preparación y la pintura.","ru":"Сначала проверяем и устраняем причину, затем выбираем подготовку и краску.","pronunciation":"примэ́ро ррэбиса́мос и ррэсолбэ́мос ла ка́уса; дэспуэ́с дэфини́мос ла прэпарасио́н и ла пинту́ра.","id":"d12-022"},{"speaker":"client","es":"¿Por qué el blanco se ve distinto?","ru":"Почему белый выглядит иначе?","pronunciation":"пор кэ́ эл бла́нко сэ бэ дисти́нто?","id":"d12-023"},{"speaker":"serguei","es":"Comparamos la referencia, el acabado, el soporte y la luz con la muestra aprobada.","ru":"Сравним артикул, степень блеска, основание и свет с согласованной выкраской.","pronunciation":"компара́мос ла ррэфэрэ́нсиа, эл акаба́до, эл сопо́ртэ и ла лус кон ла муэ́стра апроба́да.","id":"d12-024"},{"speaker":"client","es":"Me gusta este blanco de la muestra, pero con la luz de la ventana lo veo un poco más cálido.","ru":"Нравится этот белый образца, но у окна он кажется чуть теплее.","pronunciation":"мэ гу́ста э́стэ бла́нко дэ ла муэ́стра, пэ́ро кон ла лус дэ ла бэнта́на ло бэ́о ун по́ко ма́с ка́лидо.","id":"d12-025"},{"speaker":"serguei","es":"La luz de la habitación cambia la percepción del color; hacemos una muestra en la propia pared.","ru":"Освещение комнаты меняет восприятие цвета; сделаем выкрас прямо на стене.","pronunciation":"ла лус дэ ла абитасио́н ка́мбиа ла пэрсэпсио́н дэл коло́р; асэ́мос у́на муэ́стра эн ла про́пиа парэ́д.","id":"d12-026"},{"speaker":"client","es":"¿Podemos comparar un acabado mate y otro con más brillo antes de comprar toda la pintura?","ru":"Можно сравнить матовый финиш с более блестящим до покупки всей краски?","pronunciation":"подэ́мос компара́р ун акаба́до ма́тэ и о́тро кон ма́с бри́йо а́нтэс дэ компра́р то́да ла пинту́ра?","id":"d12-027"},{"speaker":"serguei","es":"Sí, confirmamos la referencia, el acabado y la muestra aprobada para que la elección quede clara.","ru":"Да, подтвердим артикул, финиш и согласованный выкрас для однозначного выбора.","pronunciation":"си́, конфирма́мос ла ррэфэрэ́нсиа, эл акаба́до и ла муэ́стра апроба́да па́ра кэ ла элэксио́н кэ́дэ кла́ра.","id":"d12-028"},{"speaker":"client","es":"En esta esquina había humedad y no quiero que vuelva a aparecer después de terminar el enlucido.","ru":"В этом углу была сырость, не хочу её возвращения после штукатурной отделки.","pronunciation":"эн э́ста эски́на аби́а умэда́д и но киэ́ро кэ буэ́лба а апарэсэ́р дэспуэ́с дэ тэрмина́р эл энлуси́до.","id":"d12-029"},{"speaker":"serguei","es":"La causa y el estado de la zona se revisan antes de definir la preparación y la pintura.","ru":"Причину и состояние зоны проверяют до определения подготовки и краски.","pronunciation":"ла ка́уса и эл эста́до дэ ла со́на сэ ррэби́сан а́нтэс дэ дэфини́р ла прэпарасио́н и ла пинту́ра.","id":"d12-030"},{"speaker":"client","es":"Si al final queda una marca pequeña, ¿revisamos solo el retoque o toda la pared con la misma luz?","ru":"Если в конце будет небольшая отметина, проверяем только подкраску или всю стену при том же свете?","pronunciation":"си ал фина́л кэ́да у́на ма́рка пэкэ́ньа, ррэбиса́мос со́ло эл ррэто́кэ о то́да ла парэ́д кон ла ми́сма лус?","id":"d12-031"},{"speaker":"serguei","es":"Revisamos el paño con el acabado acordado y confirmamos si el retoque puede quedar uniforme.","ru":"Проверим плоскость по согласованному финишу и уточним, можно ли получить однородную подкраску.","pronunciation":"ррэбиса́мос эл па́ньо кон эл акаба́до акорда́до и конфирма́мос си эл ррэто́кэ пуэ́дэ кэда́р унифо́рмэ.","id":"d12-032"},{"speaker":"client","es":"Quiero hacer esa revisión antes de colocar los muebles y de retirar todas las protecciones del suelo.","ru":"Хочу провести проверку до установки мебели и снятия всей защиты пола.","pronunciation":"киэ́ро асэ́р э́са ррэбисио́н а́нтэс дэ колока́р лос муэ́блэс и дэ ррэтира́р то́дас лас протэксио́нэс дэл суэ́ло.","id":"d12-033"},{"speaker":"serguei","es":"Lo organizamos en el calendario y revisamos juntas, esquinas y remates antes de la entrega.","ru":"Включим это в график и проверим швы, углы и примыкания до сдачи.","pronunciation":"ло органиса́мос эн эл калэнда́рио и ррэбиса́мос ху́нтас, эски́нас и ррэма́тэс а́нтэс дэ ла энтрэ́га.","id":"d12-034"}],"words":485,"minutes":5},{"lesson":13,"title":"Двери, окна и кухня на заказ","setting":"Размеры, направления открывания, техника, столешница и мебель.","sentences":[{"speaker":"client","es":"Quiero revisar las puertas y los muebles de cocina antes de confirmar el pedido con el proveedor.","ru":"Хочу проверить двери и кухонную мебель до подтверждения заказа поставщику.","pronunciation":"киэ́ро ррэбиса́р лас пуэ́ртас и лос муэ́блэс дэ коси́на а́нтэс дэ конфирма́р эл пэди́до кон эл пробээдо́р.","id":"d13-001"},{"speaker":"serguei","es":"Necesitamos las medidas finales, los acabados y las referencias exactas de cada electrodoméstico antes de fabricar.","ru":"Нужны чистовые размеры, отделка и точные артикулы каждого прибора до изготовления.","pronunciation":"нэсэсита́мос лас мэди́дас фина́лэс, лос акаба́дос и лас ррэфэрэ́нсиас экса́ктас дэ ка́да элэктродомэ́стико а́нтэс дэ фабрика́р.","id":"d13-002"},{"speaker":"client","es":"La puerta del baño debe abrir hacia fuera porque dentro queda poco espacio junto al lavabo.","ru":"Дверь ванной должна открываться наружу, потому что внутри мало места возле раковины.","pronunciation":"ла пуэ́рта дэл ба́ньо дэ́бэ абри́р а́сиа фуэ́ра по́ркэ дэ́нтро кэ́да по́ко эспа́сио ху́нто ал лаба́бо.","id":"d13-003"},{"speaker":"serguei","es":"Confirmamos el sentido de apertura con un dibujo y revisamos el paso libre y el espacio del pasillo.","ru":"Подтвердим открывание схемой и проверим свободный проход и место в коридоре.","pronunciation":"конфирма́мос эл сэнти́до дэ апэрту́ра кон ун дибу́хо и ррэбиса́мос эл па́со ли́брэ и эл эспа́сио дэл паси́йо.","id":"d13-004"},{"speaker":"client","es":"En el dormitorio prefiero una puerta corredera, pero no sé si cabe el sistema dentro del tabique.","ru":"В спальне предпочитаю раздвижную дверь, но не знаю, помещается ли система внутри перегородки.","pronunciation":"эн эл дормито́рио прэфиэ́ро у́на пуэ́рта коррэдэ́ра, пэ́ро но сэ́ си ка́бэ эл систэ́ма дэ́нтро дэл таби́кэ.","id":"d13-005"},{"speaker":"serguei","es":"Revisamos el hueco de obra y el sistema elegido antes de confirmar la solución con el fabricante.","ru":"Проверим строительный проём и выбранную систему до подтверждения решения с изготовителем.","pronunciation":"ррэбиса́мос эл уэ́ко дэ о́бра и эл систэ́ма элэхи́до а́нтэс дэ конфирма́р ла солусио́н кон эл фабрика́нтэ.","id":"d13-006"},{"speaker":"client","es":"Las manillas y las bisagras quiero que tengan el mismo acabado que los tiradores de los armarios.","ru":"Хочу одинаковую отделку дверных ручек, петель и ручек шкафов.","pronunciation":"лас мани́йас и лас биса́грас киэ́ро кэ тэ́нган эл ми́смо акаба́до кэ лос тирадо́рэс дэ лос арма́риос.","id":"d13-007"},{"speaker":"serguei","es":"¿Podría confirmar las referencias y enviarnos la ficha de esos herrajes para coordinarlos en el pedido?","ru":"Можете подтвердить артикулы и отправить документы фурнитуры для согласования в заказе?","pronunciation":"подри́а конфирма́р лас ррэфэрэ́нсиас и энбиа́рнос ла фи́ча дэ э́сос эрра́хэс па́ра координа́рлос эн эл пэди́до?","id":"d13-008"},{"speaker":"client","es":"En la cocina necesito cajones grandes y un armario empotrado que aproveche el hueco junto a la entrada.","ru":"В кухне нужны большие ящики и встроенный шкаф в нише возле входа.","pronunciation":"эн ла коси́на нэсэси́то кахо́нэс гра́ндэс и ун арма́рио эмпотра́до кэ апробэ́чэ эл уэ́ко ху́нто а ла энтра́да.","id":"d13-009"},{"speaker":"serguei","es":"Medimos el hueco terminado y revisamos los frentes para que las puertas y los cajones puedan abrirse bien.","ru":"Измерим чистовую нишу и проверим фасады, чтобы дверцы и ящики нормально открывались.","pronunciation":"мэди́мос эл уэ́ко тэрмина́до и ррэбиса́мос лос фрэ́нтэс па́ра кэ лас пуэ́ртас и лос кахо́нэс пуэ́дан абри́рсэ биэн.","id":"d13-010"},{"speaker":"client","es":"El frigorífico es más ancho que el anterior y no quiero descubrir después que no cabe entre los muebles.","ru":"Холодильник шире прежнего, не хочу потом обнаружить, что он не помещается между шкафами.","pronunciation":"эл фригори́фико эс ма́с а́нчо кэ эл антэрио́р и но киэ́ро дэскубри́р дэспуэ́с кэ но ка́бэ э́нтрэ лос муэ́блэс.","id":"d13-011"},{"speaker":"serguei","es":"Por eso pedimos la referencia exacta y comprobamos las dimensiones y las condiciones de instalación del aparato.","ru":"Поэтому запрашиваем точный артикул и проверяем размеры и условия установки прибора.","pronunciation":"пор э́со пэди́мос ла ррэфэрэ́нсиа экса́кта и компроба́мос лас димэнсио́нэс и лас кондисио́нэс дэ инсталасио́н дэл апара́то.","id":"d13-012"},{"speaker":"client","es":"¿Se puede aprovechar la cocina antigua?","ru":"Можно сохранить старую кухню?","pronunciation":"сэ пуэ́дэ апробэча́р ла коси́на анти́гуа?","id":"d13-013"},{"speaker":"serguei","es":"Revisamos módulos, medidas, instalaciones y estado para definir qué se puede reutilizar.","ru":"Проверим модули, размеры, коммуникации и состояние, чтобы определить сохраняемое.","pronunciation":"ррэбиса́мос мо́дулос, мэди́дас, инсталасио́нэс и эста́до па́ра дэфини́р кэ́ сэ пуэ́дэ ррэутилиса́р.","id":"d13-014"},{"speaker":"client","es":"¿El frigorífico va a caber?","ru":"Холодильник поместится?","pronunciation":"эл фригори́фико ба а кабэ́р?","id":"d13-015"},{"speaker":"serguei","es":"Necesitamos su ficha, el espacio de instalación y las condiciones de apertura y ventilación.","ru":"Нужны техкарта, монтажное место и условия открывания и вентиляции.","pronunciation":"нэсэсита́мос су фи́ча, эл эспа́сио дэ инсталасио́н и лас кондисио́нэс дэ апэрту́ра и бэнтиласио́н.","id":"d13-016"},{"speaker":"client","es":"¿Por qué no podemos medir la encimera ya?","ru":"Почему нельзя уже замерить столешницу?","pronunciation":"пор кэ́ но подэ́мос мэди́р ла энсимэ́ра йа?","id":"d13-017"},{"speaker":"serguei","es":"Primero confirmamos los muebles y el proceso de medición con el fabricante.","ru":"Сначала подтвердим мебель и порядок замера с изготовителем.","pronunciation":"примэ́ро конфирма́мос лос муэ́блэс и эл просэ́со дэ мэдисио́н кон эл фабрика́нтэ.","id":"d13-018"},{"speaker":"client","es":"¿Puedo poner otra ventana de distinto color?","ru":"Можно окно другого цвета?","pronunciation":"пуэ́до понэ́р о́тра бэнта́на дэ дисти́нто коло́р?","id":"d13-019"},{"speaker":"serguei","es":"Antes de pedirla comprobamos las condiciones de fachada, comunidad y ayuntamiento.","ru":"До заказа проверим условия фасада, сообщества и муниципалитета.","pronunciation":"а́нтэс дэ пэди́рла компроба́мос лас кондисио́нэс дэ фача́да, комунида́д и айунтамиэ́нто.","id":"d13-020"},{"speaker":"client","es":"¿Las puertas van a rozar con el suelo nuevo?","ru":"Двери будут задевать новый пол?","pronunciation":"лас пуэ́ртас бан а рроса́р кон эл суэ́ло нуэ́бо?","id":"d13-021"},{"speaker":"serguei","es":"Lo comprobamos con la altura terminada y las medidas de las hojas.","ru":"Проверим по чистовой отметке и размерам полотен.","pronunciation":"ло компроба́мос кон ла алту́ра тэрмина́да и лас мэди́дас дэ лас о́хас.","id":"d13-022"},{"speaker":"client","es":"¿Podemos cerrar la terraza como en la foto?","ru":"Можно застеклить/закрыть террасу как на фото?","pronunciation":"подэ́мос сэрра́р ла тэрра́са ко́мо эн ла фо́то?","id":"d13-023"},{"speaker":"serguei","es":"La foto sirve de referencia; la viabilidad y el trámite se revisan para este inmueble.","ru":"Фото — ориентир; возможность и оформление проверяем для этого объекта.","pronunciation":"ла фо́то си́рбэ дэ ррэфэрэ́нсиа; ла биабилида́д и эл тра́митэ сэ ррэби́сан па́ра э́стэ инмуэ́блэ.","id":"d13-024"},{"speaker":"client","es":"También quiero una campana extractora integrada y un fregadero bajo la encimera si el material lo permite.","ru":"Ещё хочу встроенную вытяжку и мойку под столешницей, если материал допускает.","pronunciation":"тамбиэ́н киэ́ро у́на кампа́на экстракто́ра интэгра́да и ун фрэгадэ́ро ба́хо ла энсимэ́ра си эл матэриа́л ло пэрми́тэ.","id":"d13-025"},{"speaker":"serguei","es":"Confirmamos el material, el montaje previsto y las fichas de los equipos con el proveedor de la encimera.","ru":"Уточним материал, предусмотренный монтаж и документы оборудования с поставщиком столешницы.","pronunciation":"конфирма́мос эл матэриа́л, эл монта́хэ прэби́сто и лас фи́час дэ лос эки́пос кон эл пробээдо́р дэ ла энсимэ́ра.","id":"d13-026"},{"speaker":"client","es":"¿Cuándo se hace la plantilla de la encimera para que los huecos coincidan con el fregadero y la placa?","ru":"Когда делают шаблон столешницы, чтобы отверстия совпали с мойкой и варочной панелью?","pronunciation":"куа́ндо сэ а́сэ ла планти́йа дэ ла энсимэ́ра па́ра кэ лос уэ́кос коинси́дан кон эл фрэгадэ́ро и ла пла́ка?","id":"d13-027"},{"speaker":"serguei","es":"La medición se coordina cuando los muebles están colocados, según el proceso acordado con el proveedor.","ru":"Замер согласуем после установки мебели по процедуре, принятой с поставщиком.","pronunciation":"ла мэдисио́н сэ коорди́на куа́ндо лос муэ́блэс эста́н колока́дос, сэгу́н эл просэ́со акорда́до кон эл пробээдо́р.","id":"d13-028"},{"speaker":"client","es":"La ventana del salón también quiero cambiarla, pero la persiana y el aspecto de la fachada me preocupan.","ru":"Окно гостиной тоже хочу поменять, но меня беспокоят роллета и вид фасада.","pronunciation":"ла бэнта́на дэл сало́н тамбиэ́н киэ́ро камбиа́рла, пэ́ро ла пэрсиа́на и эл аспэ́кто дэ ла фача́да мэ прэоку́пан.","id":"d13-029"},{"speaker":"serguei","es":"Consultamos las condiciones de ese cambio antes de encargar la carpintería y confirmamos el encuentro con los acabados.","ru":"Проверим условия замены до заказа оконных изделий и согласуем примыкания к отделке.","pronunciation":"консулта́мос лас кондисио́нэс дэ э́сэ ка́мбио а́нтэс дэ энкарга́р ла карпинтэри́а и конфирма́мос эл энкуэ́нтро кон лос акаба́дос.","id":"d13-030"},{"speaker":"client","es":"En la puerta de entrada necesito una cerradura nueva y que la hoja cierre sin rozar el suelo.","ru":"Во входной двери нужен новый замок, и полотно должно закрываться, не задевая пол.","pronunciation":"эн ла пуэ́рта дэ энтра́да нэсэси́то у́на сэрраду́ра нуэ́ба и кэ ла о́ха сиэ́ррэ син рроса́р эл суэ́ло.","id":"d13-031"},{"speaker":"serguei","es":"Revisamos el marco, ajustamos los elementos previstos y comprobamos la apertura y el cierre al terminar.","ru":"Проверим коробку, отрегулируем предусмотренные элементы и в конце проверим открывание и закрывание.","pronunciation":"ррэбиса́мос эл ма́рко, ахуста́мос лос элэмэ́нтос прэби́стос и компроба́мос ла апэрту́ра и эл сиэ́ррэ ал тэрмина́р.","id":"d13-032"},{"speaker":"client","es":"Antes de aceptar el pedido quiero ver una lista con medidas, colores, tiradores y sentidos de apertura.","ru":"До подтверждения заказа хочу перечень размеров, цветов, ручек и направлений открывания.","pronunciation":"а́нтэс дэ асэпта́р эл пэди́до киэ́ро бэр у́на ли́ста кон мэди́дас, коло́рэс, тирадо́рэс и сэнти́дос дэ апэрту́ра.","id":"d13-033"},{"speaker":"serguei","es":"Se lo enviamos para su aprobación y no confirmamos la fabricación hasta resolver las medidas pendientes.","ru":"Отправим на согласование и не подтвердим изготовление до уточнения оставшихся размеров.","pronunciation":"сэ ло энбиа́мос па́ра су апробасио́н и но конфирма́мос ла фабрикасио́н а́ста ррэсолбэ́р лас мэди́дас пэндиэ́нтэс.","id":"d13-034"}],"words":498,"minutes":5},{"lesson":14,"title":"Отчёт о работах и приёмка","setting":"Проверяем сделанное, обсуждаем изменение, замечания, документы и остаток оплаты.","sentences":[{"speaker":"serguei","es":"Buenos días, hoy hemos terminado el alicatado y hemos colocado los muebles que ya estaban disponibles.","ru":"Добрый день, сегодня закончили облицовку плиткой и установили доступную мебель.","pronunciation":"буэ́нос ди́ас, ои э́мос тэрмина́до эл аликата́до и э́мос колока́до лос муэ́блэс кэ йа эста́бан диспони́блэс.","id":"d14-001"},{"speaker":"client","es":"He visto las fotos del avance, pero quiero saber qué falta antes de poder usar todo el baño.","ru":"Видел фотографии хода работ, хочу знать, что осталось до полного использования ванной.","pronunciation":"э би́сто лас фо́тос дэл аба́нсэ, пэ́ро киэ́ро сабэ́р кэ́ фа́лта а́нтэс дэ подэ́р уса́р то́до эл ба́ньо.","id":"d14-002"},{"speaker":"serguei","es":"Todavía no hemos recibido la mampara y nos falta colocar unos remates que dependen de esa entrega.","ru":"Душевое ограждение ещё не получили; осталось сделать примыкания, зависящие от поставки.","pronunciation":"тодаби́а но э́мос ррэсиби́до ла мампа́ра и нос фа́лта колока́р у́нос ррэма́тэс кэ дэпэ́ндэн дэ э́са энтрэ́га.","id":"d14-003"},{"speaker":"client","es":"¿El proveedor ha confirmado la fecha o el plazo sigue pendiente de una respuesta sobre el pedido?","ru":"Поставщик подтвердил дату или срок всё ещё зависит от ответа по заказу?","pronunciation":"эл пробээдо́р а конфирма́до ла фэ́ча о эл пла́со си́гэ пэндиэ́нтэ дэ у́на ррэспуэ́ста со́брэ эл пэди́до?","id":"d14-004"},{"speaker":"serguei","es":"Estamos esperando la confirmación y le envío la actualización cuando tengamos una fecha comprobada.","ru":"Ждём подтверждения; отправлю обновление, когда будет проверенная дата.","pronunciation":"эста́мос эспэра́ндо ла конфирмасио́н и лэ энби́о ла актуалисасио́н куа́ндо тэнга́мос у́на фэ́ча компроба́да.","id":"d14-005"},{"speaker":"client","es":"También he visto una conexión que no aparece en el plano inicial y quiero entender qué ha pasado.","ru":"Ещё увидел соединение, которого нет в исходном плане, хочу понять, что произошло.","pronunciation":"тамбиэ́н э би́сто у́на конэксио́н кэ но апарэ́сэ эн эл пла́но инисиа́л и киэ́ро энтэндэ́р кэ́ а паса́до.","id":"d14-006"},{"speaker":"serguei","es":"Hemos detectado una instalación no prevista y hemos fotografiado la zona para revisar la solución.","ru":"Обнаружили непредусмотренную коммуникацию и сфотографировали зону для проверки решения.","pronunciation":"э́мос дэтэкта́до у́на инсталасио́н но прэби́ста и э́мос фотографиа́до ла со́на па́ра ррэбиса́р ла солусио́н.","id":"d14-007"},{"speaker":"client","es":"Antes de continuar necesito saber si ese cambio afecta al precio y al plazo de entrega.","ru":"До продолжения нужно знать, влияет ли изменение на цену и срок сдачи.","pronunciation":"а́нтэс дэ континуа́р нэсэси́то сабэ́р си э́сэ ка́мбио афэ́кта ал прэ́сио и ал пла́со дэ энтрэ́га.","id":"d14-008"},{"speaker":"serguei","es":"Le envío la valoración y las consecuencias del cambio antes de ejecutarlo para que pueda decidir.","ru":"Отправлю оценку и последствия изменения до выполнения, чтобы вы могли принять решение.","pronunciation":"лэ энби́о ла балорасио́н и лас консэкуэ́нсиас дэл ка́мбио а́нтэс дэ эхэкута́рло па́ра кэ пуэ́да дэсиди́р.","id":"d14-009"},{"speaker":"client","es":"Prefiero dejar la aprobación por escrito y tener una versión actualizada del listado de trabajos.","ru":"Предпочитаю письменное согласование и обновлённый список работ.","pronunciation":"прэфиэ́ро дэха́р ла апробасио́н пор эскри́то и тэнэ́р у́на бэрсио́н актуалиса́да дэл листа́до дэ траба́хос.","id":"d14-010"},{"speaker":"serguei","es":"Sí, registramos la decisión y actualizamos los pendientes para que el equipo trabaje con la misma información.","ru":"Да, зафиксируем решение и обновим остатки работ, чтобы команда имела одинаковую информацию.","pronunciation":"си́, ррэхистра́мос ла дэсисио́н и актуалиса́мос лос пэндиэ́нтэс па́ра кэ эл эки́по траба́хэ кон ла ми́сма информасио́н.","id":"d14-011"},{"speaker":"client","es":"En esta esquina veo una marca que no me convence y quiero revisarla durante la visita de hoy.","ru":"В этом углу вижу отметину, которая мне не нравится, хочу проверить её сегодня.","pronunciation":"эн э́ста эски́на бэ́о у́на ма́рка кэ но мэ конбэ́нсэ и киэ́ро ррэбиса́рла дура́нтэ ла биси́та дэ ои.","id":"d14-012"},{"speaker":"client","es":"¿Por qué se retrasa la obra?","ru":"Почему ремонт задерживается?","pronunciation":"пор кэ́ сэ ррэтра́са ла о́бра?","id":"d14-013"},{"speaker":"serguei","es":"El material no ha llegado en la fecha prevista.","ru":"Материал не пришёл в срок.","pronunciation":"эл матэриа́л но а йэга́до эн ла фэ́ча прэби́ста.","id":"d14-014"},{"speaker":"serguei","es":"Le envío qué tareas afecta y el calendario revisado.","ru":"Отправлю затронутые работы и обновлённый график.","pronunciation":"лэ энби́о кэ́ тарэ́ас афэ́кта и эл калэнда́рио ррэбиса́до.","id":"d14-015"},{"speaker":"client","es":"¿Por qué tengo que pagar este extra?","ru":"Почему нужно платить за допработу?","pronunciation":"пор кэ́ тэ́нго кэ пага́р э́стэ э́кстра?","id":"d14-016"},{"speaker":"serguei","es":"Revisamos si estaba incluida.","ru":"Проверим включение.","pronunciation":"ррэбиса́мос си эста́ба инклуи́да.","id":"d14-017"},{"speaker":"serguei","es":"Si es un cambio de alcance, enviamos la valoración y pedimos aprobación previa.","ru":"Если меняется состав работ, заранее отправим оценку и запросим согласование.","pronunciation":"си эс ун ка́мбио дэ алка́нсэ, энбиа́мос ла балорасио́н и пэди́мос апробасио́н прэ́биа.","id":"d14-018"},{"speaker":"client","es":"¿Esto está bien acabado?","ru":"Это нормально закончено?","pronunciation":"э́сто эста́ биэн акаба́до?","id":"d14-019"},{"speaker":"serguei","es":"Lo comparamos con el detalle y la muestra aprobados, y anotamos lo que debe corregirse.","ru":"Сравним с узлом и образцом и запишем, что исправить.","pronunciation":"ло компара́мос кон эл дэта́йэ и ла муэ́стра апроба́дос, и анота́мос ло кэ дэ́бэ коррэхи́рсэ.","id":"d14-020"},{"speaker":"client","es":"¿Cuándo vienen a terminar los repasos?","ru":"Когда придёте завершить исправления?","pronunciation":"куа́ндо биэ́нэн а тэрмина́р лос ррэпа́сос?","id":"d14-021"},{"speaker":"serguei","es":"Le confirmo la fecha y el listado de trabajos pendientes.","ru":"Подтвержу дату и список остатков.","pronunciation":"лэ конфи́рмо ла фэ́ча и эл листа́до дэ траба́хос пэндиэ́нтэс.","id":"d14-022"},{"speaker":"client","es":"¿Qué garantía tiene el trabajo?","ru":"Какая гарантия на работу?","pronunciation":"кэ́ гаранти́а тиэ́нэ эл траба́хо?","id":"d14-023"},{"speaker":"serguei","es":"Le entregamos las condiciones y los documentos aplicables a cada trabajo y equipo, sin sustituir los derechos legales.","ru":"Передадим условия и документы для работ и оборудования с сохранением законных прав.","pronunciation":"лэ энтрэга́мос лас кондисио́нэс и лос докумэ́нтос аплика́блэс а ка́да траба́хо и эки́по, син суституи́р лос дэрэ́чос лэга́лэс.","id":"d14-024"},{"speaker":"client","es":"¿Qué queda por pagar y qué falta entregar?","ru":"Сколько осталось оплатить и что осталось передать?","pronunciation":"кэ́ кэ́да пор пага́р и кэ́ фа́лта энтрэга́р?","id":"d14-025"},{"speaker":"serguei","es":"Revisamos el contrato, las partidas ejecutadas, los pendientes y el saldo documentado.","ru":"Проверим договор, выполненные позиции, остатки и документально подтверждённый баланс.","pronunciation":"ррэбиса́мос эл контра́то, лас парти́дас эхэкута́дас, лос пэндиэ́нтэс и эл са́лдо докумэнта́до.","id":"d14-026"},{"speaker":"serguei","es":"¿Puede señalar exactamente el punto que le preocupa para compararlo con la muestra y el acabado aprobados?","ru":"Покажете точное место, которое беспокоит, для сравнения с образцом и согласованным финишем?","pronunciation":"пуэ́дэ сэньала́р эксактамэ́нтэ эл пу́нто кэ лэ прэоку́па па́ра компара́рло кон ла муэ́стра и эл акаба́до апроба́дос?","id":"d14-027"},{"speaker":"client","es":"Es aquí, junto al perfil, porque con esta luz se nota una diferencia respecto a la zona de al lado.","ru":"Здесь, возле профиля: при таком свете видна разница с соседним участком.","pronunciation":"эс аки́, ху́нто ал пэрфи́л, по́ркэ кон э́ста лус сэ но́та у́на дифэрэ́нсиа ррэспэ́кто а ла со́на дэ ал ла́до.","id":"d14-028"},{"speaker":"serguei","es":"Gracias por indicarlo, lo revisamos y confirmamos la solución antes de dar ese punto por terminado.","ru":"Спасибо, что указали; проверим и подтвердим решение до закрытия этого пункта.","pronunciation":"гра́сиас пор индика́рло, ло ррэбиса́мос и конфирма́мос ла солусио́н а́нтэс дэ дар э́сэ пу́нто пор тэрмина́до.","id":"d14-029"},{"speaker":"client","es":"En la revisión conjunta quiero comprobar también las puertas, los grifos, la iluminación y el desagüe de la ducha.","ru":"При совместном осмотре хочу проверить двери, краны, освещение и душевой слив.","pronunciation":"эн ла ррэбисио́н конху́нта киэ́ро компроба́р тамбиэ́н лас пуэ́ртас, лос гри́фос, ла илуминасио́н и эл дэса́гуэ дэ ла ду́ча.","id":"d14-030"},{"speaker":"serguei","es":"Preparamos una lista y anotamos los repasos y las fechas acordadas para los puntos que queden pendientes.","ru":"Подготовим перечень и запишем доводки и согласованные сроки по оставшимся пунктам.","pronunciation":"прэпара́мос у́на ли́ста и анота́мос лос ррэпа́сос и лас фэ́час акорда́дас па́ра лос пу́нтос кэ кэ́дэн пэндиэ́нтэс.","id":"d14-031"},{"speaker":"client","es":"¿La documentación final y los manuales se entregan junto con el acta de entrega de la reforma?","ru":"Итоговые документы и инструкции передают вместе с актом сдачи ремонта?","pronunciation":"ла докумэнтасио́н фина́л и лос мануа́лэс сэ энтрэ́ган ху́нто кон эл а́кта дэ энтрэ́га дэ ла ррэфо́рма?","id":"d14-032"},{"speaker":"serguei","es":"Organizamos la documentación que corresponda al alcance contratado y explicamos las indicaciones de mantenimiento.","ru":"Подготовим документы по согласованному составу работ и объясним рекомендации по уходу.","pronunciation":"органиса́мос ла докумэнтасио́н кэ коррэспо́нда ал алка́нсэ контрата́до и эксплика́мос лас индикасио́нэс дэ мантэнимиэ́нто.","id":"d14-033"},{"speaker":"client","es":"También quiero revisar el saldo y comprobar que todos los pagos realizados figuran en el resumen.","ru":"Ещё хочу проверить остаток и убедиться, что все платежи отражены в сводке.","pronunciation":"тамбиэ́н киэ́ро ррэбиса́р эл са́лдо и компроба́р кэ то́дос лос па́гос ррэалиса́дос фигу́ран эн эл ррэсу́мэн.","id":"d14-034"},{"speaker":"serguei","es":"Le entrego el resumen con los importes, los justificantes y los pendientes según lo acordado en el contrato.","ru":"Передам сводку с суммами, подтверждениями и оставшимися вопросами по договору.","pronunciation":"лэ энтрэ́го эл ррэсу́мэн кон лос импо́ртэс, лос хустифика́нтэс и лос пэндиэ́нтэс сэгу́н ло акорда́до эн эл контра́то.","id":"d14-035"},{"speaker":"client","es":"Así podemos cerrar la entrega con una lista clara de lo terminado y de lo que falta resolver.","ru":"Так сможем провести сдачу с понятным списком завершённого и оставшихся вопросов.","pronunciation":"аси́ подэ́мос сэрра́р ла энтрэ́га кон у́на ли́ста кла́ра дэ ло тэрмина́до и дэ ло кэ фа́лта ррэсолбэ́р.","id":"d14-036"}],"words":495,"minutes":5},{"lesson":15,"title":"Как уточнить разрешения и документы","setting":"Разговор с заказчиком о конкретном составе работ, статусе оформления и необходимых уточнениях.","sentences":[{"speaker":"client","es":"Antes de empezar quiero saber qué documentación necesitamos para la reforma de este piso en Barcelona.","ru":"До начала хочу знать, какие документы нужны для ремонта этой квартиры в Барселоне.","pronunciation":"а́нтэс дэ эмпэса́р киэ́ро сабэ́р кэ́ докумэнтасио́н нэсэсита́мос па́ра ла ррэфо́рма дэ э́стэ пи́со эн барсэло́на.","id":"d15-001"},{"speaker":"serguei","es":"Primero definimos la actuación concreta y confirmamos el trámite que corresponde a esta dirección y a su alcance.","ru":"Сначала определим конкретные работы и уточним процедуру для этого адреса и состава.","pronunciation":"примэ́ро дэфини́мос ла актуасио́н конкрэ́та и конфирма́мос эл тра́митэ кэ коррэспо́ндэ а э́ста дирэксио́н и а су алка́нсэ.","id":"d15-002"},{"speaker":"client","es":"Queremos cambiar la distribución interior, renovar las instalaciones y estudiar un cambio en las ventanas.","ru":"Хотим изменить внутреннюю планировку, обновить коммуникации и рассмотреть замену окон.","pronunciation":"кэрэ́мос камбиа́р ла дистрибусио́н интэрио́р, ррэноба́р лас инсталасио́нэс и эстудиа́р ун ка́мбио эн лас бэнта́нас.","id":"d15-003"},{"speaker":"serguei","es":"Necesitamos indicar si los trabajos afectan a estructura, fachada o elementos protegidos antes de consultar el procedimiento.","ru":"До уточнения процедуры нужно указать влияние на конструкции, фасад и охраняемые элементы.","pronunciation":"нэсэсита́мос индика́р си лос траба́хос афэ́ктан а эструкту́ра, фача́да о элэмэ́нтос протэхи́дос а́нтэс дэ консулта́р эл просэдимиэ́нто.","id":"d15-004"},{"speaker":"client","es":"Tengo un diseño en tres dimensiones y varios planos, pero no sé si son suficientes para presentar la solicitud.","ru":"У меня трёхмерный дизайн и чертежи, но не знаю, достаточно ли их для подачи заявления.","pronunciation":"тэ́нго ун дисэ́ньо эн трэс димэнсио́нэс и ба́риос пла́нос, пэ́ро но сэ́ си сон суфисиэ́нтэс па́ра прэсэнта́р ла солиситу́д.","id":"d15-005"},{"speaker":"serguei","es":"Revisamos la documentación disponible con el técnico y confirmamos qué falta aportar para la actuación prevista.","ru":"Проверим имеющиеся документы со специалистом и уточним недостающие для планируемых работ.","pronunciation":"ррэбиса́мос ла докумэнтасио́н диспони́блэ кон эл тэ́книко и конфирма́мос кэ́ фа́лта апорта́р па́ра ла актуасио́н прэби́ста.","id":"d15-006"},{"speaker":"client","es":"Me gustaría que una sola persona coordinara las consultas para no recibir respuestas diferentes de cada profesional.","ru":"Хочу одного координатора запросов, чтобы не получать разные ответы от каждого специалиста.","pronunciation":"мэ густари́а кэ у́на со́ла пэрсо́на координа́ра лас консу́лтас па́ра но ррэсиби́р ррэспуэ́стас дифэрэ́нтэс дэ ка́да профэсиона́л.","id":"d15-007"},{"speaker":"serguei","es":"Definimos quién es el titular, quién actúa como representante y qué técnico debe intervenir en el expediente.","ru":"Определим заявителя, представителя и специалиста, который должен участвовать в оформлении.","pronunciation":"дэфини́мос киэ́н эс эл титула́р, киэ́н акту́а ко́мо ррэпрэсэнта́нтэ и кэ́ тэ́книко дэ́бэ интэрбэни́р эн эл экспэдиэ́нтэ.","id":"d15-008"},{"speaker":"client","es":"¿La comunicación previa, la declaración responsable y la licencia de obras son nombres de lo mismo?","ru":"Предварительное уведомление, декларация ответственного лица и лицензия на работы — названия одного и того же?","pronunciation":"ла комуникасио́н прэ́биа, ла дэкларасио́н ррэспонса́блэ и ла лисэ́нсиа дэ о́брас сон но́мбрэс дэ ло ми́смо?","id":"d15-009"},{"speaker":"serguei","es":"No debemos tratarlos como equivalentes; preguntamos qué régimen corresponde y cuáles son sus condiciones concretas.","ru":"Их нельзя считать равнозначными; уточняем применимый режим и конкретные условия.","pronunciation":"но дэбэ́мос трата́рлос ко́мо экибалэ́нтэс; прэгунта́мос кэ́ ррэ́химэн коррэспо́ндэ и куа́лэс сон сус кондисио́нэс конкрэ́тас.","id":"d15-010"},{"speaker":"client","es":"También quiero distinguir las tasas, los impuestos y los honorarios de quienes preparan la documentación.","ru":"Ещё хочу разделить сборы, налоги и оплату подготовки документов специалистами.","pronunciation":"тамбиэ́н киэ́ро дистинги́р лас та́сас, лос импуэ́стос и лос онора́риос дэ киэ́нэс прэпа́ран ла докумэнтасио́н.","id":"d15-011"},{"speaker":"serguei","es":"Los conceptos se confirman para el expediente concreto y se separan de la mano de obra del presupuesto.","ru":"Эти позиции уточняют для конкретного дела и отделяют от стоимости ремонтных работ.","pronunciation":"лос консэ́птос сэ конфи́рман па́ра эл экспэдиэ́нтэ конкрэ́то и сэ сэпа́ран дэ ла ма́но дэ о́бра дэл прэсупуэ́сто.","id":"d15-012"},{"speaker":"client","es":"¿Para cambiar el baño hace falta permiso?","ru":"Для ремонта ванной нужно разрешение?","pronunciation":"па́ра камбиа́р эл ба́ньо а́сэ фа́лта пэрми́со?","id":"d15-013"},{"speaker":"serguei","es":"Consultamos la actuación concreta, la dirección y sus condiciones en el ayuntamiento; el nombre «reforma de baño» no basta para elegir el trámite.","ru":"Проверяем конкретные работы, адрес и условия в муниципалитете; названия «ремонт ванной» недостаточно для выбора процедуры.","pronunciation":"консулта́мос ла актуасио́н конкрэ́та, ла дирэксио́н и сус кондисио́нэс эн эл айунтамиэ́нто; эл но́мбрэ «ррэфо́рма дэ ба́ньо» но ба́ста па́ра элэхи́р эл тра́митэ.","id":"d15-014"},{"speaker":"client","es":"¿Quién tramita la documentación?","ru":"Кто оформляет документы?","pronunciation":"киэ́н трами́та ла докумэнтасио́н?","id":"d15-015"},{"speaker":"serguei","es":"Definimos el titular, el representante y el técnico que debe intervenir, y lo incluimos en el alcance contratado.","ru":"Определим заявителя, представителя и нужного специалиста и включим в договорённый состав.","pronunciation":"дэфини́мос эл титула́р, эл ррэпрэсэнта́нтэ и эл тэ́книко кэ дэ́бэ интэрбэни́р, и ло инклуи́мос эн эл алка́нсэ контрата́до.","id":"d15-016"},{"speaker":"client","es":"¿La comunidad ya ha dicho que sí; podemos empezar?","ru":"Сообщество согласилось, можно начинать?","pronunciation":"ла комунида́д йа а ди́чо кэ си́; подэ́мос эмпэса́р?","id":"d15-017"},{"speaker":"serguei","es":"Comprobamos también el trámite municipal y las demás condiciones aplicables.","ru":"Проверим также муниципальное оформление и остальные применимые условия.","pronunciation":"компроба́мос тамбиэ́н эл тра́митэ мунисипа́л и лас дэма́с кондисио́нэс аплика́блэс.","id":"d15-018"},{"speaker":"client","es":"¿El diseño 3D sirve como proyecto?","ru":"3D-дизайн подходит вместо проекта?","pronunciation":"эл дисэ́ньо трэс дэ си́рбэ ко́мо пройэ́кто?","id":"d15-019"},{"speaker":"serguei","es":"La visualización no acredita por sí sola que esté preparada toda la documentación técnica exigida.","ru":"Сама визуализация не подтверждает наличие всего требуемого технического комплекта.","pronunciation":"ла бисуалисасио́н но акрэди́та пор си́ со́ла кэ эстэ́ прэпара́да то́да ла докумэнтасио́н тэ́кника эксихи́да.","id":"d15-020"},{"speaker":"client","es":"¿Puede firmarlo usted como ingeniero?","ru":"Вы можете подписать как инженер?","pronunciation":"пуэ́дэ фирма́рло устэ́д ко́мо инхэниэ́ро?","id":"d15-021"},{"speaker":"serguei","es":"Hay que comprobar el tipo de documento y las atribuciones y habilitación exigidas para esta actuación.","ru":"Нужно проверить тип документа и требуемые для этих работ профессиональные полномочия и допуски.","pronunciation":"аи кэ компроба́р эл ти́по дэ докумэ́нто и лас атрибусио́нэс и абилитасио́н эксихи́дас па́ра э́ста актуасио́н.","id":"d15-022"},{"speaker":"client","es":"¿Podemos poner un contenedor en la calle?","ru":"Можно поставить контейнер на улице?","pronunciation":"подэ́мос понэ́р ун контэнэдо́р эн ла ка́йэ?","id":"d15-023"},{"speaker":"serguei","es":"Antes comprobamos la autorización de ocupación, la ubicación y las condiciones que correspondan.","ru":"Сначала проверим оформление занятия улицы, место и применимые условия.","pronunciation":"а́нтэс компроба́мос ла ауторисасио́н дэ окупасио́н, ла убикасио́н и лас кондисио́нэс кэ коррэспо́ндан.","id":"d15-024"},{"speaker":"client","es":"Si recibimos un requerimiento del ayuntamiento, quiero saber exactamente qué documento o corrección falta.","ru":"Если придёт запрос муниципалитета, хочу точно знать недостающий документ или исправление.","pronunciation":"си ррэсиби́мос ун ррэкэримиэ́нто дэл айунтамиэ́нто, киэ́ро сабэ́р эксактамэ́нтэ кэ́ докумэ́нто о коррэксио́н фа́лта.","id":"d15-025"},{"speaker":"serguei","es":"Le comunicamos el estado del expediente y coordinamos la respuesta con la persona responsable de prepararla.","ru":"Сообщим статус дела и согласуем ответ с ответственным за его подготовку.","pronunciation":"лэ комуника́мос эл эста́до дэл экспэдиэ́нтэ и координа́мос ла ррэспуэ́ста кон ла пэрсо́на ррэспонса́блэ дэ прэпара́рла.","id":"d15-026"},{"speaker":"client","es":"¿Podemos consultar el estado en la sede electrónica y guardar una copia de lo que se ha presentado?","ru":"Можем проверить статус на электронном портале и сохранить копию поданных документов?","pronunciation":"подэ́мос консулта́р эл эста́до эн ла сэ́дэ элэктро́ника и гуарда́р у́на ко́пиа дэ ло кэ сэ а прэсэнта́до?","id":"d15-027"},{"speaker":"serguei","es":"Organizamos las referencias y los justificantes disponibles para distinguir lo presentado de lo pendiente de revisión.","ru":"Систематизируем реквизиты и подтверждения, разделив поданное и ожидающее проверки.","pronunciation":"органиса́мос лас ррэфэрэ́нсиас и лос хустифика́нтэс диспони́блэс па́ра дистинги́р ло прэсэнта́до дэ ло пэндиэ́нтэ дэ ррэбисио́н.","id":"d15-028"},{"speaker":"client","es":"Quiero que también quede claro quién firma cada documento y quién asume la dirección facultativa si corresponde.","ru":"Хочу понимать, кто подписывает каждый документ и кто выполняет технический надзор, если он требуется.","pronunciation":"киэ́ро кэ тамбиэ́н кэ́дэ кла́ро киэ́н фи́рма ка́да докумэ́нто и киэ́н асу́мэ ла дирэксио́н факултати́ба си коррэспо́ндэ.","id":"d15-029"},{"speaker":"serguei","es":"Lo confirmamos con el técnico competente según el alcance y las atribuciones exigidas para ese trabajo.","ru":"Уточним с компетентным специалистом по составу работ и требуемым профессиональным полномочиям.","pronunciation":"ло конфирма́мос кон эл тэ́книко компэтэ́нтэ сэгу́н эл алка́нсэ и лас атрибусио́нэс эксихи́дас па́ра э́сэ траба́хо.","id":"d15-030"},{"speaker":"client","es":"Entonces no fijamos todavía una fecha definitiva de inicio solo porque ya hemos enviado algunos documentos.","ru":"Значит, пока не назначаем окончательное начало только потому, что отправили часть документов.","pronunciation":"энто́нсэс но фиха́мос тодаби́а у́на фэ́ча дэфинити́ба дэ ини́сио со́ло по́ркэ йа э́мос энбиа́до алгу́нос докумэ́нтос.","id":"d15-031"},{"speaker":"serguei","es":"Exactamente, primero comprobamos las condiciones de inicio aplicables y después coordinamos el calendario de obra.","ru":"Именно, сначала проверим применимые условия начала, затем согласуем график работ.","pronunciation":"эксактамэ́нтэ, примэ́ро компроба́мос лас кондисио́нэс дэ ини́сио аплика́блэс и дэспуэ́с координа́мос эл калэнда́рио дэ о́бра.","id":"d15-032"},{"speaker":"client","es":"Prefiero recibir un resumen con lo confirmado, lo pendiente y la persona encargada de cada siguiente paso.","ru":"Предпочитаю сводку подтверждённого, нерешённого и ответственных за следующие шаги.","pronunciation":"прэфиэ́ро ррэсиби́р ун ррэсу́мэн кон ло конфирма́до, ло пэндиэ́нтэ и ла пэрсо́на энкарга́да дэ ка́да сигиэ́нтэ па́со.","id":"d15-033"},{"speaker":"serguei","es":"Le envío ese resumen y actualizamos el estado cuando tengamos nuevas confirmaciones del expediente.","ru":"Отправлю сводку и обновим статус после получения новых подтверждений по делу.","pronunciation":"лэ энби́о э́сэ ррэсу́мэн и актуалиса́мос эл эста́до куа́ндо тэнга́мос нуэ́бас конфирмасио́нэс дэл экспэдиэ́нтэ.","id":"d15-034"}],"words":491,"minutes":5},{"lesson":16,"title":"От первого обращения до сдачи квартиры","setting":"Итоговый разговор: приоритеты, проект, работы, согласование изменений и результат.","sentences":[{"speaker":"client","es":"Hola, he visto su portfolio y busco a alguien que coordine la reforma de mi piso en Barcelona.","ru":"Здравствуйте, видел ваше портфолио и ищу координатора ремонта своей квартиры в Барселоне.","pronunciation":"о́ла, э би́сто су портфо́лио и бу́ско а а́лгиэн кэ коорди́нэ ла ррэфо́рма дэ ми пи́со эн барсэло́на.","id":"d16-001"},{"speaker":"serguei","es":"Soy Serguéi, de INKCRAFT, y coordino la ejecución de reformas en colaboración con diseñadores y arquitectos.","ru":"Я Сергей из INKCRAFT, координирую выполнение ремонта в сотрудничестве с дизайнерами и архитекторами.","pronunciation":"сои сэргэ́й, дэ и́нккрафт, и коорди́но ла эхэкусио́н дэ ррэфо́рмас эн колаборасио́н кон дисэньадо́рэс и аркитэ́ктос.","id":"d16-002"},{"speaker":"client","es":"Nuestra prioridad es el baño, pero también queremos renovar la cocina, pintar y cambiar el suelo del salón.","ru":"Наш приоритет — ванная, но ещё хотим обновить кухню, покрасить и поменять пол гостиной.","pronunciation":"нуэ́стра приорида́д эс эл ба́ньо, пэ́ро тамбиэ́н кэрэ́мос ррэноба́р ла коси́на, пинта́р и камбиа́р эл суэ́ло дэл сало́н.","id":"d16-003"},{"speaker":"serguei","es":"Primero hacemos una visita para comprobar el estado, tomar medidas y confirmar qué elementos quiere mantener.","ru":"Сначала проведём осмотр, проверим состояние, сделаем замеры и уточним сохраняемые элементы.","pronunciation":"примэ́ро асэ́мос у́на биси́та па́ра компроба́р эл эста́до, тома́р мэди́дас и конфирма́р кэ́ элэмэ́нтос киэ́рэ мантэнэ́р.","id":"d16-004"},{"speaker":"client","es":"Tenemos un proyecto de interiorismo, aunque faltan algunas referencias de materiales y el plano eléctrico definitivo.","ru":"Есть дизайн-проект, но не хватает части артикулов материалов и окончательного электроплана.","pronunciation":"тэнэ́мос ун пройэ́кто дэ интэриори́смо, а́ункэ фа́лтан алгу́нас ррэфэрэ́нсиас дэ матэриа́лэс и эл пла́но элэ́ктрико дэфинити́бо.","id":"d16-005"},{"speaker":"serguei","es":"Anotamos esos pendientes y coordinamos el replanteo antes de cerrar el alcance y pedir los equipos.","ru":"Зафиксируем эти вопросы и согласуем разметку до окончательного определения состава работ и заказа оборудования.","pronunciation":"анота́мос э́сос пэндиэ́нтэс и координа́мос эл ррэплантэ́о а́нтэс дэ сэрра́р эл алка́нсэ и пэди́р лос эки́пос.","id":"d16-006"},{"speaker":"client","es":"Quiero entender qué está incluido en su propuesta y qué tengo que contratar o comprar por separado.","ru":"Хочу понимать, что включено в предложение и что заказывать или покупать отдельно.","pronunciation":"киэ́ро энтэндэ́р кэ́ эста́ инклуи́до эн су пропуэ́ста и кэ́ тэ́нго кэ контрата́р о компра́р пор сэпара́до.","id":"d16-007"},{"speaker":"serguei","es":"Separamos las partidas, los suministros y las exclusiones, y explicamos las condiciones de precio y de plazo.","ru":"Разделим позиции, поставки и исключения, объясним условия цены и срока.","pronunciation":"сэпара́мос лас парти́дас, лос сумини́строс и лас эксклусио́нэс, и эксплика́мос лас кондисио́нэс дэ прэ́сио и дэ пла́со.","id":"d16-008"},{"speaker":"client","es":"Me interesa recibir información del avance sin tener que llamar cada día a todos los profesionales.","ru":"Хочу получать сведения о ходе работ без ежедневных звонков каждому специалисту.","pronunciation":"мэ интэрэ́са ррэсиби́р информасио́н дэл аба́нсэ син тэнэ́р кэ йама́р ка́да ди́а а то́дос лос профэсиона́лэс.","id":"d16-009"},{"speaker":"serguei","es":"Yo coordino el seguimiento y le envío las decisiones pendientes y los cambios que necesitan aprobación.","ru":"Я координирую сопровождение и отправляю нерешённые вопросы и изменения на согласование.","pronunciation":"йо коорди́но эл сэгимиэ́нто и лэ энби́о лас дэсисио́нэс пэндиэ́нтэс и лос ка́мбиос кэ нэсэси́тан апробасио́н.","id":"d16-010"},{"speaker":"client","es":"¿Hace todo usted mismo?","ru":"Вы всё делаете лично?","pronunciation":"а́сэ то́до устэ́д ми́смо?","id":"d16-011"},{"speaker":"serguei","es":"Yo coordino la obra y cada oficio interviene según el alcance y las habilitaciones necesarias.","ru":"Я координирую объект, специалисты выполняют свою часть с нужными допусками.","pronunciation":"йо коорди́но ла о́бра и ка́да офи́сио интэрбиэ́нэ сэгу́н эл алка́нсэ и лас абилитасио́нэс нэсэса́риас.","id":"d16-012"},{"speaker":"client","es":"¿Puede ejecutar el proyecto de mi diseñador?","ru":"Можете выполнить проект моего дизайнера?","pronunciation":"пуэ́дэ эхэкута́р эл пройэ́кто дэ ми дисэньадо́р?","id":"d16-013"},{"speaker":"serguei","es":"Sí, revisamos planos, detalles y materiales y coordinamos las dudas antes de ejecutar.","ru":"Да, изучим планы, узлы и материалы и уточним вопросы до выполнения.","pronunciation":"си́, ррэбиса́мос пла́нос, дэта́йэс и матэриа́лэс и координа́мос лас ду́дас а́нтэс дэ эхэкута́р.","id":"d16-014"},{"speaker":"client","es":"¿Pueden trabajar mientras estoy en el extranjero?","ru":"Можно работать, пока я за границей?","pronunciation":"пуэ́дэн трабаха́р миэ́нтрас эсто́и эн эл экстранхэ́ро?","id":"d16-015"},{"speaker":"serguei","es":"Podemos organizar informes, fotos, videollamadas y aprobaciones por escrito.","ru":"Организуем отчёты, фото, видеозвонки и письменные согласования.","pronunciation":"подэ́мос органиса́р инфо́рмэс, фо́тос, бидэойама́дас и апробасио́нэс пор эскри́то.","id":"d16-016"},{"speaker":"client","es":"¿Me garantiza que no habrá cambios?","ru":"Гарантируете отсутствие изменений?","pronunciation":"мэ гаранти́са кэ но абра́ ка́мбиос?","id":"d16-017"},{"speaker":"serguei","es":"Definimos el alcance y las comprobaciones; cualquier imprevisto se comunica y se valora antes de cambiarlo.","ru":"Определим состав и проверки; непредвиденное сообщаем и оцениваем до изменения.","pronunciation":"дэфини́мос эл алка́нсэ и лас компробасио́нэс; куалкиэ́р импрэби́сто сэ комуни́ка и сэ бало́ра а́нтэс дэ камбиа́рло.","id":"d16-018"},{"speaker":"client","es":"¿Puede empezar sin tener elegidos todos los acabados?","ru":"Можно начать без выбора всей отделки?","pronunciation":"пуэ́дэ эмпэса́р син тэнэ́р элэхи́дос то́дос лос акаба́дос?","id":"d16-019"},{"speaker":"serguei","es":"Identificamos qué decisiones bloquean cada fase y fijamos sus fechas límite.","ru":"Определим решения, которые блокируют этапы, и сроки их принятия.","pronunciation":"идэнтифика́мос кэ́ дэсисио́нэс блокэ́ан ка́да фа́сэ и фиха́мос сус фэ́час ли́митэ.","id":"d16-020"},{"speaker":"client","es":"¿Qué pasa si no entiendo un término técnico?","ru":"Что делать, если я не понимаю техническое слово?","pronunciation":"кэ́ па́са си но энтиэ́ндо ун тэ́рмино тэ́книко?","id":"d16-021"},{"speaker":"serguei","es":"Lo explico con una foto, una muestra o el plano y confirmamos que hablamos de lo mismo.","ru":"Объясню фотографией, образцом или планом и проверим одинаковое понимание.","pronunciation":"ло экспли́ко кон у́на фо́то, у́на муэ́стра о эл пла́но и конфирма́мос кэ абла́мос дэ ло ми́смо.","id":"d16-022"},{"speaker":"client","es":"¿Podemos cambiar de material durante la obra?","ru":"Можно поменять материал в процессе?","pronunciation":"подэ́мос камбиа́р дэ матэриа́л дура́нтэ ла о́бра?","id":"d16-023"},{"speaker":"serguei","es":"Comprobamos compatibilidad, pedidos, coste y plazo antes de aprobar el cambio.","ru":"До согласования проверим совместимость, заказы, стоимость и срок.","pronunciation":"компроба́мос компатибилида́д, пэди́дос, ко́стэ и пла́со а́нтэс дэ апроба́р эл ка́мбио.","id":"d16-024"},{"speaker":"client","es":"¿Quién me avisa de un problema?","ru":"Кто сообщает о проблеме?","pronunciation":"киэ́н мэ аби́са дэ ун проблэ́ма?","id":"d16-025"},{"speaker":"serguei","es":"Yo centralizo la información y le comunico el estado y las opciones.","ru":"Я собираю информацию и сообщаю статус и варианты.","pronunciation":"йо сэнтрали́со ла информасио́н и лэ комуни́ко эл эста́до и лас опсио́нэс.","id":"d16-026"},{"speaker":"client","es":"¿Cómo hacemos la entrega?","ru":"Как сдаём объект?","pronunciation":"ко́мо асэ́мос ла энтрэ́га?","id":"d16-027"},{"speaker":"serguei","es":"Con una revisión conjunta, comprobaciones, documentos y un listado de pendientes si lo hay.","ru":"Совместным осмотром, проверками, документами и списком остатков, если они есть.","pronunciation":"кон у́на ррэбисио́н конху́нта, компробасио́нэс, докумэ́нтос и ун листа́до дэ пэндиэ́нтэс си ло аи.","id":"d16-028"},{"speaker":"client","es":"¿Qué tengo que decidir ahora?","ru":"Что мне нужно решить сейчас?","pronunciation":"кэ́ тэ́нго кэ дэсиди́р ао́ра?","id":"d16-029"},{"speaker":"serguei","es":"Estas son las decisiones prioritarias y estas son sus fechas para mantener el calendario.","ru":"Вот приоритетные решения и даты для сохранения графика.","pronunciation":"э́стас сон лас дэсисио́нэс приорита́риас и э́стас сон сус фэ́час па́ра мантэнэ́р эл калэнда́рио.","id":"d16-030"},{"speaker":"client","es":"Durante la obra quiero cambiar la posición de un mueble y necesito saber si todavía podemos hacerlo.","ru":"Во время ремонта хочу поменять положение шкафа, нужно знать, возможно ли это ещё.","pronunciation":"дура́нтэ ла о́бра киэ́ро камбиа́р ла посисио́н дэ ун муэ́блэ и нэсэси́то сабэ́р си тодаби́а подэ́мос асэ́рло.","id":"d16-031"},{"speaker":"serguei","es":"Podemos estudiarlo; antes comprobamos las medidas, las instalaciones y el efecto en el coste y en el calendario.","ru":"Можем рассмотреть; сначала проверим размеры, коммуникации и влияние на стоимость и график.","pronunciation":"подэ́мос эстудиа́рло; а́нтэс компроба́мос лас мэди́дас, лас инсталасио́нэс и эл эфэ́кто эн эл ко́стэ и эн эл калэнда́рио.","id":"d16-032"},{"speaker":"client","es":"Prefiero recibir una alternativa si la primera solución resulta demasiado cara o retrasa demasiado la entrega.","ru":"Предпочитаю получить альтернативу, если первое решение слишком дорого или сильно задерживает сдачу.","pronunciation":"прэфиэ́ро ррэсиби́р у́на алтэрнати́ба си ла примэ́ра солусио́н ррэсу́лта дэмасиа́до ка́ра о ррэтра́са дэмасиа́до ла энтрэ́га.","id":"d16-033"},{"speaker":"serguei","es":"Le explico las opciones comprobadas y dejamos la decisión por escrito antes de ejecutar el cambio.","ru":"Объясню проверенные варианты и письменно зафиксируем решение до выполнения изменения.","pronunciation":"лэ экспли́ко лас опсио́нэс компроба́дас и дэха́мос ла дэсисио́н пор эскри́то а́нтэс дэ эхэкута́р эл ка́мбио.","id":"d16-034"},{"speaker":"client","es":"Al terminar quiero revisar juntos el resultado y entender qué documentación y mantenimiento necesita cada equipo.","ru":"В конце хочу вместе проверить результат и понять документы и обслуживание каждого прибора.","pronunciation":"ал тэрмина́р киэ́ро ррэбиса́р ху́нтос эл ррэсулта́до и энтэндэ́р кэ́ докумэнтасио́н и мантэнимиэ́нто нэсэси́та ка́да эки́по.","id":"d16-035"},{"speaker":"serguei","es":"Organizamos la revisión conjunta y anotamos los pendientes, las responsabilidades y las fechas que acordemos.","ru":"Организуем совместный осмотр и запишем остатки, ответственных и согласованные даты.","pronunciation":"органиса́мос ла ррэбисио́н конху́нта и анота́мос лос пэндиэ́нтэс, лас ррэспонсабилида́дэс и лас фэ́час кэ акордэ́мос.","id":"d16-036"},{"speaker":"client","es":"¿Y si después aparece una incidencia o veo un punto que necesita una comprobación adicional?","ru":"А если позже возникнет проблема или замечу место, требующее дополнительной проверки?","pronunciation":"и си дэспуэ́с апарэ́сэ у́на инсидэ́нсиа о бэ́о ун пу́нто кэ нэсэси́та у́на компробасио́н адисиона́л?","id":"d16-037"},{"speaker":"serguei","es":"Indíquenos el punto y envíe una foto para organizar la revisión y confirmar la actuación que corresponda.","ru":"Укажите место и пришлите фото для организации осмотра и определения нужных действий.","pronunciation":"инди́кэнос эл пу́нто и энби́э у́на фо́то па́ра органиса́р ла ррэбисио́н и конфирма́р ла актуасио́н кэ коррэспо́нда.","id":"d16-038"},{"speaker":"client","es":"De acuerdo, quiero que las decisiones se basen en datos confirmados y que todo quede claro por escrito.","ru":"Хорошо, хочу решения на основе подтверждённых данных и понятную письменную фиксацию.","pronunciation":"дэ акуэ́рдо, киэ́ро кэ лас дэсисио́нэс сэ ба́сэн эн да́тос конфирма́дос и кэ то́до кэ́дэ кла́ро пор эскри́то.","id":"d16-039"},{"speaker":"serguei","es":"Ese es el criterio: distinguimos lo que sabemos, lo que parece y lo que todavía necesitamos comprobar.","ru":"Это и есть принцип: различаем известное, предположительное и то, что ещё нужно проверить.","pronunciation":"э́сэ эс эл критэ́рио: дистинги́мос ло кэ сабэ́мос, ло кэ парэ́сэ и ло кэ тодаби́а нэсэсита́мос компроба́р.","id":"d16-040"}],"words":525,"minutes":5}];
